insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1CH',1,1,null,$b$Y-Ađam mbơ̆ Y-Set, Y-Set mbơ̆ Y-Ênôs;$b$,true),
('bunong-vn','1CH',1,2,null,$b$Y-Ênôs mbơ̆ Y-Kênan mbơ̆ Y-Mahalalel, Y-Mahalalel mbơ̆ Y-Jaret, Y-Jaret mbơ̆ Y-Ênok;$b$,false),
('bunong-vn','1CH',1,3,null,$b$Y-Ênŏk mbơ̆ Y-Mêthusêla, Y-Mêthusêla mbơ̆ Y-Lamek, Y-Lamek mbơ̆ Y-Nôê,$b$,false),
('bunong-vn','1CH',1,4,null,$b$Y-Nôê mbơ̆ Y-Sem, Y-Cham Jêh ri Y-Japhet.$b$,false),
('bunong-vn','1CH',1,5,null,$b$Phung kon bu klâu Y-Japhet: Y-Gômer, Y-Magôk, Y-Madai, Y-Javan, Y-Tubal, Y-Mêsek, jêh ri Y-Tiras.$b$,true),
('bunong-vn','1CH',1,6,null,$b$Phung kon bu klâu Y-Gômer: Y-Askênas, Y-Riphat jêh ri Y-Tôgar ma.$b$,false),
('bunong-vn','1CH',1,7,null,$b$Phung kon bu klâu Y-Javan: Y-Êlisa, Y-Tarsis, Y-Kitim, jêh ri Y-Rôdanim$b$,false),
('bunong-vn','1CH',1,8,null,$b$Phung kon bu klâu Y-Cham: Y-Kus, Y-Mitraim, Y-Put jêh ri Y-Kanaan.$b$,false),
('bunong-vn','1CH',1,9,null,$b$Phung kon bu klâu Y-Kus: Y-Sêba, Y-Havila, Y-Sapta, Y-Rama jêh ri Y-Saptêka. Phung kon bu klâu Y-Rama: Y-Sêba, jêh ri Y-Dêdan$b$,true),
('bunong-vn','1CH',1,10,null,$b$Y-Kus jêng mbơ̆ ma Y-Nimrôt; păng ntơm jêng janh ktang ta neh ntu.$b$,false),
('bunong-vn','1CH',1,11,null,$b$Y-Mitraim luh mpôl Y-Ludim, mpôl Y-Anamim, mpôl Y-Lêhabim, mpôl Y-Nap tuhim$b$,false),
('bunong-vn','1CH',1,12,null,$b$mpôl Y-Patrusim, mpôl Y-Kasluhim, (tă bơh nây luh phung Philistin), jêh ri Y-Kaptêrim$b$,false),
('bunong-vn','1CH',1,13,null,$b$Y-Kanaan mbơ̆ ma Y-Sidôn kon păng deh bôk rah, jêh ri Y-Het$b$,false),
('bunong-vn','1CH',1,14,null,$b$n'hanh phung Jêbusit, phung Amôrit, phung Girgasit,$b$,false),
('bunong-vn','1CH',1,15,null,$b$phung Hivit, phung Arkit, phung Sinit,$b$,false),
('bunong-vn','1CH',1,16,null,$b$phung Arvadit, phung Sêmarit, jêh ri phung Hamatit.$b$,false),
('bunong-vn','1CH',1,17,null,$b$Phung kon bu klâu Y-Sem: Y-Êlam, Y-Asur, Y-Arpaksat, Y-Lut, Y-Aram, Y-Us, Y-Hul, Y-Gêther, jêh ri Y-Mêsek.$b$,false),
('bunong-vn','1CH',1,18,null,$b$Y-Arpaksat jêng mbơ̆ ma Y-Sêla, Y-Sêla mbơ̆ ma Y-Êber.$b$,true),
('bunong-vn','1CH',1,19,null,$b$Y-Êber geh bar hê kon bu klâu: Amoh du huê Y-Pêlek (yor lah tâm rô̆ nây neh bu hŏ tâm pă jêh); bi oh păng amoh jêng Y-Jôktan.$b$,false),
('bunong-vn','1CH',1,20,null,$b$Y-Jôktan jêng mbơ̆ ma Y-Almôdat, Y-Sêlep, Y-Hasar mavet, Y-Jêra,$b$,false),
('bunong-vn','1CH',1,21,null,$b$Y-Hadôram, Y-Usal, Y-Dikla,$b$,false),
('bunong-vn','1CH',1,22,null,$b$Y-Êbal Y-Abi maêl, Y-Sêba,$b$,false),
('bunong-vn','1CH',1,23,null,$b$Y-Ôphir, Y-Havila, jêh ri Y-Jôhap, lĕ rngôch phung nây jêng phung kon bu klâu Y-Jôktan.$b$,false),
('bunong-vn','1CH',1,24,null,$b$Y Sem jêng mbơ̆ ma Y-Arpaksat, Y-Arpaksat jêng mbơ̆ ma Y-Sêla, Y-Sêla jêng mbơ̆ ma Y-Êber.$b$,true),
('bunong-vn','1CH',1,25,null,$b$Y-Êber jêng mbơ̆ ma Y-Pêlek, Y-Pêlek jêng mbơ̆ ma Y-Rêu,$b$,false),
('bunong-vn','1CH',1,26,null,$b$Y-Rêu jêng mbơ̆ ma Y-Sêruk, Y-Sêruk jêng mbơ̆ ma Y-Nahor, Y-Nahor jêng mbơ̆ ma Y-Têra, Y-Têra jêng mbơ̆ ma Y-Abram,$b$,false),
('bunong-vn','1CH',1,27,null,$b$Y-Abram bu ntơ amoh tay Y-Abraham.$b$,false),
('bunong-vn','1CH',1,28,null,$b$Phung kon bu klâu Y-Abraham: Y-Isăk, jêh ri Y-Ismaêl.$b$,true),
('bunong-vn','1CH',1,29,null,$b$Aơ phung kon sau khân păng: Kon bôk rah Y-Ismaêl jêng Y-Nêbalôt; jêh ta nây Y-Kêdar, Y-Atbêel, Y-Mip sam,$b$,false),
('bunong-vn','1CH',1,30,null,$b$Y-Misma, Y-Duma, Y-Masa, Y-Hadat, Y-Têma,$b$,false),
('bunong-vn','1CH',1,31,null,$b$Y-Jêtur, Y-Napis, jêh ri Y-Kêdêma. Nây phung kon bu klâu Y-Ismaêl.$b$,false),
('bunong-vn','1CH',1,32,null,$b$Phung kon bu klâu H'Kêtura, ur yông Y-Abraham: Păng deh ma Y-Simran, Y-Jôksan, Y-Mêdan, Y-Madian, Y-Isbak, jêh ri Y-Sua.$b$,false),
('bunong-vn','1CH',1,33,null,$b$Phung kon bu klâu Y-Jôksan: Y-Sêba jêh ri Y-Dêdan. Phung kon bu klâu Y-Madian: Y-Êlda, Lĕ rngôch phung nây jêng kon bu klâu H'Kêtura.$b$,false),
('bunong-vn','1CH',1,34,null,$b$Y-Abraham jêng mbơ̆ ma Y-Isăk. Phung kon bu klâu Y-Isăk: Y-Êsau jêh ri Y-Israel.$b$,true),
('bunong-vn','1CH',1,35,null,$b$Phung kon bu klâu Y-Êsau: Y-Êlipas, Y-Rêuel, Y-Jêus, Y-Jalam, jêh ri Y-Kôra.$b$,true),
('bunong-vn','1CH',1,36,null,$b$Phung kon bu klâu Y-Êlipas: Y-Têman, na, jêh ri Y-Amalek.$b$,true),
('bunong-vn','1CH',1,37,null,$b$Phung kon bu klâu Y-Rêuel: Y-Nahat, Y-Sêra, Y-Sama, jêh ri Y-Misa.$b$,false),
('bunong-vn','1CH',1,38,null,$b$Phung kon bu klâu Y-Sêir: Y-Lôtan Y-Sôbal, Y-Sip kon, Y-Ana, Y-Disôn, Y-Êser, jêh ri Y-Disan.$b$,false),
('bunong-vn','1CH',1,39,null,$b$Phung kon bu klâu Y-Lôtan: Y-Hôri Jêh ri Y-Hômam; jêh nây oh bu ur Y-Lôtan jêng H'Timna.$b$,false),
('bunong-vn','1CH',1,40,null,$b$Phung kon bu- klâu Y-Sôbal: Y-Alian, Y-Manahat, Y-Êbal, Y-Sêphi, jêh ri Y-Ônam. Phung kon bu klâu Y-Sibêôn: Y-Aiya, jêh ri Y-Ana.$b$,false),
('bunong-vn','1CH',1,41,null,$b$Phung kon bu klâu Y-Ana: Y-Disôn. Phung kon bu klâu Y-Disôn: Y-Hamran, Y-Êsban, Y-Itram, jêh ri Y-Kêran.$b$,false),
('bunong-vn','1CH',1,42,null,$b$Phung kon bu klâu Y-Êser: Y-Bilham, Y-Savan, jêh ri Y-Jakan. Phung kon bu klâu Y-Disan: Y-Us jêh ri Y-Aran.$b$,false),
('bunong-vn','1CH',1,43,null,$b$Nôk sa ơm phung Israel mâu geh ôh du huê hađăch chiă uănh, pô ri aơ jêng amoh săk phung hađăch chiă uănh n'gor Êđôm: Y-Bêla kon bu klâu Y-Bêôr, amoh ƀon păng jêng Dinhaba.$b$,true),
('bunong-vn','1CH',1,44,null,$b$Tơ lah Y-Bêla khĭt, Y-Jôbap kon bu klâu Y-Sêra, tă bơh ƀon Bôsra chiă uănh thoi păng.$b$,false),
('bunong-vn','1CH',1,45,null,$b$Tơ lah Y-Jôbap khĭt, Y-Husam tă bơh n'gor Têman chiă uănh thoi păng.$b$,false),
('bunong-vn','1CH',1,46,null,$b$Tơ lah Y-Husam khĭt, Y-Hadat kon bu klâu Y-Bêdat, nơm hŏ dơi jêh đah phung Madian tâm n'gor Môap chiă uănh thoi păng; jêh ri ƀon păng jêng Avit.$b$,false),
('bunong-vn','1CH',1,47,null,$b$Tơ lah Y-Hadat khĭt, Y-Samla tă bơh ƀon Masrêka chiă uănh thoi păng.$b$,false),
('bunong-vn','1CH',1,48,null,$b$Tơ lah Y-Samla khĭt, Y-Saul tă bơh ƀon Rêhôbôt ta kơh dak krong Ơphrat chiă uănh thoi păng.$b$,false),
('bunong-vn','1CH',1,49,null,$b$Tơ lah Y-Saul khĭt, Y-Baal-Hanan kon bu klâu Y-Akbôr chiă uănh thoi păng.$b$,false),
('bunong-vn','1CH',1,50,null,$b$Tơ lah Y-Baal-Hanan khĭt, Y-Hadat chiă uănh thoi păng; Jêh ri amoh ƀon păng jêng Pai, jêh ri ur păng jêng H'Mêhetabel kon bu ur H'Matret, Sau Y-Mêsahap.$b$,true),
('bunong-vn','1CH',1,51,null,$b$Jêh ri Y-Hadat khĭt. Phung Kôranh n'gor Êđôm geh: Y-Timna, Y-Alia, Y-Jêtet,$b$,false),
('bunong-vn','1CH',1,52,null,$b$Y-Ôhô Libama, Y-Êla, Y-Pinôn.$b$,false),
('bunong-vn','1CH',1,53,null,$b$Y-Kênas, Y-Têman, Y-Mip sar,$b$,false),
('bunong-vn','1CH',1,54,null,$b$Y-Mak diêl, jêh ri Y-Iram; Phung nây jêng phung kôranh n'gor Êđôm.$b$,false),
('bunong-vn','1CH',2,1,null,$b$Phung aơ jêng phung kon bu klâu Y-Israel: Y-Ruben, Y-Simêôn, Y-Lêvi, Y-Yuđa, Y-Isakar, Y-Sabulôn,$b$,true),
('bunong-vn','1CH',2,2,null,$b$Y-Dan, Y-Yôsep, Y-Benjamin, Y-Naptali, Y-Gat jêh ri Y-Aser.$b$,false),
('bunong-vn','1CH',2,3,null,$b$Phung kon sau Y-Yuđa: Y-Er, Y-Ônan, jêh ri Y-Sêla; phung pe nuyh nây bơh H'Batsua bu ur Kanaan deh ăn păng. Y-Er, kon bôk rah Y-Yuđa, păng ƀư nau djơh ta năp măt Yêhôva, yor ri Yêhôva nkhĭt păng.$b$,true),
('bunong-vn','1CH',2,4,null,$b$H'Tama jêng ƀăn Y-Yuđa, tâm ban đŏng deh ăn păng Y-Pêres jêh ri Y-Sêra. Y-Yuđa geh lĕ rngôch prăm kon bu klâu.$b$,false),
('bunong-vn','1CH',2,5,null,$b$Kon bu klâu Y-Pêres jêng Y-Hêsron jêh ri Y-Hamuh.$b$,false),
('bunong-vn','1CH',2,6,null,$b$Phung kon bu klâu Y-Sêra: Y-Simri, Y-Êthan, Y-Hêman, Y-Kalkôl, Y-Dara, prăm nuyh lĕ rngôch.$b$,false),
('bunong-vn','1CH',2,7,null,$b$Phung kon bu klâu Y-Karmi: Y-Akar nơm ƀư rŭng Israel, nơm tih jêh đah ndơ prăp ăn ma Yêhôva;$b$,false),
('bunong-vn','1CH',2,8,null,$b$jêh ri kon bu klâu Y-Êthan jêng Y-Asaria.$b$,false),
('bunong-vn','1CH',2,9,null,$b$Phung kon bu klâu Y-Hêsron bu deh ăn păng: Y-Jêrahmel, Y-Ram, jêh ri Y-Kêlubai.$b$,false),
('bunong-vn','1CH',2,10,null,$b$Y-Ram jêng mbơ̆ ma Y-Aminadap jêh ri Y-Aminadap jêng mbơ̆ ma Y-Nahsôn, kôranh ma phung mpôl Y-Yuđa.$b$,false),
('bunong-vn','1CH',2,11,null,$b$Y-Nahsôn jêng mbơ̆ ma Y-Salma. Y-Salma jêng mbơ̆ ma Y-Bôas,$b$,false),
('bunong-vn','1CH',2,12,null,$b$Y-Bôas jêng mbơ̆ ma Y-Ôbet, Y-Ôbet jêng mbơ̆ ma Y-Yêsê.$b$,false),
('bunong-vn','1CH',2,13,null,$b$Y-Yêsê jêng mbơ̆ ma Y-Êliap, kon păng bôk rah, Y-Aminadap jêng kon rơh bar, Y-Simên jêng kon rơh pe,$b$,false),
('bunong-vn','1CH',2,14,null,$b$Y-Nêthanel kon rơh puăn, Y-Radai kon rơh prăm,$b$,false),
('bunong-vn','1CH',2,15,null,$b$Y-Ôsem kon rơh prao, Y-Đavit kon rơh pơh;$b$,false),
('bunong-vn','1CH',2,16,null,$b$jêh ri oh bu ur khân păng geh H'Sêruia jêh ri H'Abigêl. Phung kon bu klâu H'Sêruia: Y-Abisai, Y-Jôap jêh ri Y-Asahel, pe nuyh.$b$,false),
('bunong-vn','1CH',2,17,null,$b$H'Abigêl deh ma Y-Amasa, jêh ri mbơ̆ ma Y-Amasa jêng Y-Jêther bu klâu Israel.$b$,true),
('bunong-vn','1CH',2,18,null,$b$Y-Kalep kon bu klâu Y-Hêsron geh kon đah ur păng H'Asuba jêh ri đah H'Jêriôt; jêh ri aơ jêng phung kon bu klâu H'Asuba deh: Y-Jêser, Y-Sôbap, jêh ri Y-Ardôn.$b$,true),
('bunong-vn','1CH',2,19,null,$b$Tơ lah H'Asuba khĭt, Y-Kalep gŭ H'Êprat, păng deh ma Y-Hur,$b$,false),
('bunong-vn','1CH',2,20,null,$b$Y-Hur jêng mbơ̆ ma Y-Uri, jêh ri Y-Uri jêng mbơ̆ ma Y-Bêsalet.$b$,false),
('bunong-vn','1CH',2,21,null,$b$Jêh ta nây, tơ lah Y-Hêsron geh jêh prao jât năm, păng gŭ ur đah kon bu ur Y-Makir, mbơ̆ Y-Galaat; jêh ri ô băl deh ăn păng Y-Sêgup;$b$,false),
('bunong-vn','1CH',2,22,null,$b$jêh ri Y-Sêgup jêng mbơ̆ ma Y-Jar, nơm geh bar jât ma pe rplay ƀon toyh tâm n'gor Galaat.$b$,false),
('bunong-vn','1CH',2,23,null,$b$Ƀiă lah phung Gêsur jêh ri phung Siri pit in bơh khân păng ƀon Havôt-Jar, ƀon Kênat, jêh ri ndrel prao jât ƀon jê̆ jê̆. Lĕ rngôch phung nây jêng kon sau Y-Makir, mbơ̆ Y-Galaat.$b$,false),
('bunong-vn','1CH',2,24,null,$b$Jêh Y-Hêsron khĭt tâm ƀon Kalep Êprata, H'Abija ur Y-Hêsron deh ma păng Y-Asur, mbơ̆ Y-Têkôa.$b$,false),
('bunong-vn','1CH',2,25,null,$b$Phung kon bu klâu Y-Jêrahmel, kon bôk rah ma Y-Hêsron: Y-Ram kon dak bôk, Y-Buna, Y-Ôren, Y-Ôsem, jêh ri Y-Ahija.$b$,true),
('bunong-vn','1CH',2,26,null,$b$Y-Jêrahmel geh ur êng đŏng, amoh păng H'Atara; păng jêng mê̆ ma Y-Ônam.$b$,true),
('bunong-vn','1CH',2,27,null,$b$Phung kon bu klâu Y-Ram, kon bôk rah Y-Jêrahmel: Y-Mas, Y-Jamin, jêh ri Y-Êker.$b$,true),
('bunong-vn','1CH',2,28,null,$b$Phung kon bu klâu Y-Ônam: Y-Samai jêh ri Y-Jada. Phung kon bu klâu Y-Samai: Y-Nadap, jêh ri Y-Abisur.$b$,true),
('bunong-vn','1CH',2,29,null,$b$Amoh ur Y-Abisur jêng H'Abihel, jêh ri Ô băl deh ma păng: Y-Ahban jêh ri Y-Môlit.$b$,false),
('bunong-vn','1CH',2,30,null,$b$Phung kon bu klâu Y-Nadap: Y-Sêlet jêh ri Y-Apaim; jêh ri Y-Sêlet khĭt mâu geh kon ôh.$b$,false),
('bunong-vn','1CH',2,31,null,$b$Phung kon bu klâu Y-Paim: Y-Isi. Phung kon bu klâu Y-Isi: Y-Sêsan. Phung kon bu klâu Y-Sêsan: Y-Ahlai.$b$,false),
('bunong-vn','1CH',2,32,null,$b$Phung kon bu klâu Y-Jada, oh Y-Samai: Y-Jêther jêh ri Y-Jônathan; jêh nây Y-Jêther khĭt mâu geh kon ôh.$b$,false),
('bunong-vn','1CH',2,33,null,$b$Phung kon bu klâu Y-Jônathan: Y-Pêlet jêh ri Y-Sasa. Nây jêng phung kon sau Y-Jêrahmel.$b$,false),
('bunong-vn','1CH',2,34,null,$b$Y-Sêsan mâu geh ôh kon bu klâu, knŏng phung kon bu ur; ƀiă lah Y-Sêsan geh du huê dĭk Êjipt, amoh păng Y-Jarha.$b$,true),
('bunong-vn','1CH',2,35,null,$b$Pô ri Y-Sêsan ăn kon bu ur păng jêng ur Y-Jarha dĭk păng; jêh ri ô băl deh ma păng Y-Atai.$b$,false),
('bunong-vn','1CH',2,36,null,$b$Y-Atai jêng mbơ̆ ma Y-Nathan, jêh ri Y-Nathan jêng mbơ̆ ma Y-Saƀat.$b$,true),
('bunong-vn','1CH',2,37,null,$b$Y-Saƀat jêng mbơ̆ ma Y-Êphal, jêh ri Y-Êphal jêng mbơ̆ ma Y-Ôbet.$b$,false),
('bunong-vn','1CH',2,38,null,$b$Y-Ôbet jêng mbơ̆ ma Y-Jêhu, jêh ri Y-Jêhu jêng mbơ̆ ma Y-Asaria.$b$,false),
('bunong-vn','1CH',2,39,null,$b$Y-Asaria jêng mbơ̆ ma Y-Hêles, jêh ri Y-Hêles jêng mbơ̆ ma Y-Êlêasa.$b$,true),
('bunong-vn','1CH',2,40,null,$b$Y-Êlêasa jêng mbơ̆ ma Y-Sis mai, jêh ri Y-Sis mai jêng mbơ̆ ma Y-Salum.$b$,false),
('bunong-vn','1CH',2,41,null,$b$Y-Salum jêng mbơ̆ ma Y-Jêkamia, jêh ri Y-Jêkamia jêng mbơ̆ ma Y-Êlisama.$b$,false),
('bunong-vn','1CH',2,42,null,$b$Phung kon bu klâu Y-Kalep oh Y-Jêrahmel: Y-Marêsa kon păng bôk rah, nơm jêng mbơ̆ ma Y-Sip. Phung kon bu klâu Y-Marêsa: Y-Hêbron.$b$,false),
('bunong-vn','1CH',2,43,null,$b$Phung kon bu klâu Y-Hêbron: Y-Kôra, Y-Tapua, Y-Rêkem, jêh ri Y-Sêma.$b$,false),
('bunong-vn','1CH',2,44,null,$b$Y-Sêma jêng mbơ̆ ma Y-Raham, Y-Raham jêng chô che ma Y-Jôrkêam, bi Y-Rêkem jêng mbơ̆ ma Y-Samai.$b$,false),
('bunong-vn','1CH',2,45,null,$b$Kon bu klâu Y-Samai: Y-Ma ôn; jêh ri Y-Ma ôn jêng mbơ̆ ma Y-Betsur.$b$,false),
('bunong-vn','1CH',2,46,null,$b$Ur yông Y-Kalep H'Êphas tâm ban đŏng deh ma Y-Haran, Y-Môsa, jêh ri Y-Gasês; jêh ri Y-Haran jêng mbơ̆ ma Y-Gasês.$b$,false),
('bunong-vn','1CH',2,47,null,$b$Phung kon bu klâu Y-Jahdi: Y-Rêgem, Y-Jôtham, Y-Gêsan, Y-Pêlet, Y-Êpha, jêh ri Y-Sap.$b$,false),
('bunong-vn','1CH',2,48,null,$b$H'Maka ur yông Y-Kalep deh ma Y-Sêber jêh ri Y-Tir hana.$b$,false),
('bunong-vn','1CH',2,49,null,$b$Ô băl deh đŏng ma Y-Sap, mbơ̆ ma Y-Madmana, mbơ̆ ma Y-Sêra mbơ̆ ma Y-Mak bêna jêh ri mbơ̆ ma Y-Gibêa; jêh ri H'Aksa jêng kon bu ur Y-Kalep.$b$,false),
('bunong-vn','1CH',2,50,null,$b$Nây jêng phung kon sau Y-Kalep. Phung kon bu klâu Y-Hur kon bôk rah ma H'Êphrata: Y-Sôbal mbơ̆ ma Y-Kiriat-Jêarim,$b$,false),
('bunong-vn','1CH',2,51,null,$b$Y-Salma mbơ̆ ma Y-Betlêhem, jêh ri Y-Harep mbơ̆ ma Y-Bet-Gader.$b$,false),
('bunong-vn','1CH',2,52,null,$b$Y-Sôbal, chô che ma Y-Kiriat- Jêarim geh phung kon bu klâu; Y-Harôê jêh ri du n'gul mpôl Mênuhôt.$b$,false),
('bunong-vn','1CH',2,53,null,$b$Phung noi deh Y-Kiriatjêarim: Phung Itri, phung Put, phung Sumat, jêh ri phung Misra; bơh phung nây luh du phung Sôra jêh ri phung Astaôl.$b$,false),
('bunong-vn','1CH',2,54,null,$b$Phung kon bu klâu Y-Sal ma: Y-Betlêhem, phung Nêtôphat, phung Atrôt- Bet-Jôap, jêh ri du n'gul phung Manahat, phung Sôra.$b$,false),
('bunong-vn','1CH',2,55,null,$b$Geh tâm ban đŏng phung mpôl phung blau chih sămƀŭt gŭ ta ƀon Jabes; phung Tirat, phung Simêat, jêh ri phung Sukat. Phung nây jêng phung Kênit luh bơh Y-Hamat, chô yau ma ngih Rêkap.$b$,false),
('bunong-vn','1CH',3,1,null,$b$Aơ jêng phung kon bu klâu Y-Đavit bu deh ma păng tâm ƀon Hêbron: Kon bôk rah jêng Y-Amnôn, păng geh ô băl đah H'Ahi nôam, bơh phung mpôl Jesrêel; kon rơh bar jêng Y-Daniel, păng geh ô băl đah H'Abigiêl bu ur bơh ƀon Karmel.$b$,true),
('bunong-vn','1CH',3,2,null,$b$Kon rơh pe, Y-Apsalôm, mê̆ ô băl jêng H'Maka, kon bu ur Y-Talmai, hađăch n'gor Gêsur; kon rơh puăn Y-Adônija mê̆ ô băl jêng H'Hagit;$b$,false),
('bunong-vn','1CH',3,3,null,$b$kon rơh prăm jêng Y-Sêpatia, păng geh ô băl đah H'Abital; kon rơh prao Y-Itrêam đah ur păng H'Êgla;$b$,false),
('bunong-vn','1CH',3,4,null,$b$bu deh ăn păng prao nuyh tâm ƀon Hêbrôn, ta nây păng jêng hađăch chiă uănh dôl pơh năm prao khay. Jêh ri păng chiă uănh pe jât ma pe năm tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',3,5,null,$b$Phung aơ bu deh ăn păng ta ƀon Yêrusalem: Y-Simêa, Y-Sôbap, Y-Nathan jêh ri Y-Salômôn, puăn nuyh đah H'Batsua kon bu ur Y-Amiêl;$b$,false),
('bunong-vn','1CH',3,6,null,$b$jêh ri Y-Iphar, Y-Êlisama, Y-Êliphêlet,$b$,false),
('bunong-vn','1CH',3,7,null,$b$Y-Nôga, Y-Nêphek, Y-Japhia,$b$,false),
('bunong-vn','1CH',3,8,null,$b$Y-Êlisama, Y-Êliada, jêh ri Y-Êliphêlet, sĭn nuyh.$b$,false),
('bunong-vn','1CH',3,9,null,$b$Lĕ rngôch phung nây jêng kon bu klâu Y-Đavit rmeh ma kon bu klâu đah ur yông; jêh ri H'Tamar jêng oh bu ur khân păng.$b$,false),
('bunong-vn','1CH',3,10,null,$b$Phung kon bu klâu Y-Salômôn: Y-Rôbôam, Y-Abija, Y-Asa, Y-Jôsaphat,$b$,true),
('bunong-vn','1CH',3,11,null,$b$Y-Jôram, Y-Abasia, Y-Jôas,$b$,false),
('bunong-vn','1CH',3,12,null,$b$Y-Amasia, Y-Asaria, Y-Jôtham,$b$,false),
('bunong-vn','1CH',3,13,null,$b$Y-Ahas, Y-Hêsêkia, Y-Manasê,$b$,false),
('bunong-vn','1CH',3,14,null,$b$Y-Amôn, Y-Jôsia.$b$,false),
('bunong-vn','1CH',3,15,null,$b$Phung kon bu klâu Y-Jôsia: Y-Jôhanan kon bôk rah, Y-Jêhôjakim kon rơh bar, Y-Sêdêkia kon rơh pe, Y-Salum kon rơh puăn.$b$,false),
('bunong-vn','1CH',3,16,null,$b$Phung kon bu klâu Y-Jêhôjakim: Y-Jêkônia, Y-Sêdêkia;$b$,false),
('bunong-vn','1CH',3,17,null,$b$jêh ri phung kon bu klâu Y-Jêkônia nơm jêng bu nă: Y-Sêaltiêl,$b$,false),
('bunong-vn','1CH',3,18,null,$b$Y-Malkiram, Y-Pêdaya, Y-Sênasar, Y-Jêkamia, Y-Hôsama, jêh ri Y-Nêdabia;$b$,false),
('bunong-vn','1CH',3,19,null,$b$jêh ri phung kon bu klâu Y-Pêdaya: Y-Sêrubabet jêh ri Y-Simei; jêh ri phung kon bu klâu Y-Sêrubabel: Y-Mêsulam jêh ri Y-Hanania, jêh ri H'Sêlômit jêng oh bu ur khân păng;$b$,false),
('bunong-vn','1CH',3,20,null,$b$jêh ri Y-Hasuba, Hêset, prăm nuyh.$b$,false),
('bunong-vn','1CH',3,21,null,$b$Phung kon bu klâu Y-Hanania: Y-Pêlatia, jêh ri Y-Pêsaya, Y-Rêphaya, Y-Arnan, Y-Ôbadia, Y-Sêkania.$b$,false),
('bunong-vn','1CH',3,22,null,$b$Kon bu klâu Y-Sêkania: Y-Sêmana. Phung kon bu klâu Y-Sêmaya: Y-Hatus, Y-Igal, Y-Baria, Y-Nêaria, jêh ri Y-Saphat, prao nuyh.$b$,true),
('bunong-vn','1CH',3,23,null,$b$Kon bu klâu Nêraria, Ê-li-ô-ê-nai, Êxêchia, jêh ri A-ri-kham, pe nuyh.$b$,false),
('bunong-vn','1CH',3,24,null,$b$Phung kon bu klâu Y-Êliônai: Y-Hôdavia, Y-Êliasip, Y-Pôlaya, Y-Akup, Y-Jôhanan, Y-Dêlaya, jêh ri Y-Anani, pơh nuyh.$b$,false),
('bunong-vn','1CH',4,1,null,$b$Phung kon bu klâu Y-Yuđa: Y-Pêres, Y-Hêsron, Y-Kar mi, Y-Hur jêh ri Y-Sôbal.$b$,true),
('bunong-vn','1CH',4,2,null,$b$Y-Rê aya kon bu klâu Y-Sôbal jêng mbơ̆ ma Y-Jahat, jêh ri Y-Jahat jêng mbơ̆ ma Y-Ahumai jêh ri Y-Jahat, jêh ri Y-Jahat jêng mbơ̆ ma Y-Ahumai jêh ri Y-Lahat. Nây jêng phung mpôl Sôrat.$b$,false),
('bunong-vn','1CH',4,3,null,$b$Aơ jêng phung kon sau Y-Êtam: Y-Jêrêel, Y-Isma, jêh ri Y-Itbas; jêh ri oh bu ur khân păng jêng H'Hasêlêlpôni,$b$,true),
('bunong-vn','1CH',4,4,null,$b$jêh ri Y-Pênuel jêng mbơ̆ ma Y-Gêdôr, jêh ri Y-Êser jêng mbơ̆ ma Y-Husa. Aơ phung kon bu klâu Y-Hur, kon bôk rah Y-Êphrata mbơ̆ Y-Betlêhem.$b$,false),
('bunong-vn','1CH',4,5,null,$b$Y-Asur mbơ̆ Y-Têkôa, geh bar hê ur, H'Hêla jêh ri H'Nara.$b$,false),
('bunong-vn','1CH',4,6,null,$b$H'Nara deh ăn păng Y-Ahusam, Y-Hêpher, Y-Têmêni, jêh ri Y-Hahastari. Nây jêng phung kon bu klâu H'Nara.$b$,false),
('bunong-vn','1CH',4,7,null,$b$Phung kon bu klâu H'Hêla: Y-Sêret, Y-Sôhar, Y-Êtnan,$b$,false),
('bunong-vn','1CH',4,8,null,$b$Y-Kôs jêng mbơ̆ ma Y-Anup, Y-Sôbêba, jêh ri phung mpôl Aharhel kon bu klâu Y-Harum.$b$,false),
('bunong-vn','1CH',4,9,null,$b$Y-Jabes geh nau bu yơk lơn ma phung oh nâu păng; jêh ri mê̆ păng ntơ amoh păng Y-Jabes, lah, “Yor lah gâp deh ma păng đah nau ji.”$b$,false),
('bunong-vn','1CH',4,10,null,$b$Y-Jabes kuăl mbơh sơm ma Brah Ndu Israel, lah, “Lơi dĭng may mâu ăn ôh ma gâp nau ueh lăng, pơk an huy n'har bri gâp; jêh ri dăn ti may sâm king gâp, gay ma may mra chiă uănh gâp bơh nau mhĭk gay ma nau nây lơi tât ôh ma gâp!” Brah Ndu ăn ma păng nau păng dăn jêh.$b$,true),
('bunong-vn','1CH',4,11,null,$b$Y-Kêlup oh Y-Suah jêng mbơ̆ ma Y-Mêhir, nơm jêng mbơ̆ ma Y-Êstôn.$b$,false),
('bunong-vn','1CH',4,12,null,$b$Y-Êstôn jêng mbơ̆ ma Y-Betrapa, Y-Pasêa, jêh ri Y-Têhina mbơ̆ Y-Irnahas. Nây phung oh Y-Rêka.$b$,false),
('bunong-vn','1CH',4,13,null,$b$Phung kon bu klâu Y-Kênas: Y-Ôtniêl jêh ri Y-Sêraya; jêh ri phung kon bu klâu Y-Ôtniêl: Y-Hatat jêh ri Y-Mêônôthai.$b$,false),
('bunong-vn','1CH',4,14,null,$b$Y-Mêônôthai jêng mbơ̆ ma Y-Ôphra; jêh ri Y-Sêraya jêng mbơ̆ ma Y-Jôap, chô che Y-Gêharasim phung khân păng gŭ tâm rlŭng trah chap meh bu ntơ pô nây yor lah khân păng jêng phung blau kan.$b$,false),
('bunong-vn','1CH',4,15,null,$b$Phung kon bu klâu Y-Kalep, kon bu klâu Y-Jêphunê: Y-Iru, Y-Êla, jêh ri Y-Nam; jêh nây phung kon bu klâu Y-Êla: Y-Kênas.$b$,false),
('bunong-vn','1CH',4,16,null,$b$Phung kon bu klâu Y-Jahalel: Y-Sip, Y-Sipa, Y-Tiria, jêh ri Y-Asarel.$b$,false),
('bunong-vn','1CH',4,17,null,$b$Phung kon bu klâu Y-Êsra: Y-Jêther, Y-Mêret, Y-Êpher, jêh ri Y-Jalôn. Phung aơ jêng kon bu klâu H'Bitia kon bu ur hađăch Pharaôn, jêng ur ma Y-Mêret. Păng ntreo jêh ri deh ma Y-Miriam, jêh ri Y-Isba mbơ̆ Y-Êstêmôa.$b$,false),
('bunong-vn','1CH',4,18,null,$b$Ur păng jêng du huê Yuđa, deh ma Y-Jaret mbơ̆ Y-Gêdôr, Y-Hêber mbơ̆ ma Y-Sôkô, jêh ri Y-Jêkutiêl mbơ̆ Y-Sanôa.$b$,false),
('bunong-vn','1CH',4,19,null,$b$Phung kon bu klâu ur Y-Hôdia oh bu ur Y-Naham, jêng mbơ̆ ma Y-Keila bu klâu Garmi, jêh ri Y-Êstêmôa, bunuyh Makatit.$b$,false),
('bunong-vn','1CH',4,20,null,$b$Phung kon bu klâu Y-Simôn: Y-Amnôn, Y-Rina, Y-Benhavan, jêh ri Y-Tilôn. Phung kon bu klâu Y-Tisi: Y-Sôhet jêh ri Y-Bensôhet.$b$,false),
('bunong-vn','1CH',4,21,null,$b$Phung kon bu klâu Y-Sêla kon bu klâu Y-Yuđa: Y-Er mbơ̆ Y-Lêka, Y-Lada mbơ̆ Y-Marêsa, jêh ri phung ndŭl mpôl pah kan brai mhay ta ƀon Betasbêa.$b$,false),
('bunong-vn','1CH',4,22,null,$b$Geh Y-Jôkim, jêh ri phung ƀon Kôsêba, Y-Jôas jêh ri, Y-Sarap, nơm chiă uănh n'gor Môap jêh ri plơ̆ sĭt tay ma ƀon Lêhem (Sămƀŭt bu chih amoh khân păng bơh rô̆ kăl e)$b$,false),
('bunong-vn','1CH',4,23,null,$b$Nây jêng phung mon glah jêh ri phung gŭ ta ƀon Nêtaim jêh ri ƀon Gêdêra; khân păng gŭ ta nây ndrel ma hađăch gay pah kan ma păng.$b$,false),
('bunong-vn','1CH',4,24,null,$b$Phung kon bu klâu Y-Simêôn: Y-Nêmuel Y-Jamin, Y-Jarip, Y-Sêra, Y-Saul;$b$,true),
('bunong-vn','1CH',4,25,null,$b$Y-Salum jêng kon bu klâu păng ndrel ma Y-Mip sam jêh ri Y-Misma.$b$,false),
('bunong-vn','1CH',4,26,null,$b$Phung kon bu klâu Y-Mis ma: Y-Hamuel, Y-Sakur, Y-Simei.$b$,false),
('bunong-vn','1CH',4,27,null,$b$Bi Y-Simei geh jât ma prao nuyh kon bu klâu jêh ri prao nuyh kon bu ur. Ƀiă lah phung nâu păng mâu geh kon âk ôh; jêh ri lĕ rngôch mpôl khân păng tâm rđĭl đah phung Yuđa mâu jêng bĭk rơ̆ ôh.$b$,true),
('bunong-vn','1CH',4,28,null,$b$Khân păng gŭ tâm ƀon Bêr-Sêba, ƀon Môlada, ƀon Hasar-Sual,$b$,false),
('bunong-vn','1CH',4,29,null,$b$ƀon Bilha, ƀon Êsem, ƀon Tôlat,$b$,false),
('bunong-vn','1CH',4,30,null,$b$ƀon Bêthuet, ƀon Hôrma, ƀon Siklak,$b$,false),
('bunong-vn','1CH',4,31,null,$b$ƀon Bet-Markabôt, ƀon Hasan susim, ƀon Bet-Biri, jêh ri ƀon Saraim. Nây ƀon toyh khân păng kŏ tât ma rnôk Y-Đavit chiă uănh.$b$,false),
('bunong-vn','1CH',4,32,null,$b$Jêh ri ƀon jê̆ khân păng geh Êtam, Ain, Rimôn, Tôken, jêh ri Asan, prăm rplay ƀon,$b$,false),
('bunong-vn','1CH',4,33,null,$b$ndrel ma lĕ rngôch ƀon jê̆ gŭ jŭm tât ta ƀon Baal. Nây ntŭk khân păng gŭ, jêh ri khân păng djôt prăp Sămƀŭt ƀoi yau khân păng.$b$,false),
('bunong-vn','1CH',4,34,null,$b$Geh Y-Mêsôbap, Y-Jamlek, Y-Jôsa, kon bu klâu Y-Amasia,$b$,false),
('bunong-vn','1CH',4,35,null,$b$Y-Jôel, Y-Jêhu kon bu klâu Y-Yôsibia, sau Y-Sêraya, se Y-Asiêl,$b$,false),
('bunong-vn','1CH',4,36,null,$b$Y-Êliô ênai, Y-Jakôba, Y-Jêsahaya, Y-Asaya, Y-Adiêl, Y-Jêsimiêl, Y-Bênaya.$b$,false),
('bunong-vn','1CH',4,37,null,$b$Y-Sisa kon bu klâu Y-Sipi, Sau Y-Alôn, se Y-Jêdaya, săn Y-Simri jêng kon bu klâu Y-Sêmaya.$b$,false),
('bunong-vn','1CH',4,38,null,$b$Lĕ rngôch phung nây jêng phung kôranh tâm noi deh khân păng, ndŭl deh khân păng hao bĭk ngăn.$b$,true),
('bunong-vn','1CH',4,39,null,$b$Khân păng nsong tât ta ntŭk lăp ƀon Gêdôr, tât ta mpeh pa lơ rlŭng, gay joi ndrêch gơ̆ ma biăp khân păng;$b$,false),
('bunong-vn','1CH',4,40,null,$b$ntŭk khân păng saơ ndrêch gơ̆ ueh, jêh ri ntŭk ndrêch gơ̆ jêng toyh, rngơt klăk jêh ri đăp mpăn; kăl e noi deh Cham gŭ ta nây.$b$,false),
('bunong-vn','1CH',4,41,null,$b$Phung nây bu chih amoh kăl e, tâm rnôk Y-Hêsêkia; hađăch Yuđa, jêh ri hăn lơh lĕ rngôch phung Mêunim gŭ ta nây tâm nhuang ntŭk ngih bok khân păng, jêh ri gŭ ta ntŭk khân păng, yor lah ta nây geh ndrêch gơ̆ ma biăp khân păng.$b$,false),
('bunong-vn','1CH',4,42,null,$b$Tâm noi Simêôn geh prăm rhiăng bu klâu hăn hao tât yôk Sêir. Phung kôranh khân păng jêng Y-Pêlatia, Y-Nêaria, Y-Rêphaya, jêh ri Y-Usiêl, phung kon bu klâu Y-Isi;$b$,false),
('bunong-vn','1CH',4,43,null,$b$jêh ri khân păng ƀư rai phung Amalek klaih hôm e klen, jêh ri khân păng gŭ ta nây tât ma nar aơ.$b$,false),
('bunong-vn','1CH',5,1,null,$b$Phung kon bu klâu Y-Ruben, kon bôk rah ma Y-Israel, yor lah ƀư ƀơ̆ sưng bêch mbơ̆ păng, yor ri nau jêng nâu ranh bu jao jêh ma phung kon bu klâu Y-Yôsep, jêng kon bu klâu Y-Israel; nđâp lah pô nây, tâm nau ƀoi yau bu mâu chih ôh amoh Y-Yôsep jêng nâu ranh;$b$,true),
('bunong-vn','1CH',5,2,null,$b$Yor lah Y-Yuđa lơ đê̆ ta nklang phung oh nâu păng jêh ri tă bơh păng geh du huê kôranh chiă uănh; ƀiă lah nau jêng kôranh nâu ranh di ma Y-Yôsep.$b$,false),
('bunong-vn','1CH',5,3,null,$b$Aơ phung kon bu klâu Y-Ruben, kon bôk rah ma Y-Israel jêng Y-Hanôk, Y-Palu, Y-Hêsron, jêh ri Y-Karmi.$b$,false),
('bunong-vn','1CH',5,4,null,$b$Kon bu klâu Y-Yôel: Y-Sêmaya, kon bu klâu Y-Sêmaya: Y-Gôk; kon bu klâu Y-Gôk: Y-Simei;$b$,true),
('bunong-vn','1CH',5,5,null,$b$kon bu klâu Y-Simei: Y-Mi ka; kon bu klâu Y-Mika: Y-Rêaya; kon bu klâu Y-Rêaya: Y-Baal.$b$,false),
('bunong-vn','1CH',5,6,null,$b$Y-Bêera, nơm Y-Tiglat Pilêser hađăch n'gor bri Siri nhŭp ƀư bu nă; păng jêng kôranh noi deh tâm ndŭl mpôl Ruben.$b$,false),
('bunong-vn','1CH',5,7,null,$b$Phung oh nâu Y-Bêera tĭng mpôl păng, di nâm bu hŏ chih kơp tâm ndrom sămƀŭt ƀoi yau jêng, Y-Jêiêl ƀư kôranh, jêh ri Y-Sakari,$b$,false),
('bunong-vn','1CH',5,8,null,$b$jêh ri Y-Bêla kon bu klâu Y-Asas, sau Y-Sêma, se Y-Yôel, nơm gŭ ta ƀon Arôer tât ta yôk Nêbô jêh ri Baal. Mêon.$b$,false),
('bunong-vn','1CH',5,9,null,$b$Mpeh pa lơ păng gŭ ta ntŭk lăp bri rdah n'ho tât dak krong Ơphrat, yor lah mpô mpa khân păng rong lĕ bĭk ngăn n'gor Galaat.$b$,true),
('bunong-vn','1CH',5,10,null,$b$Tâm rnôk Y-Sôl khân păng tâm lơh đah phung Hagrit, phung khân păng hŏ khĭt jêh ma ti bu; jêh ri khân păng gŭ tâm ntŭk ngih bok khân păng lam nkual mpeh pa lơ n'gor Galaat.$b$,true),
('bunong-vn','1CH',5,11,null,$b$Phung kon bu klâu Y-Gat gŭ tâm tra đah khân păng tâm n'gor Basan, tât ta ƀon Salêka.$b$,true),
('bunong-vn','1CH',5,12,null,$b$Y-Yôel jêng kôranh, Y-Sapham jêng nơm groi păng; geh đŏng Y-Janai jêh ri Y-Saphat tâm n'gor Basan.$b$,false),
('bunong-vn','1CH',5,13,null,$b$Mpôl khân păng tĭng nâm noi deh khân păng: Y-Mikal, Y-Mêsulam, Y-Sêba, Y-Jôrai, Y-Jakan, Y-Sia, jêh ri Y-Êber, pơh nuyh.$b$,false),
('bunong-vn','1CH',5,14,null,$b$Nây jêng phung kon bu klâu Y-Abi hai; Y-Abi hai kon bu klâu Y-Hur; Y-Hur kon bu klâu Y-Jarôa; Y-Jarôa kon bu klâu Y-Galaat; Y-Galaat kon bu klâu Y-Mi kal; Y-Mi kal kon bu klâu Y-Jêsis ai; Y-Jêsi sai kon bu klâu Y-Jadô; Y-Jadô kon bu klâu Y-Bus.$b$,false),
('bunong-vn','1CH',5,15,null,$b$Y-Ahi kon bu klâu Y-Apdiêl; Y-Apdiêl kon bu klâu Y-Guni; Y-Ahi jêng kôranh tâm noi deh.$b$,false),
('bunong-vn','1CH',5,16,null,$b$Khân păng gŭ ta n'gor Galaat, tâm n'gor Basan, jêh ri ƀon jê̆ jê̆ păng, jêh ri tâm lĕ rngôch ndrêch dâng neh lâng Sarôn tât ta dŭt n'har păng$b$,false),
('bunong-vn','1CH',5,17,null,$b$Lĕ rngôch phung nây bu chih jêh amoh tâm ndrom sămƀŭt ƀoi yau tâm rnôk Y-Jôtham, hađăch Yuđa, jêh ri tâm rnôk Y-Jêrôbôam hađăch Israel.$b$,false),
('bunong-vn','1CH',5,18,null,$b$Phung Ruben, phung Gat, jêh ri du n'gul ndŭl mpôl Manasê geh phung dăng ktang djôt khêl jêh ri đao, jêh nây pănh na, n'hăk tâm lơh, geh puăn rmưn puăn rbăn pơh rhiăng prao jât nuyh nkra rơm kâp tâm lơh.$b$,true),
('bunong-vn','1CH',5,19,null,$b$Khân păng tâm lơh đah phung Hagrit, phung Jêtur, phung Napis, jêh ri phung Nôdap.$b$,false),
('bunong-vn','1CH',5,20,null,$b$Dôl tơ lah khân păng tâm lơh, khân păng vơl dăn ma Brah Ndu, jêh ri Brah Ndu dơn yor lah khân păng geh nuih n'hâm nsing rnơm ma păng, pô ri kơl rklaih an, jao phung Hagrit jêh ri lĕ rngôch phung tĭng păng tâm ti khân păng.$b$,false),
('bunong-vn','1CH',5,21,null,$b$Khân păng sŏk gro mpô mpa khân păng rong: Prăm rmưn mlâm seh samô, bar rsen prăm rmưn mlâm biăp, bar rbăn mlâm seh bri, jêh ri du rsen bu klâu hôm e rêh.$b$,true),
('bunong-vn','1CH',5,22,null,$b$Yor lah âk ngăn bunuyh lĕ chôt khĭt, yor lah nau tâm lơh luh tă bơh Brah Ndu. Khân păng gŭ ta ntŭk khân păng kŏ tât nôk bu nhŭp njŭn leo khân păng jêng bună.$b$,false),
('bunong-vn','1CH',5,23,null,$b$Du n'gul phung ndŭl mpôl Manasê gŭ tâm n'gor ntơm bơh yôk Basan tât yôk Baal-Hêrmôn, yôk Sênir, jêh ri yôk Hêrmôn; rnoh bunuyh khân păng âk ngăn.$b$,false),
('bunong-vn','1CH',5,24,null,$b$Aơ jêng kôranh ma phung ndŭl mpôl tâm noi deh khân păng: Y-Êpher, Y-Tisi, Y-Êliêl, Y-Ariel, Y-Yêrimi, Y-Hôdavia, jêh ri Y-Jahdiêl, phung janh ktang phung geh lư n'găr, kôranh ma ndŭl mpôl khân păng.$b$,false),
('bunong-vn','1CH',5,25,null,$b$Ƀiă lah khân păng rlau nau vay tâm rdâng đah Brah Ndu ma phung che khân păng, jêh ri ƀư nau brơl tĭng ndô̆ phung brah ƀon lan tâm n'gor nây, phung Brah Ndu ƀư rai jêh ta năp khân păng.$b$,false),
('bunong-vn','1CH',5,26,null,$b$Pô ri Brah Ndu Israel nsônh nau mĭn Y-Pul hađăch Asiri, jêh ri nau mĭn Y-Tiglat-Pilêser hađăch Asiri, jêh ri păng nhŭp njŭn leo jêng bu nă phung Ruben, phung Gat, jêh ri du n'gul ndŭl mpôl Manasê, jêh ri njŭn khân păng leo ma ƀon Hala, ƀon Habôt, ƀon Hara, jêh ri dak krong Gôsan tât ma nar aơ.$b$,false),
('bunong-vn','1CH',6,1,null,$b$Phung kon bu klâu Y-Lêvi: Y-Gersôm, Y-Kôhat, jêh ri Y-Mêrari.$b$,true),
('bunong-vn','1CH',6,2,null,$b$Phung kon bu klâu Y-Kôhat: Y-Amram, Y-Ishar, Y-Hêbron, Y-Usiêl.$b$,false),
('bunong-vn','1CH',6,3,null,$b$Phung kon Y-Amram: Y-Arôn, Y-Môis, H'Miriam. Phung kon bu klâu Y-Arôn: Y-Ithamar: Y-Nadap, Y-Abihu, Y-Êlêasar, jêh ri Y-Itham ar.$b$,false),
('bunong-vn','1CH',6,4,null,$b$Y-Êlêa sar jêng mbơ̆ ma Y-Phinêas, Y-Phinêas jêng mbơ̆ ma Y-Abisua,$b$,false),
('bunong-vn','1CH',6,5,null,$b$Y-Abisua jêng mbơ̆ ma Y-Buki, Y-Buk, jêng mbơ̆ ma Y-Usi,$b$,false),
('bunong-vn','1CH',6,6,null,$b$Y-Usi jêng mbơ̆ ma Y-Sêrahia, Y-Sêrahia jêng mbơ̆ ma jêng mbơ̆ ma Y-Mêralôt,$b$,false),
('bunong-vn','1CH',6,7,null,$b$Y-Mêralôt jêng mbơ̆ ma Y-Amaria, Y-Amaria jêng mbơ̆ ma Y-Ahitup,$b$,false),
('bunong-vn','1CH',6,8,null,$b$Y-Ahitup jêng mbơ̆ ma Y-Sadôk, Y-Sadôk jêng mbơ̆ ma Y-Ahimas$b$,false),
('bunong-vn','1CH',6,9,null,$b$Y-Ahimas jêng mbơ̆ ma Y-Asaria, Y-Asaria jêng mbơ̆ ma Y-Jôhanan,$b$,false),
('bunong-vn','1CH',6,10,null,$b$jêh ri Y-Jôhanan jêng mbơ̆ Y-Asaria, (jêng bunuyh pah kan kôranh ƀư brah tâm ngih Y-Salômôn hŏ ndâk tâm ƀon Yêrusalem).$b$,false),
('bunong-vn','1CH',6,11,null,$b$Y-Asaria jêng mbơ̆ ma Y-Amaria, Y-Amaria jêng mbơ̆ ma Y-Ahitup,$b$,false),
('bunong-vn','1CH',6,12,null,$b$Y-Ahitup jêng mbơ̆ ma Y-Sadôk, Y-Sadôk jêng mbơ̆ ma Y-Salum.$b$,false),
('bunong-vn','1CH',6,13,null,$b$Y-Salum jêng mbơ̆ ma Y-Hilkia, Y-Hilkia jêng mbơ̆ ma Y-Asaria,$b$,false),
('bunong-vn','1CH',6,14,null,$b$Y-Asaria jêng mbơ̆ ma Y-Sêraya, Y-Sêraya jêng mbơ̆ ma Y-Jêhô-sadak,$b$,false),
('bunong-vn','1CH',6,15,null,$b$jêh ri Y-Jêhôsadak hăn jêng bună ma ti Nêbukatnetsar.$b$,false),
('bunong-vn','1CH',6,16,null,$b$Phung kon bu klâu Y-Lêvi: Y-Gersôm, Y-Kôhat, jêh ri Y-Mêrari.$b$,false),
('bunong-vn','1CH',6,17,null,$b$Aơ jêng amoh phung kon bu klâu Y-Gersôm: Y-Lipni jêh ri Y-Simei.$b$,false),
('bunong-vn','1CH',6,18,null,$b$Phung kon bu klâu Y-Kôhat: Y-Amram, Y-Ishar, Y-Hêbron jêh ri Y-Usiêl.$b$,false),
('bunong-vn','1CH',6,19,null,$b$Phung kon bu klâu Y-Mêrari: Y-Mahil jêh ri Y-Musi. Nây jêng mpôl phung Lêvi tĭng noi deh khân păng.$b$,false),
('bunong-vn','1CH',6,20,null,$b$Kon bu klâu Y-Gersôm: Y-Lipni, Y-Jahat, Y-Sima,$b$,false),
('bunong-vn','1CH',6,21,null,$b$Y-Jôa, Y-Idô, Y-Sêra, Y-Jêatêrai.$b$,false),
('bunong-vn','1CH',6,22,null,$b$Phung kon bu klâu Y-Kôhat: Y-Aminadap, Y-Kôrê, Y-Asir,$b$,false),
('bunong-vn','1CH',6,23,null,$b$Y-Êlkana, Y-Êbiasap, Y-Asir,$b$,false),
('bunong-vn','1CH',6,24,null,$b$Y-Jahat, Y-Uriêl, Y-Usia, jêh ri Y-Sal,$b$,false),
('bunong-vn','1CH',6,25,null,$b$Phung kon bu klâu Y-Êlkana: Y-Amasai, jêh ri Y-Ahimôt,$b$,false),
('bunong-vn','1CH',6,26,null,$b$Y-Êlkana, Y-Sôphai; Y-Nahat,$b$,false),
('bunong-vn','1CH',6,27,null,$b$Y-Êliap, Y-Jêrôham, Y-Êlkana.$b$,false),
('bunong-vn','1CH',6,28,null,$b$Phung kon bu klâu Y-Samuel: Y-Yôel kon bôk rah, Y-Ahisa kon rơh bar.$b$,false),
('bunong-vn','1CH',6,29,null,$b$Phung kon bu klâu Y-Mêrari: Y-Mahli, Y-Lipni, Y-Simei, Y-Usa,$b$,false),
('bunong-vn','1CH',6,30,null,$b$Y-Simêa, Y-Hagia, jêh ri Y-Asia.$b$,false),
('bunong-vn','1CH',6,31,null,$b$Aơ jêng phung bunuyh Y-Đavit dơm kan mprơ tâm ngih brah Yêhôva, jêh bu tung leo hip ta nây.$b$,true),
('bunong-vn','1CH',6,32,null,$b$Khân păng pah kan ma nau mprơ ta năp ngih bok tâm rƀŭn, kŏ tât tơ lah Y-Salômôn ndâk lôch jêh ngih Yêhôva tâm ƀon Yêrusalem; jêh ri khân păng pah kan tĭng nâm di tâm ndăch.$b$,false),
('bunong-vn','1CH',6,33,null,$b$Phung aơ jêng phung bu klâu kon bu klâu khân păng pah kan nây. Phung kon bu klâu Y-Kôhat: Geh Y-Hêman jêng nơm kreh, nơm mprơ jêng kon bu klâu Y-Yôel, Y-Yôel kon bu klâu Y-Samuel,$b$,true),
('bunong-vn','1CH',6,34,null,$b$Y Samuel kon bu klâu Y-Êlkana, Y-Êlkana kon bu klâu Y-Jêrôham, Y-Jêrôham kon bu klâu Y-Êliêl, Y-Êliêl kon bu klâu Y-Tôa,$b$,false),
('bunong-vn','1CH',6,35,null,$b$Y-Tôa kon bu klâu Y-Sup, Y-Sup kon bu klâu Y-Êlkana, Y-Êlkana kon bu klâu Y-Mahat, Y-Mahat kon bu klâu Y-Amasai,$b$,false),
('bunong-vn','1CH',6,36,null,$b$Y-Amasai kon bu klâu Y-Êkana, Y-Êlkana kon bu klâu Y-Yôel, Y-Yôel kon bu klâu Y-Asaria, Y-Asaria kon bu klâu Y-Sephania,$b$,false),
('bunong-vn','1CH',6,37,null,$b$Y-Sêphania kon bu klâu Y-Tahat, Y-Tahat kon Y-Asir, Y-Asir kon bu klâu Y-Êbiasap, Y-Êbiasap kon bu klâu Y-Kôrê,$b$,false),
('bunong-vn','1CH',6,38,null,$b$Y-Kôrê kon bu klâu Y-Tisihar, Y-Tisihar kon bu klâu Y-Kôhat, Y-Kôhat kon bu klâu Y-Lêvi, Y-Lêvi kon bu klâu Y-Israel.$b$,false),
('bunong-vn','1CH',6,39,null,$b$Y-Asap, oh Y-Hêman, nơm gŭ mpeh pa ma păng, Y-Asap kon bu klâu Y-Bêrêkia, Y-Bêrêkia kon bu klâu Y-Simêa,$b$,true),
('bunong-vn','1CH',6,40,null,$b$Y-Simêa kon bu klâu Y-Mikal, Y-Mikal kon bu klâu Y-Baseya, Y-Baseya kon bu klâu Y-Malkija,$b$,false),
('bunong-vn','1CH',6,41,null,$b$Y-Malkija kon bu klâu Y-Êtni, Y-Êtni kon bu klâu Y-Sera, Y-Sera kon bu klâu Y-Adaya,$b$,false),
('bunong-vn','1CH',6,42,null,$b$Y-Adaya kon bu klâu Y-Êthan, Y-Êthan kon bu klâu Y-Sima, Y-Sima kon bu klâu Y-Simei.$b$,false),
('bunong-vn','1CH',6,43,null,$b$Y-Simei kon bu klâu Y-Jahat, Y-Jahat kon bu klâu Y-Gersôm, Y-Gersôm kon bu klâu Y-Lêvi.$b$,false),
('bunong-vn','1CH',6,44,null,$b$Phung kon bu klâu Y-Mêrari, oh nâu khân păng, gŭ mpeh pa chiau da dê, geh Y-Êthan kon bu klâu Y-Kisi, Y-Kisi kon bu klâu Y-Apdi, Y-Apdi kon bu klâu Y-Maluk,$b$,false),
('bunong-vn','1CH',6,45,null,$b$Y-Maluk kon bu klâu Y-Hasabia, Y-Hasabia kon bu klâu Y-Amasia, Y-Amasia kon bu klâu Y-Hilkia,$b$,false),
('bunong-vn','1CH',6,46,null,$b$Y-Hilkia kon bu klâu Y-Amsi, Y-Amsi kon bu klâu Y-Bani, Y-Bani kon bu klâu Y-Sêmer,$b$,false),
('bunong-vn','1CH',6,47,null,$b$Y-Sêmer kon bu klâu Y-Mahil, Y-Mahil kon bu klâu Y-Musi, Y-Musi kon bu klâu Y-Mêrari, Y-Mêrari kon bu klâu Y-Lêvi.$b$,false),
('bunong-vn','1CH',6,48,null,$b$Phung oh nâu khân păng, jêng phung Lêvi êng, bu dơm kan jêh ma lĕ rngôch kan ngih bok tâm ngih Brah Ndu.$b$,false),
('bunong-vn','1CH',6,49,null,$b$Ƀiă lah Y-Arôn jêh ri phung kon bu klâu păng nhhơr ndơ ta klơ nơng ndơ nhhơr gŭch jêh ri ta klơ nơng ndơ nhhơr ƀâu kah ma lĕ rngôch kan tâm ntŭk kloh ueh ngăn, jêh ri gay ƀư tâm chuai nau tih ăn kloh ma phung Israel, tĭng nâm nau Y-Môis oh mon Brah Ndu$b$,true),
('bunong-vn','1CH',6,50,null,$b$Aơ phung kon bu klâu Y-Arôn: Y-Êlêasar kon bu klâu păng; Y-Phinêas kon bu klâu Y-Êlêasar; Y-Abisua kon bu klâu Y-Phinêas;$b$,false),
('bunong-vn','1CH',6,51,null,$b$Y-Buki kon bu klâu Y-Abisua, Y-Usi kon bu klâu Y-Buki, Y-Sêrahia kon bu klâu Y-Usi,$b$,false),
('bunong-vn','1CH',6,52,null,$b$Y-Mêraiôt kon bu klâu Y-Sêrahia, Y-Amrari kon bu klâu Y-Mêraiôt, Y-Ahitup kon bu klâu Y-Amaria,$b$,false),
('bunong-vn','1CH',6,53,null,$b$Y-Sadôk kon bu klâu Y-Ahi tup, Y-Ahimas kon bu klâu Y-Sadôk.$b$,false),
('bunong-vn','1CH',6,54,null,$b$Aơ jêng ntŭk gŭ phung kon sau Y-Arôn, tĭng nâm ntŭk njơh tâm nkual n'har bri khân păng tĭng ndŭl mpôl Kôhat tâm nchroh lor lơn,$b$,true),
('bunong-vn','1CH',6,55,null,$b$ma khân păng bu ăn ƀon Hêbron tâm n'gor Yuđa nđâp ndrêch gơ̆ văr jŭm,$b$,false),
('bunong-vn','1CH',6,56,null,$b$ƀiă lah bu ăn mir jêh ri ƀon jê̆ ma Y-Kalep kon bu klâu Y-Jêphunê.$b$,false),
('bunong-vn','1CH',6,57,null,$b$Khân păng ăn ma phung kon bu klâu Y-Arôn ƀon prăp du krap. Ƀon Hêbron, ƀon Lipna ndrel ma ndrêch gơ̆ , ƀon Jatir, ƀon Êstêmôa ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,58,null,$b$ƀon Hilên ndrel ma ndrêch gơ̆ , ƀon Dêbin ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,59,null,$b$ƀon Asan ndrel ma ndrêch gơ̆ , jêh ri ƀon Betsêmes ndrel ma ndrêch gơ̆ ;$b$,false),
('bunong-vn','1CH',6,60,null,$b$jêh ri tâm nkual Benjamin bu ăn ƀon Gêba ndrel ma ndrêch gơ̆ , ƀon Alêmet ndrel ma ndrêch gơ̆ , jêh ri ƀon Anathôt ndrel ma ndrêch gơ̆ . Lĕ rngôch ƀon toyh tâm lĕ rngôch mpôl khân păng geh jât ma pe rplay ƀon.$b$,false),
('bunong-vn','1CH',6,61,null,$b$Ma phung Kôhat hôm e bu ăn jêh ma nau tâm nchroh du n'gul mpôl phung Manasê jât rplay ƀon.$b$,false),
('bunong-vn','1CH',6,62,null,$b$Ma phung Gersôm tĭng nâm mpôl khân păng bu ăn jât ma pe rplay ƀon toyh bơh mpôl phung Isakar, phung Aser, phung Naptali jêh ri phung Manasê tâm n'gor Basan.$b$,false),
('bunong-vn','1CH',6,63,null,$b$Ma phung Mêrari tĭng nâm mpôl khân păng bu ăn jât ma bar rplay ƀon toyh bơh mpôl phung Ruben, phung Gat, jêh ri phung Sabulôn.$b$,false),
('bunong-vn','1CH',6,64,null,$b$Pô ri phung ƀon lan Israel ăn ma phung Lêvi âk rplay ƀon toyh ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,65,null,$b$Khân păng tâm ban đŏng ma nau tâm nchroh bơh mpôl phung Yuđa, phung Simêôn, jêh ri phung Benjamin lĕ rngôch ƀon aơ bu rŏ amoh khân păng.$b$,false),
('bunong-vn','1CH',6,66,null,$b$Tâm phung Kôhat geh ƀa ƀă ƀon tâm neh khân păng jêng ndơ bơh mpôl phung Êphraim.$b$,true),
('bunong-vn','1CH',6,67,null,$b$Bu ăn ma khân păng ƀon prăp du krap: Ƀon Sichem ndrel ma ndrêch gơ̆ tâm n'gor klơ dor Êphraim, ƀon Gêser ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,68,null,$b$ƀon Jôkmêam ndrel ma ndrêch gơ̆ , ƀon Bet-Hôron ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,69,null,$b$ƀon Aijalon ndrel ma ndrêch gơ̆ , ƀon Gat-Rimôn ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,70,null,$b$jêh ri bơh du n'gul mpôl phung Manasê, ƀon Aser ndrel ma ndrêch gơ̆ , jêh ri ƀon Bilêam ndrel ma ndrêch gơ̆ , prăp ma phung mpôl Kôhat hôm e.$b$,false),
('bunong-vn','1CH',6,71,null,$b$Bu ăn ma phung Gersôm bơh du n'gul mpôl phung Manasê: Ƀon Gôlan tâm n'gor Basan ndrel ma ndrêch gơ̆ , jêh ri ƀon Astarôt ndrel ma ndrêch gơ̆ ;$b$,false),
('bunong-vn','1CH',6,72,null,$b$jêh ri bơh mpôl phung Isakar. Ƀon Kêdês ndrel ma ndrêch gơ̆ , ƀon Dabêrat ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,73,null,$b$ƀon Ramôt ndrel ma ndrêch gơ̆ , jêh ri ƀon Anem ndrel ma ndrêch gơ̆ ;$b$,false),
('bunong-vn','1CH',6,74,null,$b$bơh mpôl phung Aser. Ƀon Masal ndrel ma ndrêch gơ̆ , ƀon Apdôn ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,75,null,$b$ƀon Hukôk ndrel ma ndrêch gơ̆ , jêh ri ƀon Rêhôp ndrel ma ndrêch gơ̆ ;$b$,false),
('bunong-vn','1CH',6,76,null,$b$bơh mpôl phung Naptali. Ƀon kêdês tâm n'gor Galilê ndrel ma ndrêch gơ̆ , ƀon Hamôn ndrel ma ndrêch gơ̆ , jêh ri ƀon Kiriat thaim ndrel ma ndrêch gơ̆ .$b$,false),
('bunong-vn','1CH',6,77,null,$b$Bu ăn ma Mêrari hôm e klen ndơ bơh mpôl phung Sabulôn: Ƀon Rimônô ndrel ma ndrêch gơ̆ , ƀon Tabôr ndrel ma ndrêch gơ̆ ,$b$,true),
('bunong-vn','1CH',6,78,null,$b$jêh ri kăl tê̆ dak krong Yurdan ta ƀon Yêrikô mpeh Pa lơ, bơh mpôl phung Ruben: Ƀon Bêser tâm ntŭk neh lâng ndrel ma ndrêch gơ̆ , ƀon Jasa ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,79,null,$b$ƀon Kêdêmôt ndrel ma ndrêch gơ̆ , jêh ri ƀon Mêphat ndrel ma ndrêch gơ̆ ;$b$,false),
('bunong-vn','1CH',6,80,null,$b$jêh ri bơh mpôl phung Gat. Ƀon Ramôt tâm n'gor Galaat ndrel ma ndrêch gơ̆ , ƀon Mahanaim ndrel ma ndrêch gơ̆ ,$b$,false),
('bunong-vn','1CH',6,81,null,$b$ƀon Hêsbon ndrel ma ndrêch gơ̆ , jêh ri ƀon Jaser ndrel ma ndrêch gơ̆ .$b$,false),
('bunong-vn','1CH',7,1,null,$b$Phung kon bu klâu Isakar: Y-Tôla, Y-Dua, Y-Jasup, jêh ri Y-Sim rôn, puăn nuyh.$b$,true),
('bunong-vn','1CH',7,2,null,$b$Phung kon bu klâu Y-Tôla: Y-Usi, Y-Rêphaya, Y-Jêriêl, Y-Jahmai, Y-Ipsam, jêh ri Y-Samuel, jêng kôranh ma noi deh khân păng nâm bu Tôla, phung janh ktang tâm rnôk khân păng; rnoh kơp tâm rnôk Y-Đavit geh bar rmưn bar rbăn prao rhiăng nuyh.$b$,false),
('bunong-vn','1CH',7,3,null,$b$Kon bu klâu Y-Usi: Y-Israhia. Phung kon bu klâu Y-Israhia: Y-Mikel, Y-Ôbadia, Y-Yôel, jêh ri Y-Isiya, lĕ rngôch khân păng prăm nuyh jêng kôranh da dê;$b$,false),
('bunong-vn','1CH',7,4,null,$b$jêh ri ndrel ma khân păng tĭng nâm rô̆ khân păng tĭng nâm ndŭl mpôl khân păng, geh mpôl ta han êng êng prăp ma nau tâm lơh, pe rmưn prao rbăn nuyh, yor lah khân păng geh âk ur jêh ri kon bu klâu.$b$,false),
('bunong-vn','1CH',7,5,null,$b$Phung bunuyh tâm lĕ rngôch phung mpôl Isakar geh pham rmưn pơh rbăn nuyh phung ta han janh ktang, geh amoh săk chih tâm ndrom săm bŭt chih amoh.$b$,false),
('bunong-vn','1CH',7,6,null,$b$Phung kon bu klâu Benjamin: Y-Bêla, Y-Bêker, jêh ri Y-Jêdiaêl, pe nuyh.$b$,true),
('bunong-vn','1CH',7,7,null,$b$Phung kon bu klâu Y-Bêla: Y-Êsbôn, Y-Usi, Y-Usiêl, Y-Jêrimôt, jêh ri Y-Jri, prăm nuyh, kôranh ma noi deh khân păng da dê, jêng phung ta han janh ktang; jêh ri rnoh kơp kon sau khân păng tĭng ndŭl mpôl, geh bar rmưn bar rbăn pe jât ma puăn nuyh.$b$,false),
('bunong-vn','1CH',7,8,null,$b$Phung kon bu klâu Y-Bêker: Y-Sêmira, Y-Jôas, Y-Êliêser, Y-Êliôênai, Y-Ômri, Y-Jêrêmôt, Y-Abija, Y-Anathôt, jêh ri Y-Alêmet.$b$,false),
('bunong-vn','1CH',7,9,null,$b$Lĕ rngôch phung nây jêng kon bu klâu Y-Bêker; tơ lah chih amoh khân păng tĭng nâm rô̆ khân păng jêng kôranh ma ndŭl mpôl khân păng, jêng phung ta han janh ktang, geh bar rmưn bar rhiăng nuyh.$b$,false),
('bunong-vn','1CH',7,10,null,$b$Kon bu klâu Y-Jêdiaêl: Y-Bilhan. Phung kon bu klâu Y-Bilhan: Y-Jêus, Y-Benjamin, Y-Êhut, Y-Kênana, Y-Sêthan, Y-Tarsis, jêh ri Y-Ahisahar.$b$,false),
('bunong-vn','1CH',7,11,null,$b$Lĕ rngôch phung nây jêng phung kon bu klâu Y-Jêdiaêl tĭng nâm phung kôranh ndŭl mpôl khân păng, phung ta han janh ktang, geh du rmưn pơh rbăn bar rhiăng nuyh kâp tâm lơh.$b$,false),
('bunong-vn','1CH',7,12,null,$b$Y-Supim jêh ri Y-Hisim jêng kon bu klâu Y-Aher.$b$,false),
('bunong-vn','1CH',7,13,null,$b$Phung kon bu klâu Y-Naptali: Y-Jahsiêl, Y-Guni, Y-Jêser, jêh ri Y-Salum kon bu klâu H'Bilha.$b$,true),
('bunong-vn','1CH',7,14,null,$b$Kon bu klâu Y-Manasê: Y-Asriêl, nơm ur yông păng du huê bu ur Aram deh ăn păng; păng deh ma Y-Makir jêng mbơ̆ ma Y-Galaat.$b$,true),
('bunong-vn','1CH',7,15,null,$b$Jêh ri Y-Makir joi ur ma Y-Hupim jêh ri Y-Supim. Amoh oh bu ur păng jêng H'Maka. Amoh kon bu klâu rơh bar jêng Y-Sêlôphêhat; jêh ri Y-Sêlôphêhat geh knŏng phung kon bu ur.$b$,false),
('bunong-vn','1CH',7,16,null,$b$H'Maka ur Y-Makir deh ma du huê kon bu klâu, jêh ri păng ntơ amoh păng Y-Pêres; jêh ri amoh oh păng jêng Y-Sêres; jêh ri phung kon bu klâu păng jêng Y-Ulam jêh ri Y-Rakem.$b$,false),
('bunong-vn','1CH',7,17,null,$b$Kon bu klâu Y-Ulam: Y-Bêdan-Aơ jêng phung kon bu klâu Y-Galaat, sau Y-Makir, se Y-Manasê.$b$,true),
('bunong-vn','1CH',7,18,null,$b$Oh bu ur păng H'Hamôleket deh ma Y-Isôt, Y-Abiêser, jêh ri Y-Mahla.$b$,false),
('bunong-vn','1CH',7,19,null,$b$Phung kon bu klâu Y-Sêmida jêng Y-Ahian, Y-Sichem, Y-Likhi, jêh ri Y-Aniam.$b$,true),
('bunong-vn','1CH',7,20,null,$b$Phung kon sau Y-Êphraim: Y-Suthêla; kon bu klâu Y-Suthêla jêng Y-Bêrêt; kon bu klâu Y-Bêret jêng Y-Tahat; kon bu klâu Y-Tahat jêng Y-Êlêada; kon bu klâu Y-Êlêada jêng Y-Tahat;$b$,true),
('bunong-vn','1CH',7,21,null,$b$kon bu klâu Y-Tahat jêng Y-Saƀat; kon bu klâu Y-Saƀat jêng Y-Suthêla, Y-Êser jêh ri Y-Êlêat; khân păng lĕ phung Gat nkhĭt, yor lah khân păng trŭnh gay ŭch pit in mpô mpa khân păng rong.$b$,false),
('bunong-vn','1CH',7,22,null,$b$Y-Êphraim, mbơ̆ khân păng, nđom klâng rngot jŏ nar, jêh ri phung oh nâu păng văch bonh leng păng.$b$,true),
('bunong-vn','1CH',7,23,null,$b$Pô nây, Y-Êphraim lăp gŭ đah ur păng, jêh ri ô băl ntreo jêh nây deh ma du huê kon bu klâu; jêh ri păng ntơ amoh ô băl Y-Bêria, yor lah nau mhĭk tât jêh ma ngih păng.$b$,false),
('bunong-vn','1CH',7,24,null,$b$Kon bu ur păng H'Sêra, nơm ndâk jêh ƀon Bet-Hôron tâm dâng jêh ri ta Klơ, jêh nây ƀon Usen-Sêra.$b$,false),
('bunong-vn','1CH',7,25,null,$b$Jêh ta nây păng geh đŏng phung kon bu klâu păng: Y-Rêpha mbơ̆ ma Y-Rêsep jêh ri Y-Têla; Y-Têla mbơ̆ ma Y-Tahan;$b$,true),
('bunong-vn','1CH',7,26,null,$b$Y-Tahan mbơ̆ ma Y-Ladan; Y-Ladan mbơ̆ ma Y-Amihut; Y-Amhut mbơ̆ ma Y-Êlisama,$b$,false),
('bunong-vn','1CH',7,27,null,$b$Y-Êlisama mbơ̆ ma Y-Nun; jêh ri Y-Nun mbơ̆ ma Y-Yôsuê.$b$,false),
('bunong-vn','1CH',7,28,null,$b$Drăp ndơ ndơn khân păng jêh ri ntŭk gŭ khân păng jêng ƀon Bêthel jêh ri lĕ rngôch ƀon jê̆ păng, mpeh pa lơ geh ƀon Naran, mpeh pa dâng geh ƀon Gêser jêh ri lĕ rngôch ƀon jê̆ păng, ƀon Aya jêh ri lĕ rngôch ƀon jê̆ păng;$b$,false),
('bunong-vn','1CH',7,29,null,$b$tâm ban đŏng n'gŏ n'har bri phung Manasê, ƀon Betsêan jêh ri lĕ rngôch ƀon jê̆ păng, ƀon Tanak jêh ri lĕ rngôch ƀon jê̆ păng, ƀon Mêgidô jêh ri ƀon lĕ rngôch ƀon jê̆ păng, ƀon Dor jêh ri lĕ rngôch ƀon jê̆ păng. Kon sau Y-Yôsep, kon bu klâu Y-Israel gŭ ta nây.$b$,false),
('bunong-vn','1CH',7,30,null,$b$Phung kon bu klâu Y-Aser: Y-Imna Y-Isva, Y-Isvi, Y-Bêria, jêh ri oh bu ur khân păng H'Sêra.$b$,true),
('bunong-vn','1CH',7,31,null,$b$Phung kon bu klâu Y-Bêria: Y-Hêber jêh ri Y-Malkiêl; Y-Malkiêl jêng Chô che ma Y-Birsait.$b$,false),
('bunong-vn','1CH',7,32,null,$b$Y-Hêber jêng mbơ̆ ma Y-Japhlet, Y-Sêmer, Y-Hôtham, jêh ri oh bu ur khân păng H'Sua.$b$,false),
('bunong-vn','1CH',7,33,null,$b$Phung kon bu klâu Y-Japhlet: Y-Pasach, Y-Bimhal, jêh ri Y-Asvat. Phung nây jêng phung kon bu klâu Y-Japhlet.$b$,false),
('bunong-vn','1CH',7,34,null,$b$Phung kon bu klâu Y-Sêmer oh păng: Y-Ahi, Y-Rohga, Y-Jêhuba, jêh ri Y-Aram.$b$,false),
('bunong-vn','1CH',7,35,null,$b$Phung kon bu klâu Y-Hêlem oh păng: Y-Sôpha, Y-Imna, Y-Sêles jêh ri Y-Amal.$b$,false),
('bunong-vn','1CH',7,36,null,$b$Phung kon bu klâu Y-Sôpha: Y-Sua, Y-Harnêpher, Y-Sual, Y-Bêri, Y-Imra,$b$,false),
('bunong-vn','1CH',7,37,null,$b$Y-Bêser, Y-Hot, Y-Sama, Y-Silsa, Y-Itram, jêh ri Y-Bêera.$b$,false),
('bunong-vn','1CH',7,38,null,$b$Phung kon bu klâu Y-Jether: Y-Jêphunê, Y-Pispa, jêh ri Y-Ara.$b$,false),
('bunong-vn','1CH',7,39,null,$b$Phung kon bu klâu Y-Ula: Y-Ara, Y-Haniêl, jêh ri Y-Risia.$b$,false),
('bunong-vn','1CH',7,40,null,$b$Lĕ rngôch phung nây jêng phung ndŭl mpôl Aser, ƀư kôranh ma ndŭl deh, phung bu yơk, phung ta han janh ktang, kôranh toyh ma phung kôranh. Rnoh kơp khân păng chih jêh tâm ndrom săm ƀŭt prăp ma kan tâm lơh geh bar rmưn prao rbăn nuyh.$b$,false),
('bunong-vn','1CH',8,1,null,$b$Y-Benjamin jêng mbơ̆ ma Y-Bêla, kon bôk rah, Y-Asbel kon rơh bar, Y-Ahara kon rơh pe,$b$,true),
('bunong-vn','1CH',8,2,null,$b$Y-Nôha kon rơh puăn, jêh ri Y-Rapha kon rơh prăm.$b$,false),
('bunong-vn','1CH',8,3,null,$b$Y-Bêla geh phung kon bu klâu: Y-Adar, Y-Gêra, Y-Abi hut,$b$,false),
('bunong-vn','1CH',8,4,null,$b$Y-Abi sua, Y-Na man, Y-Ahôa.$b$,false),
('bunong-vn','1CH',8,5,null,$b$Y-Gêra, Y-Sêphu phan, jêh ri Y-Huram.$b$,true),
('bunong-vn','1CH',8,6,null,$b$Aơ jêng phung kon bu klâu Y-Êhut; phung nây jêng kôranh ma ndŭl mpôl phung gŭ tâm ƀon Gêba; jêh ri bu nhŭp phung nây ƀư bu nă njŭn tât ma neh ƀon Manahat;$b$,true),
('bunong-vn','1CH',8,7,null,$b$Y-Naman, Y-Ahija, jêh ri Y-Gêra bu nhŭp ndrel khân păng jêng bună, jêh ri Y-Gêra jêng mbơ̆ ma Y-Usa jêh ri Y-Ahihut.$b$,false),
('bunong-vn','1CH',8,8,null,$b$Y-Saharaim geh phung kon bu klâu tâm n'gor Môap jêh păng lơi ur păng H'Husim jêh ri H'Bara.$b$,true),
('bunong-vn','1CH',8,9,null,$b$Păng geh phung kon bu klâu đah ur păng H'Hôdes: Y-Jôbap, Y-Sibia, Y-Mêsa, Y-Malkam,$b$,false),
('bunong-vn','1CH',8,10,null,$b$Y-Jêus, Y-Sakia, jêh ri Y-Mirma. Nây jêng phung kon bu klâu păng, kôranh ma ndŭl mpôl păng.$b$,false),
('bunong-vn','1CH',8,11,null,$b$Păng geh đŏng phung kon đah ur păng H'Husim: Y-Abitup, jêh ri Y-Êlpal.$b$,false),
('bunong-vn','1CH',8,12,null,$b$Phung kon bu klâu Y-Êlpal: Y-Êber, Y-Misam jêh ri Y-Sêmer, nơm ndâk ƀon Ônô jêh ri ƀon Lot ndrel ma lĕ rngôch ƀon jê̆ păng,$b$,false),
('bunong-vn','1CH',8,13,null,$b$jêh ri Y-Bêria jêh ri Y-Sêma, khân păng jêng kôranh ma ndŭl mpôl khân păng ma phung gŭ tâm rlŭng Aijalon, phung hŏ mprơh du pru pra phung gŭ tâm ƀon Gat;$b$,false),
('bunong-vn','1CH',8,14,null,$b$jêh ri Y-Ahiô, Y-Sasak, jêh ri Y-Jêrêmôt.$b$,false),
('bunong-vn','1CH',8,15,null,$b$Y-Sêbadia, Y-Arat, Y-Êder,$b$,true),
('bunong-vn','1CH',8,16,null,$b$Y-Mikel, Y-Ispa jêh ri Y-Jôha jêng phung kon bu klâu Y-Bêria.$b$,false),
('bunong-vn','1CH',8,17,null,$b$Y-Sêbadia, Y-Mêsulam, Y-Hiski, Y-Hêber,$b$,false),
('bunong-vn','1CH',8,18,null,$b$Y-Tsmê rai, Y-Islia jêh ri Y-Jôbap$b$,false),
('bunong-vn','1CH',8,19,null,$b$jêng phung kon bu klâu Y-Elpal, Y-Jakim, Y-Sikri, Y-Sapdi,$b$,false),
('bunong-vn','1CH',8,20,null,$b$Y-Êliênai, Y-Silêthai, Y-Êliêl,$b$,false),
('bunong-vn','1CH',8,21,null,$b$Y-Adaya, Y-Bêraya jêh ri Y-Simrat jêng phung kon bu klâu Y-Simei.$b$,false),
('bunong-vn','1CH',8,22,null,$b$Y-Ispan, Y-Êber, Y-Êliêl,$b$,false),
('bunong-vn','1CH',8,23,null,$b$Y-Apdon, Y-Sikri, Y-Hanan,$b$,false),
('bunong-vn','1CH',8,24,null,$b$Y-Hanania, Y-Êlam, Y-Anathôthija,$b$,false),
('bunong-vn','1CH',8,25,null,$b$Y-Ipdeya, jêh ri Y-Pênuel jêng phung kon bu klâu Y-Sasak.$b$,false),
('bunong-vn','1CH',8,26,null,$b$Y-Samsêrai, Y-Sêhari, Y-Atalia,$b$,false),
('bunong-vn','1CH',8,27,null,$b$Y-Jêrêsia, Y-Êli, jêh ri Y-Sikri jêng phung kon bu klâu Y-Jêrôham.$b$,false),
('bunong-vn','1CH',8,28,null,$b$Nây jêng phung kôranh ma ndŭl mpôl khân păng, tĭng nâm noi deh khân păng, jêng kôranh. Phung nây gŭ tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',8,29,null,$b$Y-Jeiêl jêng chô che ma Y-Gabaôn, gŭ tâm ƀon Gabaôn, jêh ri ur păng jêng H'Maka.$b$,true),
('bunong-vn','1CH',8,30,null,$b$Kon bu klâu bôk rah Y-Apdon, jêh ri geh deh đŏng: Y-Sur, Y-Kis, Y-Baal, Y-Nadap,$b$,false),
('bunong-vn','1CH',8,31,null,$b$Y-Gêdor, Y-Ahiô, Y-Sêker,$b$,false),
('bunong-vn','1CH',8,32,null,$b$jêh ri Y-Miklôt (ô băl jêng mbơ̆ ma Y-Simêa). Phung nây tâm ban đŏng gŭ mpeh ma phung ndŭl mpôl khân păng tâm ƀon Yêrusalem ndrel ma mpôl khân păng.$b$,false),
('bunong-vn','1CH',8,33,null,$b$Y-Ner jêng mbơ̆ ma Y-Kis, Y-Kis jêng mbơ̆ ma Y-Sôl, Y-Sôl jêng mbơ̆ ma Y-Jônathan, Y-Mal kisua, Y-Abinadap, jêh ri Y-Êsbaal;$b$,false),
('bunong-vn','1CH',8,34,null,$b$jêh ri kon bu klâu Y-Jônathan jêng Y-Mêri-Baal, jêh ri Y-Mêri-Baal jêng mbơ̆ ma Y-Mika.$b$,false),
('bunong-vn','1CH',8,35,null,$b$Phung kon bu klâu Y-Mika: Y-Pithôn, Y-Mêlek, Y-Tarêa, jêh ri Y-Ahas,$b$,true),
('bunong-vn','1CH',8,36,null,$b$Y-Ahas jêng mbơ̆ ma Y-Jêhôada; jêh ri Y-Jêhôada jêng mbơ̆ ma Y-Alêmet, Y-Asmavet, jêh ri Y-Simri. Y-Simri jêng mbơ̆ ma Y-Môsa.$b$,false),
('bunong-vn','1CH',8,37,null,$b$Y-Môsa jêng mbơ̆ ma Y-Binêa; Y-Binêa jêng mbơ̆ ma Y-Rapha; Y-Rapha jêng mbơ̆ ma Y-Êlêasa; Y-Êlêasa; Y-Êlêasa jêng mbơ̆ ma Y-Asel.$b$,true),
('bunong-vn','1CH',8,38,null,$b$Y-Asel geh prao nuyh kon bu klâu, jêh ri aơ amoh khân păng: Y-Asrikam, Y-Bôkêru, Y-Ismaêl, Y-Sêaria, Y-Ôbadia, jêh ri Y-Hanan. Lĕ rngôch phung nây jêng phung kon bu klâu Y-Asel.$b$,false),
('bunong-vn','1CH',8,39,null,$b$Phung kon bu klâu Y-Êsek oh păng: Y-Ulam kon bu klâu bôk rah, Y-Jêus kon bu klâu rơh bar, jêh ri Y-Êliphêlet kon bu klâu rơh pe,$b$,false),
('bunong-vn','1CH',8,40,null,$b$Phung kon bu klâu Y-Ulam jêng phung ta han janh ktang, blau pănh na, geh âk kon bu klâu jêh ri âk bunuyh, du rhiăng prăm jât nuyh. Lĕ rngôch phung nây jêng phung Benjamin.$b$,false),
('bunong-vn','1CH',9,1,null,$b$Pô ri bu chih amoh tâm ndrom sămƀŭt lĕ rngôch phung Israel tĭng nâm ndŭl mpôl khân păng; jêh ri nau nây bu hŏ chih jêh tâm ndrom Săm ƀŭt Phung Hađăch Israel. Bu njŭn leo phung Yuđa jêng bună tâm n'gor bri Babilôn yor nau khân păng mâu geh gŭ răp jăp ôh.$b$,true),
('bunong-vn','1CH',9,2,null,$b$Phung sĭt lor ntơm sa ơm gŭ tâm bri neh khân păng tâm ƀon khân păng jêng phung Israel, phung kôranh ƀư brah, phung Lêvi, jêh ri phung Nêthinim$b$,false),
('bunong-vn','1CH',9,3,null,$b$Jêh ri ƀa ƀă phung ƀon lan Yuđa, phung Benjamin, phung Êphraim, jêh ri phung Manasê gŭ tâm ƀon Yêrusalem$b$,false),
('bunong-vn','1CH',9,4,null,$b$Y-Uthai kon bu klâu Y-Amihut, kon bu klâu Y-Ômri, kon bu klâu Y-Imri, kon bu klâu Y-Bani bơh phung kon bu klâu Y-Pêres kon bu klâu Yuđa.$b$,false),
('bunong-vn','1CH',9,5,null,$b$Tă tâm phung Silôn geh: Y-Asaya kon dak bôk, jêh ri phung kon bu klâu păng.$b$,false),
('bunong-vn','1CH',9,6,null,$b$Tă tâm phung kon bu klâu Y-Sêra: Y-Jêuêl jêh ri ndŭl deh khân păng, prao rhiăng du rsen nuyh.$b$,true),
('bunong-vn','1CH',9,7,null,$b$Tă tâm phung Benjamin geh: Y-Salu kon bu klâu Y-Mêsulam; Y-Mêsulam kon bu klâu Y-Hôdavia; Y-Hôdavia kon bu klâu Y-Hasênua,$b$,false),
('bunong-vn','1CH',9,8,null,$b$geh đŏng Y-Ipneya, kon bu klâu Y-Jêrôham, Y-Êla kon bu klâu Y-Usi; Y-Usi kon bu klâu Y-Mikri, jêh ri Y-Mêsulam kon bu klâu Y-Sêphatah; Y-Sêphatah kon bu klâu Y-Rêuel; Y-Rêuel kon bu klâu Y-Ipnija;$b$,false),
('bunong-vn','1CH',9,9,null,$b$jêh ri ndŭl deh khân păng tĭng nâm rô̆ khân păng, sĭn rhiăng prăm jât ma prao nuyh. Lĕ rngôch phung nây jêng phung kôranh ndŭl mpôl khân păng tĭng nâm noi khân păng.$b$,false),
('bunong-vn','1CH',9,10,null,$b$Tă tâm phung kôranh ƀư brah geh: Y-Jêdaya, Y-Jêhôyarip, Y-Jakin,$b$,false),
('bunong-vn','1CH',9,11,null,$b$jêh ri Y-Asaria, kon bu klâu Y-Hilkia; Y-Hilkia kon bu klâu Y-Mêsulam; Y-Mêsulam kon bu klâu Y-Sadôk; Y-Sadôk kon bu klâu Y-Mêraiôt; Y-Mêraiôt kon bu klâu Y-Ahi tup, jêng kôranh ma lĕ phung kôranh ngih Brah Ndu;$b$,false),
('bunong-vn','1CH',9,12,null,$b$jêh ri Y-Adaya kon bu klâu Y-Jêrôham; Y-Jêrôham kon bu klâu Y-Pasur; Y-Pasur kon bu klâu Y-Malkija, Y-Malkija kon bu klâu Y-Masai; Y-Masai kon bu klâu Y-Atiêl; Y-Atiêl kon bu klâu Y-Jahsêra; Y-Jahsêra kon bu klâu Y-Mêsulam; Y-Mêsulam kon bu klâu Y-Mêsilômit; Y-Mêsilômit kon bu klâu Y-Imer.$b$,false),
('bunong-vn','1CH',9,13,null,$b$Jêh ri ndŭl mpôl khân păng geh du rbăn pơh rhiăng prao jât nuyh, kôranh ma ndŭl deh khân păng, geh nau blau ngăn prăp ma kan tâm ngih Brah Ndu$b$,false),
('bunong-vn','1CH',9,14,null,$b$Tâm phung Lêvi geh: Y-Sêmaya kon bu klâu Y-Hasup; sau Y-Asrikam, se Y-Hasabia; lĕ rngôch jêng noi deh Y-Mêrari;$b$,false),
('bunong-vn','1CH',9,15,null,$b$geh đŏng Y-Bakbakar, Y-Hêres, Y-Galal, jêh ri Y-Matania, kon bu klâu Y-Mika da dê, sau Y-Sikri, se Y-Asap;$b$,false),
('bunong-vn','1CH',9,16,null,$b$jêh ri Y-Ôbadia kon bu klâu Y-Sêmaya, sau Y-Galal, se Y-Yêduthun; jêh ri Y-Bêrêkia, kon bu klâu Y-Asa, sau Y-Êlkana, phung gŭ tâm ƀon jê̆ jê̆ phung Nêtôphat.$b$,false),
('bunong-vn','1CH',9,17,null,$b$Phung gak mpông pêr geh: Y-Salum, Y-Akup, Y-Tal môn, Y-Ahiman, jêh ri mpôl khân păng, (Y-Salum jêng kôranh).$b$,false),
('bunong-vn','1CH',9,18,null,$b$Khân păng gŭ gak tâm mpông pêr hađăch ta pa lơ; bi kăl e chô yau khân păng jêng phung mât njrăng nhuang ngih ntŭk phung Lêvi.$b$,false),
('bunong-vn','1CH',9,19,null,$b$Y-Salum kon bu klâu Y-Kôrê, sau Y-Êliasap, se Y-Kôra, jêh ri ndŭl mpôl khân păng; nây jêng phung Kôra djôt kan mât uănh ntŭk lăp mpông ngih bok; Kăl e phung chô che khân păng djôt jêh kan tâm nhuang ntŭk ngih Yêhôva jêh ri njrăng ntŭk lăp mpông.$b$,false),
('bunong-vn','1CH',9,20,null,$b$Rnôk sa ơm Y-Phinêas kon bu klâu kôranh ƀư brah Y-Êlêasar jêng kôranh ma khân păng; Yêhôva gŭ ndrel ma păng.$b$,false),
('bunong-vn','1CH',9,21,null,$b$Y-Sakari kon bu klâu Y-Nêsêlêmia jêng nơm mât njrăng mpông pêr ta ntŭk lăp ngih bok tâm rƀŭn.$b$,false),
('bunong-vn','1CH',9,22,null,$b$Lĕ rngôch phung nây bu săch jêh jêng phung mât njrăng ntŭk lăp mpông pêr geh bar rhiăng jât ma bar nuyh. Bu chih jêh amoh khân păng tâm sămƀŭt prăp amoh tĭng nâm ndŭl mpôl tâm ƀon khân păng. Y-Đavit jêh ri nơm geh nau tâm saơ Y-Samuel dơm khân păng tâm kan.$b$,false),
('bunong-vn','1CH',9,23,null,$b$Pô ri khân păng jêh ri phung kon sau khân păng mât njrăng pêr ngih Yêhôva, nâm bu ntĭt jêng phung gak ngih bok.$b$,false),
('bunong-vn','1CH',9,24,null,$b$Phung mât njrăng mpông pêr gŭ ta puăn njônh, pa lơ pa dâng, klơ dor jêh ri tâm rđŭng;$b$,false),
('bunong-vn','1CH',9,25,null,$b$jêh ri mpôl khân păng hôm e tâm ƀon bu ăn văch ăp pơh nar ƀa ƀơ gay gŭ ndrel ma khân păng;$b$,false),
('bunong-vn','1CH',9,26,null,$b$yor lah puăn nuyh kôranh mât njrăng mpông pêr jêng phung Lêvi, mât jrô jêh ri drăp ndơ ngih Brah Ndu.$b$,false),
('bunong-vn','1CH',9,27,null,$b$Khân păng bêch jŭm ngih Brah Ndu, yor lah khân păng geh kan gak, jêh ri khân păng pah kan pơk mpông pêr ăp ôi.$b$,false),
('bunong-vn','1CH',9,28,null,$b$Ƀa ƀă khân păng geh kan mât mray khăl ngan bu dŏng ma kan mbah yơk, yor lah bu ntĭnh ma khân păng kơp ndơ nây tơ lah khân păng djôt leo tâm trôm jêh ri leo ngluh tay pa dih.$b$,false),
('bunong-vn','1CH',9,29,null,$b$Ƀa ƀă phung êng bu dơm kan mray sưng rnơl, jêh ri mray lĕ rngôch khăl ngan kloh ueh, nđâp rnih muy, dak play kriăk ƀâu, dak play ôlivơ, ndơ ƀâu kah, jêh ri dak si ƀâu n'hôl.$b$,false),
('bunong-vn','1CH',9,30,null,$b$Ƀa ƀă phung êng jêng phung bu klâu kôranh ƀư brah pah kan tâm pot dak si ƀâu n'hôl;$b$,false),
('bunong-vn','1CH',9,31,null,$b$jêh ri Y-Matatia du huê Lêvi, kon dak bôk Y-Salum bu klâu Kôra, geh kan ƀư ƀănh n'hơ$b$,false),
('bunong-vn','1CH',9,32,null,$b$Tâm ban đŏng ƀa ƀă phung mpôl khân păng bơh phung Kôhat pah kan nkra piăng let nhhơr ma Brah Ndu$b$,false),
('bunong-vn','1CH',9,33,null,$b$Phung aơ jêng phung mprơ, phung kôranh ma noi deh tâm phung Lêvi, gŭ tâm jrô ngih brah, mâu hôm pah kan êng, yor lah khân păng geh kan pah nar nđâp măng.$b$,false),
('bunong-vn','1CH',9,34,null,$b$Phung nây jêng kôranh noi deh phung Lêvi, tĭng nâm rô̆ khân păng, phung kôranh leo gŭ ta ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',9,35,null,$b$Tâm ƀon Gabaôn Y-Jêiêl Chô che Y-Gabaôn gŭ, jêh ri ur păng jêng H'Maka,$b$,true),
('bunong-vn','1CH',9,36,null,$b$jêh ri kon bu klâu bôk rah păng Y-Apdon, jêh ta nây geh Y-Sur, Y-Kis, Y-Baal, Y-Ner, Y-Nadap,$b$,false),
('bunong-vn','1CH',9,37,null,$b$Y-Gêdor, Y-Ahiô, Y-Sakari, jêh ri Y-Miklôt;$b$,false),
('bunong-vn','1CH',9,38,null,$b$jêh ri Y-Miklôt jêng mbơ̆ ma Y-Simêam; jêh ri phung nây tâm ban đŏng gŭ ntŭk mpeh ma phung ndŭl mpôl khân păng tâm ƀon Yêrusalem ndrel ma phung mpôl khân păng.$b$,false),
('bunong-vn','1CH',9,39,null,$b$Y-Ner jêng mbơ̆ Y-Kis, Y-Kis jêng mbơ̆ Y-Sôl, Y-Sôl jêng mbơ̆ Y-Jônathan, Y-Malkisua, Y-Abinadap, jêh ri Y-Êsbaal;$b$,false),
('bunong-vn','1CH',9,40,null,$b$jêh ri kon bu klâu Y-Jônathan jêng Y-Mêri-Baal; jêh ri Y-Mêri-Baal jêng mbơ̆ ma Y-Mika.$b$,false),
('bunong-vn','1CH',9,41,null,$b$Phung kon bu klâu Y-Mika: Y-Pithôn, Y-Mêlek, Y-Tahrêa, jêh ri Y-Ahas;$b$,false),
('bunong-vn','1CH',9,42,null,$b$jêh ri Y-Ahas jêng mbơ̆ ma Y-Jara, Y-Jara jêng mbơ̆ ma Y-Alêmet, Y-Asmavet, jêh ri Y-Simri; jêh ri Y-Simri jêng mbơ̆ ma Y-Môsa;$b$,false),
('bunong-vn','1CH',9,43,null,$b$Y-Môsa jêng mbơ̆ ma Y-Binêa; jêh ri Y-Rêphaya jêng kon bu klâu păng,$b$,false),
('bunong-vn','1CH',9,44,null,$b$Y-Asel geh prao nuyh kon bu klâu jêh ri amoh khân păng pô aơ: Y-Asrikam, Y-Bôkêru, Y-Ismaêl, Y-Sêaria, Y-Ôbadia, jêh ri Y-Hanan; nây jêng phung kon bu klâu Y-Asel.$b$,false),
('bunong-vn','1CH',10,1,null,$b$Phung Philistin tâm lơh đah phung Israel, jêh ri phung bu klâu Israel du pa năp phung Philistin, jêh ri chôt khĭt ta yôk Gilbôa.$b$,true),
('bunong-vn','1CH',10,2,null,$b$Phung Philistin ban Y-Sôl jêh ri phung kon bu klâu păng; jêh nây phung Philistin nkhĭt Y-Jônathan, Y-Abinadap, jêh ri Y-Malkisua, phung kon bu klâu Y-Sôl.$b$,false),
('bunong-vn','1CH',10,3,null,$b$Nau tâm lơh ktang ngăn, ƀư ăn Y-Sôl nđêh nji; jêh ri phung ta han djôt na tĭng ban păng pănh ƀư sôt păng.$b$,true),
('bunong-vn','1CH',10,4,null,$b$Pô ri Y-Sôl lah ma nơm djôt ndơ tâm lơh păng, “Tŏk đao may jêh ri ntâp gâp, klach ma phung mâu geh koh ntâu aơ văch tât jêh ri ƀư nkrit gâp.” Ƀiă lah nơm djôt ndơ tâm lơh păng mâu ŭch ôh, yor lah ô băl klach ngăn. Yor nây Y-Sôl tŏk đao păng nơm jêh ri kŭnh tom tra ntang ntơh sân đah đao nây.$b$,false),
('bunong-vn','1CH',10,5,null,$b$Tơ lah nơm djôt ndơ tâm lơh păng saơ Y-Sôl lĕ khĭt jêh, ô băl tâm ban đŏng tom săk păng nơm sân đah đao păng nơm jêh ri khĭt.$b$,false),
('bunong-vn','1CH',10,6,null,$b$Pô nây Y-Sôl khĭt; păng jêh ri pe nuyh kon bu klâu păng jêh ri lĕ rngôch ngih păng khĭt ndrel n'grŭp.$b$,false),
('bunong-vn','1CH',10,7,null,$b$Tơ lah lĕ rngôch phung bu klâu Israel gŭ tâm rlŭng saơ phung ta han du jêh, jêh ri saơ Y-Sôl ndrel phung kon bu klâu păng lĕ khĭt jêh, pô ri khân păng cha lơi ƀon jêh ri du. Jêh ri phung Philistin tât jêh ri gŭ tâm ƀon nây.$b$,false),
('bunong-vn','1CH',10,8,null,$b$Kah ôi taơ tơ lah phung Philistin tât ŭch pit sŏk ndô ndơ bơh phung khĭt jêh, khân păng saơ Y-Sôl jêh ri phung kon bu klâu păng chôt jêh ta yôk Gilbôa.$b$,false),
('bunong-vn','1CH',10,9,null,$b$Khân păng pit sŏk ndơ ô băl, djôt leo bôk ô băl jêh ri ndơ ô băl tâm lơh, jêh ri prơh hăn phung mbơh lam n'gor Philistin gay leo nau mhe mhan ma phung rup brah jêh ri phung ƀon lan khân păng.$b$,false),
('bunong-vn','1CH',10,10,null,$b$Khân păng dơm ndơ ô băl tâm lơh tâm ngih brah khân păng, jêh ri pâng yông bôk ô băl tâm ngih brah Dagôn.$b$,true),
('bunong-vn','1CH',10,11,null,$b$Ƀiă lah tơ lah lĕ rngôch phung ƀon Jabes-Galaat tăng lĕ nau phung Philistin ƀư jêh ma Y-Sôl,$b$,false),
('bunong-vn','1CH',10,12,null,$b$lĕ rngôch phung janh ktang dâk hăn sŏk rdu săk jăn Y-Sôl, jêh ri săk jăn phung kon bu klâu păng, jêh ri leo rlet ma ƀon Jabes. Khân păng tâp brôi nting khân ô băl tâm dâng tơm si tâm ƀon Jabes, jêh ri ver ât sông sa tâm pơh nar.$b$,false),
('bunong-vn','1CH',10,13,null,$b$Pô ri Y-Sôl khĭt yor păng mâu gŭ răp jăp ôh, păng mâu geh ôh jêng răp jăp đah Yêhôva tâm nau păng mâu djôt prăp ôh nau Yêhôva ntăm, jêh ri tâm ban đŏng păng ôp jêh ma du huê n'hŭm gay joi nau nchră,$b$,false),
('bunong-vn','1CH',10,14,null,$b$jêh ri mâu joi ôh nau nchră bơh Yêhôva. Yor nây Yêhôva nkhĭt păng, jêh ri jao ƀon bri hađăch păng ma Y-Đavit kon bu klâu Y-Yêsê.$b$,false),
('bunong-vn','1CH',11,1,null,$b$Rnôk nây lĕ rngôch phung Israel tâm rƀŭn ndrel ma Y-Đavit ta ƀon Hêbron jêh ri lah, “Aơ, hên jêng nting may jêh ri mlay puăch may.$b$,true),
('bunong-vn','1CH',11,2,null,$b$Rnôk sa ơm nđâp dôl Y-Sôl jêng hađăch, may yơh njŭn jêh phung Israel luh jêh ri lăp; jêh ri Yêhôva Brah Ndu may lah ma may, “May mra jêng rmăk biăp ma phung ƀon lan gâp Israel, jêh ri may mra jêng kôranh chiă uănh phung ƀon lan gâp$b$,false),
('bunong-vn','1CH',11,3,null,$b$Pô ri lĕ rngôch phung bu bŭnh bu ranh Israel văch ma hađăch ta ƀon Hêbron; jêh ri Y-Đavit ƀư nau tâm nkol đah khân păng ta ƀon Hêbron ta năp Yêhôva, jêh ri khân păng tŏ dak ƀâu kah ma Y-Đavit ăn jêng hađăch chiă uănh phung Israel, tĭng nâm nau Yêhôva ngơi jêh đah Y-Samuel.$b$,false),
('bunong-vn','1CH',11,4,null,$b$Y-Đavit jêh ri lĕ rngôch phung Israel hăn rlet ƀon Yêrusalem, nâm bu ntĭt ƀon Jêbus, ntŭk phung Jêbusit gŭ jêh.$b$,true),
('bunong-vn','1CH',11,5,null,$b$Phung gŭ tâm ƀon Jêbus lah ma Y-Đavit, “May mâu dơi văch lăp ta aơ ôh.” Ƀiă lah Y-Đavit lơh pit pôih nâp ƀon Siôn, nâm bu ntĭt ƀon Y-Đavit,$b$,false),
('bunong-vn','1CH',11,6,null,$b$Y-Đavit lah, “Mbu nơm mra dong phung Jêbusit lor lơn mra jêng kôranh ma phung ta han.” Y-Jôap kon bu klâu Y-Sêruia hăn hao lor, pô nây păng jêng kôranh ro.$b$,false),
('bunong-vn','1CH',11,7,null,$b$Jêh ri Y-Đavit gŭ pôih nâp; yor nây bu ntơ ma ntŭk nây Ƀon Y-Đavit.$b$,false),
('bunong-vn','1CH',11,8,null,$b$Păng ndâk ƀon văr jŭm ntơm bơh Milô; jêh ri Y-Jôap nkra đŏng lĕ ƀon mâu hŏ jêh.$b$,false),
('bunong-vn','1CH',11,9,null,$b$Y-Đavit văch ma hao toyh lơn mro mrăng, yor lah Yêhôva ma phung ta han gŭ ndrel ma păng.$b$,false),
('bunong-vn','1CH',11,10,null,$b$Aơ jêng phung kôranh ma phung ta han janh ktang Y-Đavit, phung kâp rđâng păng nâp tâm ƀon bri hađăch păng, ndrel ma lĕ rngôch phung Israel, gay njêng păng hađăch tĭng nâm nau Yêhôva ngơi jêh di ma phung Israel.$b$,true),
('bunong-vn','1CH',11,11,null,$b$Aơ jêng nau nkoch bri ma phung ta han janh ktang Y-Đavit: Y-Jasôbêam du huê Hakmônit jêng kôranh ma pe nuyh; ma tak păng nkhĭt pe rhiăng nuyh tâm du tơ̆ tâm lơh.$b$,false),
('bunong-vn','1CH',11,12,null,$b$Nơm pa kơi jêh păng tâm pe nuyh ta han janh ktang geh Y-Êlêasar kon bu klâu Y-Dô dô bunuyh Ahôhit.$b$,false),
('bunong-vn','1CH',11,13,null,$b$Păng gŭ ndrel ma Y-Đavit ta ntŭk Pasdamim tơ lah Philistin dăp ta han bra ma nau tâm lơh. Ta nây geh mir bu tuch ba ôrgơ, jêh ri phung ta han nchuăt du pa năp đah phung Philistin.$b$,false),
('bunong-vn','1CH',11,14,null,$b$Ƀiă păng dâk ta nklang mir, king mir, jêh ri nkhĭt phung Philistin; jêh ri Yêhôva tâm rklaih khân păng ma nau dơi toyh.$b$,false),
('bunong-vn','1CH',11,15,null,$b$Pe nuyh tâm phung pe jât nuyh kôranh ta han trŭnh hăn leo trôm Lŭ Adalam, rlet ma Y-Đavit. Bi phung ta han Philistin gŭ njơh ƀư rmlak tâm rlŭng Rêphaim.$b$,false),
('bunong-vn','1CH',11,16,null,$b$Nôk nây Y-Đavit gŭ tâm pôih nâp; jêh ri pôih ta han phung Philistin gŭ ta ƀon Ƀetlêhem.$b$,false),
('bunong-vn','1CH',11,17,null,$b$Y-Đavit lah ma nau klâng, “Vơ! Ŭch ngăn bu ăn dak nhêt ma gâp tă bơh ndrâm dak ƀon Ƀetlêhem êp kêng mpông pêr!”$b$,false),
('bunong-vn','1CH',11,18,null,$b$Pô ri pe nuyh ta han janh ktang lăp rgăn năp tâm nhuang phung Philistin jêh ri bâk dak, tă tâm ndrâm ntu ƀon Ƀetlêhem êp mpông pêr, jêh ri djôt leo ma Y-Đavit. Ƀiă lah Y-Đavit mâu ŭch nhêt ôh; păng nkhŭt dak nây ta năp măt Yêhôva,$b$,false),
('bunong-vn','1CH',11,19,null,$b$jêh ri lah, “Mâu ôh, ta năp Brah Ndu gâp mâu mâp ƀư ôh nau aơ. Gâp mra nhêt lĕ mham nau rêh phung ta han aơ? Yor lah khân păng sân săk jăn gay leo dak nây.” Yor nây păng mâu ŭch nhêt ôh dak nây. Nau nây phung pe nuyh janh ktang hŏ ƀư jêh.$b$,false),
('bunong-vn','1CH',11,20,null,$b$Y-Abisai oh Y-Jôap jêng kôranh ma phung pe nuyh. Păng rjăng tak păng ƀư ma pe rhiăng nuyh bu klâu jêh ri nkhĭt khân păng, jêh ri geh nau lư n'găr ndrel ma pe nuyh nây.$b$,false),
('bunong-vn','1CH',11,21,null,$b$Păng geh lư n'găr lơn ma phung pe jât nuyh, jêh ri jêng kôranh ma khân păng; ƀiă lah nau lư n'găr păng mâu tâm ban ôh đah phung pe nuyh lor sa ơm nây.$b$,false),
('bunong-vn','1CH',11,22,null,$b$Geh đŏng Y-Bênaya kon bu klâu Y-Jêhôida jêng du huê janh ktang bơh ƀon Kapsêel, ƀư kan toyh; păng nkhĭt bar hê bunuyh Môap janh nănh lơn ma lĕ rngôch; tâm ban đŏng păng hăn trŭnh nkhĭt du mlâm yau mŭr tâm du ntŭk trôm ta nar geh măng lĭng (geh dak pler nkâm).$b$,false),
('bunong-vn','1CH',11,23,null,$b$Păng nkhĭt du huê Êjipt, du huê toyh juat, prăm hăt prêh. Bu klâu Êjipt djôt rnă tak nâm bu mâng mpeh tanh; ƀiă lah Y-Bênaya- trŭnh hăn ma păng djôt du mlâm mâng jra jêh ri pit tak ta ti bu klâu Êjipt, jêh ri nkhĭt ô băl ma tak păng nơm.$b$,true),
('bunong-vn','1CH',11,24,null,$b$Nau nây Y-Bênaya, kon bu klâu Y-Jêhôida ƀư, jêh ri geh amoh lư n'găr ndrel ma pe nuyh ta han janh ktang nây.$b$,false),
('bunong-vn','1CH',11,25,null,$b$Păng geh lư n'găr ndrel ma phung pe jât nuyh, ƀiă lah nau lư n'găr păng mâu tâm ban ôh đah phung pe nuyh lor sa ơm nây. Y-Đavit dơm kan păng kôranh phung gak hađăch.$b$,false),
('bunong-vn','1CH',11,26,null,$b$Phung bu klâu janh ktang tâm phung ta han geh: Y-Asahel oh Y-Jôap, Y-Êlhanan kon bu klâu Y-Dôdô bơh ƀon Ƀetlêhem.$b$,false),
('bunong-vn','1CH',11,27,null,$b$Y-Samôt bơh ƀon Sarôt; Y-Hêles bunuyh Pêlôn;$b$,false),
('bunong-vn','1CH',11,28,null,$b$Y-Ira kon bu klâu Y-Ikês bơh ƀon Têkôa, Y-Abiêser bơh ƀon Anathôt;$b$,false),
('bunong-vn','1CH',11,29,null,$b$Y-Sibêkal bunuyh Husatit; Y-Itai bunuyh Ahôhit;$b$,false),
('bunong-vn','1CH',11,30,null,$b$Y-Maharal bơh ƀon Nêtôpa;$b$,false),
('bunong-vn','1CH',11,31,null,$b$Y-Itai kon bu klâu Y-Ribai bơh ƀon Gibêa tâm mpôl phung Benjamin; Y-Bênaya bơh ƀon Pirathôn;$b$,false),
('bunong-vn','1CH',11,32,null,$b$Y-Hurai tă lơh dak n'hor Gas; Y-Abiêl bunuyh Arba;$b$,false),
('bunong-vn','1CH',11,33,null,$b$Y-Asmavet bơh ƀon Bahrum; Y-Êliahba bơh ƀon salbôn;$b$,false),
('bunong-vn','1CH',11,34,null,$b$Y-Hasem bunuyh Gisônit; Y-Jônathan kon bu klâu Y-Sagê bunuyh Hararit;$b$,false),
('bunong-vn','1CH',11,35,null,$b$Y-Hiam kon bu klâu Y-Sakar, bunuyh Hararit; Y-Êliphal kon bu klâu Y-Ur;$b$,false),
('bunong-vn','1CH',11,36,null,$b$Y-Hêpher bunuyh Mêkêratit; Y-Ahija bunuyh Pêlônit;$b$,false),
('bunong-vn','1CH',11,37,null,$b$Y-Hêsrô bơh yôk Karmel, Y-Narai kon bu klâu Y-Êsbai;$b$,false),
('bunong-vn','1CH',11,38,null,$b$Y-Yôel oh Y-Nathan, Y-Miphar kon bu klâu Y-Hagri;$b$,false),
('bunong-vn','1CH',11,39,null,$b$Y-Sêlek du huê Amôn, Y-Naharai bơh ƀon Bêorôt, nơm djôt ndơ tâm lơh Y-Jôap kon bu klâu Y-Sêruia;$b$,false),
('bunong-vn','1CH',11,40,null,$b$Y-Ira du huê Ithrit, Y-Garep bu klâu Ithrit;$b$,false),
('bunong-vn','1CH',11,41,null,$b$Y-Uri du huê Hitit, Y-Saƀat kon bu klâu Y-Ahlai;$b$,false),
('bunong-vn','1CH',11,42,null,$b$Y-Adina kon bu klâu Y-Sisa bơh mpôl phung Ruben, du huê kôranh tâm phung Ruben, jêh ri pe jât nuyh ndrel ma păng;$b$,false),
('bunong-vn','1CH',11,43,null,$b$Y-Hanan kon bu klâu Y-Maka, jêh ri Y-Jôsaphat bunuyh Hitit;$b$,false),
('bunong-vn','1CH',11,44,null,$b$Y-Usia bunuyh Asteratit, Y-Sama jêh ri Y-Jêiêl phung kon bu klâu Y-Hôtham du huê Arôer;$b$,false),
('bunong-vn','1CH',11,45,null,$b$Y-Jêdiaêl kon bu klâu Y-Simri, jêh ri Y-Jôha oh păng, du huê Tisit;$b$,false),
('bunong-vn','1CH',11,46,null,$b$Y-Êliêl du huê Mahawit; Y-Jêribai, jêh ri Y-Jêsavia, phung kon bu klâu Y-Êlnam jêh ri Y-It ma du huê Môap;$b$,false),
('bunong-vn','1CH',11,47,null,$b$Y-Êliêl, Y-Ôbet jêh ri Y-Jasiêl du huê Mêsôba.$b$,false),
('bunong-vn','1CH',12,1,null,$b$Aơ jêng phung bu klâu văch tĭng Y-Đavit ta ƀon Siklak, dôl păng du ndĕ đah Y-Sôl kon bu klâu Y-Kis; jêh ri khân păng jêng tâm phung ta han janh ktang kơl Y-Đavit tâm lơh.$b$,true),
('bunong-vn','1CH',12,2,null,$b$Khân păng jêng phung ta han djôt na jêh ri dơi pănh na, blau klŭp lŭ ti pa ma mâu lah ti pa chiau. Khân păng jêng phung Benjamin, noi Y-Sôl.$b$,false),
('bunong-vn','1CH',12,3,null,$b$Kôranh khân păng jêng Y-Ahiêser, jêh ri Y-Jôas, lĕ bar kon bu klâu Y-Sêma bơh ƀon Gibêa; Y-Jêsiêl jêh ri Y-Pêlet, phung kon bu klâu Y-Asmavet; Y-Beraka, Y-Jêhu bơh ƀon Anathôt,$b$,true),
('bunong-vn','1CH',12,4,null,$b$Y-Ismaya bơh ƀon Gabaôn, du huê ta han nănh ta nklang pe jât nuyh jêh ri du huê kôranh chiă uănh pe jât nuyh nây; Y-Yêrêmi, Y-Jahasiêl, Y-Jôhanan, Y-Jôsabat bơh ƀon Gêdêra,$b$,false),
('bunong-vn','1CH',12,5,null,$b$Y-Êlusai, Y-Jêrimôt, Y-Bêalia, Y-Sêmaria, Y-Sêphatia bunuyh Harup;$b$,false),
('bunong-vn','1CH',12,6,null,$b$Y-Êlkana, Y-Isiya, Y-Asarel, Y-Jôêser, jêh ri Jasôbêam du huê Kôra;$b$,false),
('bunong-vn','1CH',12,7,null,$b$Y-Jôêla jêh ri Y-Sêbadia, phung kon bu klâu Y-Jêrôham bơh ƀon Gêdôr.$b$,false),
('bunong-vn','1CH',12,8,null,$b$Tâm ndŭl mpôl Gat, hăn gŭ mpeh Y-Đavit ta pôih nâp tâm bri rdah jêng phung janh ktang jêh ri blau jêh nau tâm lơh, n'hăk djôt khêl jêh ri rjăng tak muh măt khân păng nâm bu muh măt yau mŭr, jêh ri dơi nchuăt prăl nâm bu yơng ta klơ yôk;$b$,false),
('bunong-vn','1CH',12,9,null,$b$Y-Êser jêng kôranh, Y-Ôbadi groi păng, Y-Êliap rơh pe,$b$,false),
('bunong-vn','1CH',12,10,null,$b$Y-Mismana rơh puăn, Y-Yêrêmi rơh prăm,$b$,false),
('bunong-vn','1CH',12,11,null,$b$Y-Atai rơh prao, Y-Êliêl rơh pơh,$b$,false),
('bunong-vn','1CH',12,12,null,$b$Y-Jôhanan rơh pham, Y-Êlsabat rơh sĭn,$b$,false),
('bunong-vn','1CH',12,13,null,$b$Y-Yêrêmi rơh jât, Y-Mak-Banai rơh jât ma nguay.$b$,false),
('bunong-vn','1CH',12,14,null,$b$Phung Gat nây jêng phung kôranh ta han, phung jê̆ lơn chiă uănh du rhiăng nuyh jêh ri kôranh toyh lơn chiă uănh du rbăn nuyh.$b$,false),
('bunong-vn','1CH',12,15,null,$b$Amoh phung ta han rgăn dak krong Yurdan ta khay nguay, dôl dak krong hao toyh lip băm bong, jêh ri mprơh ƀư pru pra lĕ rngôch phung gŭ tâm rlŭng mpeh pa lơ jêh ri mpeh pa dâng.$b$,false),
('bunong-vn','1CH',12,16,null,$b$Ƀă ƀă phung ta han Benjamin jêh ri phung Yuđa văch tât pôih nâp rlet ma Y-Đavit.$b$,false),
('bunong-vn','1CH',12,17,null,$b$Y-Đavit luh gay tâm mâp đah khân păng jêh ri lah ma khân păng, “Tơ lah khân păng văch ma gâp ma nau rŏng gay kơl gâp, nuih n'hâm gâp mra rŏng ma khân may; ƀiă lah tơ lah khân may ŭch ƀlăch ƀlêr jao gâp ma phung rlăng gâp, nđâp tơ lah mâu geh nau tih ôh tâm ti gâp pô nây ăn Brah Ndu phung che he saơ jêh ri nduyh khân may.”$b$,false),
('bunong-vn','1CH',12,18,null,$b$Jêh ri Huêng Brah trŭnh gŭ ta Y-Amasai, Kôranh ma phung pe jât nây, jêh ri bu lah, “Hên jêng phung may, Hơi Y-Đavit, jêh ri gŭ ndrel ma may, Hơi kon bu klâu Y-Yêsê! Nau đăp mpăn, nau đăp mpăn ma may, jêh ri nau đăp mpăn ma phung kơl may! Yor lah Brah Ndu may kơl may.” Jêh ri Y-Đavit rom Khân păng, jêh ri njêng khân păng phung kôranh ma ta han păng.$b$,false),
('bunong-vn','1CH',12,19,null,$b$Geh ƀa ƀă phung mpôl Manasê hăn tĭng Y-Đavit tơ lah păng hăn tĭng ndrel ma phung Philistin gay tâm lơh đah Y-Sôl. (Ƀiă lah Y-Đavit mâu kơl phung Philistin ôh, yor lah phung kôranh Philistin nchră jêh ri prơh hăn păng lah, “Păng mra du gŭ mpeh ma Kôranh păng Y-Sôl jêng nau mhĭk ma he”).$b$,false),
('bunong-vn','1CH',12,20,null,$b$Dôl Y-Đavit hăn ma ƀon Siklak phung ta han Manasê aơ hăn gŭ ndrel ma păng: Y-Atna, Y-Jôsabat, Jêdiêl, Y-Mikel, Y-Jôsabat, Y-Êlihu, jêh ri Y-Silêthai, ăp nơm jêng kôranh ma du rbăn nuyh phung ta han Manasê.$b$,false),
('bunong-vn','1CH',12,21,null,$b$Khân păng kơl Y-Đavit tâm rdâng đah phung văch pit in; yor lah lĕ rngôch khân păng jêng phung ta han janh ktang, jêh ri jêng phung kôranh ta han.$b$,false),
('bunong-vn','1CH',12,22,null,$b$Yor lah ăp nar phung bunuyh văch ƀa ƀơ ma Y-Đavit gay kơl păng, tât geh du phung ta han âk nâm bu phung ta han Brah Ndu.$b$,true),
('bunong-vn','1CH',12,23,null,$b$Aơ rnoh mpôl phung ta han văch ma Y-Đavit tâm ƀon Hêbron, gay jao ƀon bri hađăch Y-Sôl ma Y-Đavit, tĭng nâm nau Yêhôva ngơi.$b$,true),
('bunong-vn','1CH',12,24,null,$b$Phung ta han Yuđa djôt khêl jêh ri tak geh prao rbăn pham rhiăng nuyh ta han djôt ndơ tâm lơh.$b$,false),
('bunong-vn','1CH',12,25,null,$b$Phung ta han Simêôn phung ta han janh ktang geh pơh rbăn du rhiăng nuyh.$b$,false),
('bunong-vn','1CH',12,26,null,$b$Phung Lêvi geh puăn rbăn prao rhiăng nuyh.$b$,false),
('bunong-vn','1CH',12,27,null,$b$Du huê kôranh, Y-Jêhôida, bơh ngih Y-Arôn văch ndrel ma pe rbăn pơh rhiăng nuyh.$b$,false),
('bunong-vn','1CH',12,28,null,$b$Y-Sadôk jêng du huê bu klâu ndăm janh ktang văch ndrel ma bar jât ma bar nuyh kôranh ta han bơh mbơ̆ păng.$b$,true),
('bunong-vn','1CH',12,29,null,$b$Phung ta han Benjamin, phung mpôl Y-Sôl, geh pe rbăn nuyh, âk lơn tâm phung khân păng hôm dôl tĭng ngih Y-Sôl sa ơm.$b$,false),
('bunong-vn','1CH',12,30,null,$b$Phung Êphraim geh bar rmưn bar rbăn pham rhiăng nuyh ta han janh ktang geh lư n'găr tâm ngih mbơ̆ khân păng.$b$,false),
('bunong-vn','1CH',12,31,null,$b$Phung du n'gul mpôl Manasê geh du rmưn pham rbăn nuyh, bu ntĭnh ăn hăn njêng Y-Đavit hađăch.$b$,false),
('bunong-vn','1CH',12,32,null,$b$Phung Isakar, phung gĭt rblang lĕ nau tât dơi gĭt moh nau di ma phung Israel ƀư, geh bar rhiăng nuyh kôranh, jêh ri lĕ rngôch mpôl khân păng tâm dâng nau khân păng chiă uănh.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1CH',12,33,null,$b$Phung Sabulôn geh prăm rmưn nuyh ta han gĭt jêh tâm lơh, djôt ndơ tâm lơh ăp ntil, gay kơl Y-Đavit ma du nau ŭch.$b$,false),
('bunong-vn','1CH',12,34,null,$b$Phung Naptali geh du rbăn kôranh ta han ndrel ma pe rmưn pơh rbăn nuyh ta han djôt khêl jêh ri tak.$b$,false),
('bunong-vn','1CH',12,35,null,$b$Phung Dan, geh bar rmưn pham rbăn prao rhiăng nuyh ta han djôt ndơ tâm lơh.$b$,false),
('bunong-vn','1CH',12,36,null,$b$Phung Aser, geh puăn rmưn nuyh ta han blau tâm lơh nkra ma nau tâm lơh.$b$,false),
('bunong-vn','1CH',12,37,null,$b$Bi phung Ruben, jêh ri phung Gat jêh ri du n'gul phung Manasê bơh kăl tê̆ dak krong Yurdan geh du rsen bar rmưn nuyh ta han djôt ăp ntil ndơ tâm lơh.$b$,false),
('bunong-vn','1CH',12,38,null,$b$Lĕ rngôch phung aơ jêng phung ta han tâm lơh dăp jêh ma nau tâm lơh văch rlet ma ƀon Hêbron bêng ma nau ŭch njêng Y-Đavit ƀư hađăch chiă uănh lĕ rngôch phung Israel; tâm ban đŏng lĕ rngôch phung Israel hôm e geh knŏng du nau mĭn gay njêng Y-Đavit hađăch.$b$,false),
('bunong-vn','1CH',12,39,null,$b$Khân păng gŭ ta nây ndrel ma Y-Đavit tâm pe nar, sông sa jêh ri nhêt, yor lah phung oh nâu khân păng nkra jêh nau nhêt sa ma khân păng.$b$,false),
('bunong-vn','1CH',12,40,null,$b$Tâm ban đŏng phung chiau meng khân păng tă bơh ntŭk ngai nâm bu mpôl Isakar, mpôl Sabulôn, jêh ri mpôl Naptali văch leo ndơ sông sa rdeng ma seh, seh samô, seh bri, jêh ri ma ndrôk, ăp ntil ndơ sông sa rmeh rmai, ƀănh play rvi, rkŭm play krĭak ƀâu kro, jêh ri dak play kriăk ƀâu, jêh ri dak play ôlivơ, ndrôk jêh ri biăp, yor lah geh nau hâk răm ta nklang phung Israel.$b$,true),
('bunong-vn','1CH',13,1,null,$b$Y-Đavit tâm chră ndrel ma phung kôranh ma du rbăn nuyh jêh ri kôranh ma du rhiăng nuyh, ăp nơm kôranh uănh bôk.$b$,true),
('bunong-vn','1CH',13,2,null,$b$Y-Đavit lah ma lĕ rngôch phung Israel tâm rƀŭn, “Tơ lah khân may mĭn jêng ueh, jêh ri tơ lah jêng nau Yêhôva Brah Ndu he ŭch, ăn he prơh bunuyh hăn mbơh lam ntŭk, ma phung oh nâu he hôm e tâm lam n'gor Israel, jêh ri nđâp ma phung kôranh ƀư brah jêh ri phung Lêvi tâm ƀon geh ndrêch gơ̆ , gay ma khân păng dơi văch tâm rƀŭn ndrel ma he.$b$,false),
('bunong-vn','1CH',13,3,null,$b$Jêh ri ăn he tung leo đŏng hip Brah Ndu he sĭt ma he; yor lah tâm rnôk Y-Sôl, he mâu ŭch chrê ôh.”$b$,false),
('bunong-vn','1CH',13,4,null,$b$Lĕ rngôch phung tâm rƀŭn dơn mra ƀư pô nây, yor lah nau nây jêng di ta năp măt lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','1CH',13,5,null,$b$Pô nây Y-Đavit tâm rƀŭn lĕ rngôch phung Israel ntơm bơh ƀon Sihôr tâm n'gor bri Êjipt tât ma ntŭk lăp ƀon Hamat, gay tung leo hip Brah Ndu bơh ƀon Kiriat- Jêarim.$b$,true),
('bunong-vn','1CH',13,6,null,$b$Y-Đavit jêh ri lĕ rngôch phung Israel hăn hao ma ƀon Bala, bu ntơ ƀon Kiriat-Jêarim, jêng ƀon tâm n'gor Yuđa, gay tung leo tă bơh ntŭk nây hip Brah Ndu, bu ntơ Amoh Yêhôva, nơm gŭ ta nklang phung Chêrubim, jêng ntŭk vơh vơl amoh Păng.$b$,false),
('bunong-vn','1CH',13,7,null,$b$Khân păng rdeng hip Brah Ndu ma ndeh ndrôk mhe tă bơh ngih Y-Abinadap; jêh nây Y-Usa jêh ri Y-Ahiô ƀĭt ndeh.$b$,true),
('bunong-vn','1CH',13,8,null,$b$Y-Đavit jêh ri lĕ rngôch phung Israel ƀư nau hâk răm ta năp Brah Ndu ma lĕ nau pâl khân păng dơi, ma nau mprơ, uh n'hôm, kreh gong rêng, goh gâr, rgu dang nteh, jêh ri uh nŭng.$b$,false),
('bunong-vn','1CH',13,9,null,$b$Tơ lah khân păng tât ta ntŭk bu mprah ba ƀon Kidôn, Y-Usa yơh ti păng gay ŭch rđâng hip, yor lah ndrôk chêh prah.$b$,false),
('bunong-vn','1CH',13,10,null,$b$Pô nây Yêhôva hao ji nuih ma Y-Usa, jêh ri dong ô băl yor lah ô băl yơr ti djôt hip, jêh ri ô băl khĭt ta nây ta năp Brah Ndu.$b$,false),
('bunong-vn','1CH',13,11,null,$b$Y-Đavit nuih yor lah Yêhôva ƀư jêh ma Y-Usa; jêh ri bu ntơ ntŭk nây Pêres-Usa tât ma nar aơ.$b$,false),
('bunong-vn','1CH',13,12,null,$b$Jêh ri Y-Đavit klach ma Brah Ndu nar nây, jêh ri păng lah, “Mâm gâp dơi njŭn leo hip Brah Ndu ma ngih gâp?”$b$,false),
('bunong-vn','1CH',13,13,null,$b$Pô ri Y-Đavit mâu njŭn leo ôh hip lăp tâm ƀon Y-Đavit, ƀiă lah veh nglăp hip tâm ngih Y-Ôbet-Êđôm bu klâu Gitit.$b$,false),
('bunong-vn','1CH',13,14,null,$b$Hip Brah Ndu hôm e tâm ngih Y-Ôbet-Êđôm tâm pe khay; jêh ri Yêhôva ăn nau ueh lăng ma ngih Y-Ôbet-Êđôm jêh ri ma lĕ rngôch ndơ păng geh.$b$,false),
('bunong-vn','1CH',14,1,null,$b$Y-Hiram hađăch ƀon Tir prơh bunuyh hăn mbơh ma Y-Đavit, jêh njuăl tơm si sêdar nđâp phung pah kan đah lŭ jêh ri phung trah meh gay ndâk du mlâm ngih ma păng.$b$,true),
('bunong-vn','1CH',14,2,null,$b$Y-Đavit gĭt ma Yêhôva njêng păng ƀư hađăch chiă uănh phung Israel, jêh ri gĭt ma ƀon bri hađăch geh nau bu yơk yor phung ƀon lan păng phung Israel.$b$,false),
('bunong-vn','1CH',14,3,null,$b$Y-Đavit sŏk đŏng âk ur tâm ƀon Yêrusalem, jêh ri Y-Đavit geh âk đŏng kon bu klâu jêh ri kon bu ur.$b$,true),
('bunong-vn','1CH',14,4,null,$b$Aơ amoh phung kon păng geh tâm ƀon Yêrusalem: Y-Samua, Y-Sôbap, Y-Nathan, Y-Salômôn,$b$,false),
('bunong-vn','1CH',14,5,null,$b$Y-Iphar, Y-Êlisua, Y-Êlpêlêt,$b$,false),
('bunong-vn','1CH',14,6,null,$b$Y-Nôga, Y-Nêphek, Y-Japhia,$b$,false),
('bunong-vn','1CH',14,7,null,$b$Y-Êlisama, Y-Bêliada, jêh ri Y-Êliphêlet.$b$,false),
('bunong-vn','1CH',14,8,null,$b$Tơ lah phung Philistin tăng bu tŏ jêh dak ƀâu kah ăn Y-Đavit jêng hađăch chiă uănh lĕ rngôch phung Israel, lĕ rngôch phung Philistin hăn hao joi Y-Đavit, Y-Đavit tăng lư nau nây jêh ri luh hăn tâm lơh đah khân păng.$b$,true),
('bunong-vn','1CH',14,9,null,$b$Phung Philistin văch gay ŭch sŏk gro ndô ndơ tâm rlŭng Rêphaim,$b$,false),
('bunong-vn','1CH',14,10,null,$b$Y-Đavit ôp ma Brah Ndu, “Gâp mra hăn tâm lơh lĕ đah phung Philistin? May mra jao lĕ khân păng tâm ti gâp?” Yêhôva lah ma păng, “Hăn hom, jêh ri gâp mra jao khân păng tâm ti may.”$b$,false),
('bunong-vn','1CH',14,11,null,$b$Pô ri păng hăn ma ƀon Baal-Pêrisim, jêh ri Y-Đavit dơi đah khân păng ta nây. Jêh ri Y-Đavit lah, “Brah Ndu ƀư rai jêh phung rlăng gâp ma ti gâp nâm bu dak lip.” Yor nây bu ntơ ntŭk nây Baal Pêrisim.$b$,false),
('bunong-vn','1CH',14,12,null,$b$Khân păng cha lơi rup brah khân păng ta nây. Y-Đavit ntĭnh, jêh ri bu su lơi rup brah nây.$b$,false),
('bunong-vn','1CH',14,13,null,$b$Phung Philistin hăn pit in đŏng tâm rlŭng.$b$,false),
('bunong-vn','1CH',14,14,null,$b$Tơ lah Y-Đavit ôp tay ma Brah Ndu, Brah Ndu lah ma păng, “Lơi may hăn hao tĭng, ôh khân păng; ƀiă lah ndăch pa kơi khân păng jêh ri hăn lơh mpeh pa năp tơm si balsam.$b$,false),
('bunong-vn','1CH',14,15,null,$b$Tơ lah may tăng nteh jâng ta klơ chiông si balsam, pô ri hăn tâm lơh hom, yor lah Brah Ndu luh hăn lor jêh ma may gay dong phung ta han Philistin.$b$,false),
('bunong-vn','1CH',14,16,null,$b$Y-Đavit ƀư tĭng nâm Brah Ndu ntĭnh jêh ma păng, jêh ri khân păng tâm lơh dơi đah phung ta han Philistin ntơm bơh ƀon Gabaôn tât ma ƀon Gêser.$b$,false),
('bunong-vn','1CH',14,17,null,$b$Nau lư n'găr Y-Đavit bu tăng lư lam n'gor bri; jêh ri Yêhôva ăn lĕ rngôch ntil mpôl bunuyh klach ma păng.$b$,false),
('bunong-vn','1CH',15,1,null,$b$Y-Đavit ndâk âk rplay ngih ma păng nơm tâm ƀon Y-Đavit, jêh ri păng nkra du ntŭk ma hip Brah Ndu, jêh ri ndâk du mlâm ngih bok ma hip nây.$b$,true),
('bunong-vn','1CH',15,2,null,$b$Jêh ri Y-Đavit lah, “Mâu geh phung êng ôh, knŏng phung Lêvi dơi tung hip Brah Ndu, yor lah Yêhôva săch jêh khân păng ăn tung hip Yêhôva jêh ri pah kan ma păng n'ho ro.”$b$,false),
('bunong-vn','1CH',15,3,null,$b$Y-Đavit tâm rƀŭn lĕ rngôch phung Israel ta ƀon Yêrusalem, gay tung leo hip Yêhôva ma ntŭk păng nkra jêh ma hip.$b$,true),
('bunong-vn','1CH',15,4,null,$b$Y-Đavit ăt tâm rƀŭn đŏng ndrel lĕ rngôch phung kon bu klâu Y-Arôn jêh ri phung Lêvi:$b$,false),
('bunong-vn','1CH',15,5,null,$b$Phung noi deh Y-Kôhat geh Y-Uriêl jêng kôranh, ndrel ma du rhiăng bar jât nuyh phung oh nâu păng;$b$,false),
('bunong-vn','1CH',15,6,null,$b$phung noi deh Y-Mêrari geh Y-Asia jêng kôranh, ndrel ma bar rhiăng bar jât nuyh phung oh nâu păng;$b$,false),
('bunong-vn','1CH',15,7,null,$b$Phung noi deh Y-Gersôm geh Y-Jôel jêng kôranh, ndrel ma du rhiăng pe jât nuyh phung oh nâu păng;$b$,false),
('bunong-vn','1CH',15,8,null,$b$Phung noi deh Y-Êlisapan geh Y-Sêmaya jêng kôranh, ndrel ma bar rhiăng nuyh oh nâu păng;$b$,false),
('bunong-vn','1CH',15,9,null,$b$phung noi deh Y-Hêbron geh Y-Êliêl jêng kôranh, ndrel ma pham jât nuyh oh nâu păng,$b$,false),
('bunong-vn','1CH',15,10,null,$b$phung noi deh Y-Usiêl geh Y-Aminadap jêng kôranh, ndrel ma du rhiăng jât ma bar nuyh phung oh nâu păng.$b$,false),
('bunong-vn','1CH',15,11,null,$b$Jêh ri Y-Đavit kuăl tâm rƀŭn phung kôranh ƀư brah Y-Sadôk jêh ri Y-Abiathar, jêh ri phung Lêvi Y-Uriêl, Y-Asaya, Y-Jôel, Y-Sêmaya, Y-Êliêl, jêh ri Y-Aminadap,$b$,true),
('bunong-vn','1CH',15,12,null,$b$Jêh ri lah ma khân păng, khân may jêng kôranh ma noi deh khân may phung Lêvi; ƀư kloh hom khân may nơm, khân may jêh ri phung oh nâu khân may, pô ri khân may dơi tung hip Yêhôva Brah Ndu Israel ma ntŭk gâp nkra jêh ma hip$b$,false),
('bunong-vn','1CH',15,13,null,$b$Yor lah nôk sa ơm khân may mâu mâp ôh tung hip, jêh ri he mâu chiă uănh păng tĭng nâm Yêhôva ntĭnh jêh; Yor ri Yêhôva Brah Ndu ƀư ma he.$b$,false),
('bunong-vn','1CH',15,14,null,$b$Pô ri phung kôranh ƀư brah jêh ri phung Lêvi ƀư kloh lơi khân păng nơm, gay tung leo hip Yêhôva Brah Ndu Israel.$b$,true),
('bunong-vn','1CH',15,15,null,$b$Phung Lêvi tung hip Brah Ndu ta săng nglik khân păng ma mâng, tĭng nâm nau Yêhôva ngơi ntĭnh jêh ma Y-Môis.$b$,true),
('bunong-vn','1CH',15,16,null,$b$Tâm ban đŏng Y-Đavit ntĭnh ma phung kôranh Lêvi ăn dơm kan phung oh nâu khân păng jêng phung mprơ mra kreh gong rêng, uh n'hôm, rgu nteh dang ăn huy gay geh bâr nteh hâk răm.$b$,true),
('bunong-vn','1CH',15,17,null,$b$Pô nây phung Lêvi dơm Y-Hêman kon bu klâu Y-Jôel; jêh ri oh păng Y-Asap kon bu klâu Y-Bêrêkia; jêh ri bơh phung noi deh Y-Mêrari phung oh nâu khân păng, dơm Y-Êthan kon bu klâu Y-Kusaya,$b$,false),
('bunong-vn','1CH',15,18,null,$b$ndrel ma khân păng phung oh nâu khân păng tâm mpôl rơh bar, Y-Sakari, Y-Jasiêl, Y-Sêmiramôt, Y-Jêhiêl, Y-Uni, Y-Êliap, Y-Bênaya, Y-Maseya, Y-Matithia, Y-Êliphêlêhu, jêh ri Y-Mikneya, jêh ri phung mât njrăng mpông pêr Y-Ôbet-Êđôm jêh ri Y-Jêlêt.$b$,false),
('bunong-vn','1CH',15,19,null,$b$Phung mprơ, Y-Hêman, Y-Asap, jêh ri Y-Êtam geh kan rgu dang kông,$b$,true),
('bunong-vn','1CH',15,20,null,$b$Y-Sakari, Y-Asriêl, Y-Sêmiramôt, Y-Jêhiêl, Y-Uni, Y-Êliap, Y-Maseya jêh ri Y-Bênaya geh kan kreh gong rêng tĭng nâm Alamôt;$b$,false),
('bunong-vn','1CH',15,21,null,$b$ƀiă lah Y-Matithia, Y-Êliphêlêhu, Y-Mikneya, geh kan leo khân păng dôl uh n'hôm tĭng Sêminit.$b$,false),
('bunong-vn','1CH',15,22,null,$b$Y-Kênania jêng kôranh ma phung Lêvi mpât mprơ geh kan leo nau mprơ, yor lah păng gĭt vât kan nây.$b$,false),
('bunong-vn','1CH',15,23,null,$b$Y-Bêrêkia jêh ri Y-Êlkana jêng phung mât njrăng mpông pêr ma hip$b$,true),
('bunong-vn','1CH',15,24,null,$b$Y-Sêbania, Y-Jôsaphat, Y-Nêthanel, Y-Amasai, Y-Sakari, Y-Bênaya, jêh ri Y-Êliêser phung kôranh ƀư brah mra uh nŭng ta năp hip Brah Ndu. Y-Ôbet-Êđôm jêh ri Y-Jêhia tâm ban đŏng jêng phung mât njrăng mpông pêr ma hip.$b$,false),
('bunong-vn','1CH',15,25,null,$b$Pô ri Y-Đavit jêh ri phung bu bŭnh bu ranh Israel jêh ri phung kôranh ma du rbăn nuyh hăn njŭn leo hip nau tâm rnglăp Yêhôva bơh ngih Y-Ôbet-Êđôm ma nau rhơn.$b$,true),
('bunong-vn','1CH',15,26,null,$b$Yor lah Brah Ndu kơl jêh phung Lêvi tung hip nau tâm rnglăp Yêhôva, khân păng ƀư brah pơh mlâm ndrôk nkuăng jêh ri pơh mlâm biăp nkuăng.$b$,false),
('bunong-vn','1CH',15,27,null,$b$Y-Đavit nsoh ao jâr ƀư ma mhay rhên, nâm bu lĕ rngôch phung Lêvi tung hip, jêh ri phung mprơ, jêh ri Y-Kênania kôranh ma phung mprơ, jêh ri Y-Đavit nsoh ao êphôt ƀư ma mhay.$b$,false),
('bunong-vn','1CH',15,28,null,$b$Pô ri lĕ rngôch phung Israel njŭn leo hip nau tâm rnglăp Yêhôva ma nau troh nter, ma bâr nŭng, dang nteh, jêh ri bâr nteh huy ngăn bơh gong rêng jêh ri n'hôm.$b$,false),
('bunong-vn','1CH',15,29,null,$b$Dôl hip nau tâm rnglăp Yêhôva tât ma ƀon Y-Đavit, H'Mikal kon bu ur Y-Sôl uănh n'gơr tă bơh mpông bloh jêh ri saơ Hađăch Đavit talơ̆ jêh ri ƀư nau rhơn; jêh ri Y-Mikal tâm rmot ma Y-Đavit tâm nuih n'hâm.$b$,true),
('bunong-vn','1CH',16,1,null,$b$Khân păng tung nglăp hip Brah Ndu jêh ri dơm păng tâm trôm ngih bok Y-Đavit ndâk jêh ma hip; jêh ri păng gŭch ndơ nhhơr gŭch jêh ri ndơ nhhơr ma nau đăp mpăn ta năp Brah Ndu.$b$,true),
('bunong-vn','1CH',16,2,null,$b$Tơ lah Y-Đavit hŏ nhhơr ndơ gŭch jêh ri ndơ nhhơr ma nau đăp mpăn lĕ lôch jêh păng mât ton ma phung ƀon lan tâm amoh Yêhôva,$b$,false),
('bunong-vn','1CH',16,3,null,$b$jêh ri tâm pă ma lĕ rngôch phung Israel nđâp bu klâu nđâp bu ur ma ăp nơm du glo piăng let, du rlăng puăch, jêh ri du glo ƀănh play kriăk ƀâu kro.$b$,false),
('bunong-vn','1CH',16,4,null,$b$Jêh ri păng dơm kan ƀa ƀă phung Lêvi jêng phung pah kan ta năp hip Yêhôva; ăn khân păng kuăl mbơh sơm, tâm rnê, jêh ri mât ton ma Yêhôva Brah Ndu Israel.$b$,true),
('bunong-vn','1CH',16,5,null,$b$Y-Asap jêng kôranh, Y-Sakari jêng nơm rơh bar, jêh ri geh Y-Jêhiêl, Y-Sêmiramôt, Y-Jêliêl, Y-Matithia, Y-Êliap, Y-Bênaya, Y-Ôbet-Êđôm, jêh ri Y-Jêlêl geh kan kreh gong rêng, jêh ri uh n'hôm; Y-Asap rgu dang nteh,$b$,true),
('bunong-vn','1CH',16,6,null,$b$jêh ri Y-Bênaya jêh ri Y-Jahasiêl phung kôranh ƀư brah uh ƀa ƀơ nŭng ta năp hip nau tâm rnglăp Brah Ndu.$b$,false),
('bunong-vn','1CH',16,7,null,$b$Ta nar nây, Y-Đavit ntĭnh lor lơn ăn Y-Asap jêh ri phung oh nâu păng mprơ tâm rnê ma Yêhôva.$b$,true),
('bunong-vn','1CH',16,8,null,$b$Tâm rnê hom ma Yêhôva, kuăl mbơh sơm ma amoh Păng, ăn phung ƀon lan gĭt kan păng!$b$,true),
('bunong-vn','1CH',16,9,null,$b$Mprơ hom ma păng, mprơ tâm rnê hom ma păng, mbơh hom lĕ rngôch kan khlay Păng.$b$,true),
('bunong-vn','1CH',16,10,null,$b$Tâm rnê hom ma amoh Păng ăn jêng kloh ueh; ăn nuih n'hâm phung joi Yêhôva geh nau hâk maak!$b$,true),
('bunong-vn','1CH',16,11,null,$b$Joi hom Yêhôva jêh ri nau brah Păng, joi hom muh măt Păng ƀa ƀơ!$b$,true),
('bunong-vn','1CH',16,12,null,$b$Hơi phung kon sau Y-Abraham oh mon păng, Hơi phung kon sau Y-Yakôp phung Păng săch jêh!$b$,true),
('bunong-vn','1CH',16,13,null,$b$Kah gĭt hom kan khlay Păng hŏ ƀư, Lĕ nau mbên khlay păng ƀư, jêh ri nau Păng ngơi dôih.$b$,true),
('bunong-vn','1CH',16,14,null,$b$Păng jêng Yêhôva Brah Ndu he; nau Păng phat dôih gŭ jêh lam bri neh ntu.$b$,true),
('bunong-vn','1CH',16,15,null,$b$Păng kah gĭt ƀa ƀơ ma nau Păng tâm rnglăp, ma nau Păng ngơi ntĭnh jêh, tât ma rbăn rô̆ ;$b$,true),
('bunong-vn','1CH',16,16,null,$b$Jêng nau Păng tâm rnglăp hŏ ƀư jêh đah Y-Abraham, jêh ri Păng sơm ton ăn ma Y-Isăk,$b$,false),
('bunong-vn','1CH',16,17,null,$b$nau nây Păng ƀư ăn nâp jêh jêng nau vay ma Y-Yakôp Jêng nau tâm rnglăp n'ho ro ma phung Israel,$b$,false),
('bunong-vn','1CH',16,18,null,$b$lah pô aơ: “Ma khân may gâp mra ăn n'gor Kanaan, jêng du kô̆ drăp ndơm khân may.”$b$,false),
('bunong-vn','1CH',16,19,null,$b$Dôl nôk nây khân may jêng knŏng phung ƀhôi, bu uănh mâu khlay ôh, jêng phung gŭ njơh ƀât lât ta n'gor nây;$b$,false),
('bunong-vn','1CH',16,20,null,$b$hăn rsong blă blơ tă bơh ndŭl mpôl aơ tât ma ndŭl mpôl êng, tă bơh bri dak aơ tât ma bri dak êng.$b$,false),
('bunong-vn','1CH',16,21,null,$b$Păng mâu ăn bu tŭn jot khân păng, Păng nduyh phung hađăch yor khân păng,$b$,false),
('bunong-vn','1CH',16,22,null,$b$lah pô aơ: “Lơi ta pah bi ôh phung gâp lĕ tŏ jêh dak ƀâu kah, lơi ƀư mhĭk ôh ma phung kôranh nơm mbơh lor gâp!”$b$,false),
('bunong-vn','1CH',16,23,null,$b$Hơi lĕ rngôch lam neh ntu, mprơ hom ma Yêhôva! Mbơh hom ăp nar nau Păng tâm rklaih.$b$,false),
('bunong-vn','1CH',16,24,null,$b$Mbơh hom nau chrêk ma lơp Păng ta nklang phung ndŭl mpôl bunuyh, kan hih rhâl Păng ƀư jêh ta nklang lĕ rngôch phung ƀon lan!$b$,false),
('bunong-vn','1CH',16,25,null,$b$Yor lah Yêhôva jêng toyh, khư ngăn ma bu tâm rnê, jêh ri Păng jêng khư ngăn ma bu klach yơk lơn ma lĕ rngôch phung brah.$b$,true),
('bunong-vn','1CH',16,26,null,$b$Yor lah lĕ rngôch brah phung ƀon lan jêng knŏng rup trah, ƀiă lah Yêhôva rhăk njêng jêh lĕ klơ trôk.$b$,true),
('bunong-vn','1CH',16,27,null,$b$Pa năp măt Păng geh nau chrêk lơp, hit rnam; nau brah jêh ri nau hâk răm gŭ ndrel ma Păng.$b$,false),
('bunong-vn','1CH',16,28,null,$b$Hơi phung ndŭl mpôl phung ƀon lan, yơk hom ma Yêhôva nau chrêk ma lơp jêh ri nau brah!$b$,false),
('bunong-vn','1CH',16,29,null,$b$Yơk hom Yêhôva nau chrêk ma lơp di ma amoh Păng; djôt leo hom ndơ nhhơr jêh ri văch pa năp Păng! Mbah yơk ma Yêhôva ma drăp nkrơ̆ kloh ueh.$b$,false),
('bunong-vn','1CH',16,30,null,$b$Hơi lĕ rngôch neh ntu, ăn râm nsâr klach hom ta năp măt Păng. N'hêl nanê̆, lam bri neh ntu gŭ nâp, mâu dơi mpât n'gơ ôh.$b$,true),
('bunong-vn','1CH',16,31,null,$b$Ăn trôk răm rhơn hom, jêh ri neh ntu maak, jêh ri ăn khân păng lah ta nklang phung ndŭl mpôl bunuyh “Yêhôva chiă uănh$b$,false),
('bunong-vn','1CH',16,32,null,$b$Ăn dak mƀŭt jêh ri lĕ rngôch ndơ tâm păng ngrông huy, ăn mir ba, nđâp lĕ rngôch ndơ tâm păng răm maak!$b$,false),
('bunong-vn','1CH',16,33,null,$b$Nôk nây lĕ rngôch tơm si mra mprơ ma nau hâk răm ta năp Yêhôva; yor lah Păng gay phat dôih neh ntu.$b$,false),
('bunong-vn','1CH',16,34,null,$b$Tâm rnê hom ma Yêhôva, yor lah Păng jêng ueh; yor lah nau Păng rŏng hôm e gŭ ƀa ƀơ n'ho ro!$b$,false),
('bunong-vn','1CH',16,35,null,$b$Lah hom: “Hơi Brah Ndu, Nơm tâm rklaih hên tâm rklaih hom hên rgum tay hên jêh ri tâm rklaih hên tă bơh nklang phung ndŭl mpôl bunuyh, gay ma hên dơi tâm rnê ma amoh kloh ueh may, jêh ri geh nau răm maak tâm nau tâm rnê ma may.$b$,true),
('bunong-vn','1CH',16,36,null,$b$Mât ton ma Yêhôva, Brah Ndu Israel, ntơm bơh rnôk n'ho ro tât ma rnôk n'ho ro!” Jêh ri lĕ rngôch phung ƀon lan lah, “Amen” Jêh ri mât ton ma Yêhôva!$b$,true),
('bunong-vn','1CH',16,37,null,$b$Pô ri Y-Đavit dơm Y-Asap jêh ri phung oh nâu păng ta nây, pa năp hip nau tâm rnglăp Yêhôva gay pah kan ƀa ƀơ pa năp hip tĭng nâm nau di ăp nar,$b$,true),
('bunong-vn','1CH',16,38,null,$b$jêh ri tâm ban đŏng Y-Ôbet-Êđôm jêh ri phung prao jât ma pham nuyh oh nâu păng; dôl Y-Ôbet-Êđôm kon bu klâu Y-Yêduthun jêh ri Y-Hôsa prăp ma kan mât njrăng mpông pêr.$b$,false),
('bunong-vn','1CH',16,39,null,$b$Păng dơm đŏng kôranh ƀư brah Y-Sadôk jêh ri phung oh nâu păng phung kôranh ƀư brah pa năp ngih bok Yêhôva tâm ntŭk prêh klơ ta ƀon Gabaôn,$b$,true),
('bunong-vn','1CH',16,40,null,$b$gay nhhơr ndơ nhhơr gŭch ma Yêhôva ta klơ nơng gŭch ndơ nhhơr ƀa ƀơ kêng ôi jêh ri kêng măng, tĭng nâm lĕ nau chih jêh ma phung Israel.$b$,false),
('bunong-vn','1CH',16,41,null,$b$Ndrel ma khân păng geh Y-Hêman jêh ri Y-Yêduthun, jêh nây phung êng bu săch prăp ma kan tâm rnê ma Yêhôva, yor lah nau păng rŏng răp jăp gŭ ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','1CH',16,42,null,$b$Y-Hêman jêh ri Y-Yêduthun geh nŭng jêh ri dang nteh prăp uh rgu jêh ri ndơ êng prăp ma nau mprơ kloh ueh. Bu dơm jêh phung kon bu klâu Y-Yêduthun ma kan mât njrăng mpông pêr.$b$,false),
('bunong-vn','1CH',16,43,null,$b$Jêh ri lĕ rngôch phung ƀon lan hăn sĭt, ăp nơm sĭt ngih păng; bi Y-Đavit sĭt rlet ngih bok gay mât ton phung bunuyh tâm ngih păng.$b$,false),
('bunong-vn','1CH',17,1,null,$b$Tơ lah Y-Đavit gŭ tâm ngih păng nơm, pô ri păng ngơi đah kôranh nơm mbơh lor Y-Nathan, “Aơ, gâp gŭ tâm du rplay ngih ƀư ma tơm si Sêdar, ƀiă lah hip nau tâm rnglăp Yêhôva gŭ tâm dâng ngih bok”$b$,true),
('bunong-vn','1CH',17,2,null,$b$Y-Nathan lah ma Y-Đavit, “Ƀư hom lĕ nau may mĭn tâm nuih n'hâm may, yor lah Brah Ndu gŭ ndrel ma may.”$b$,false),
('bunong-vn','1CH',17,3,null,$b$Ƀiă lah măng nây đŏng Yêhôva ngơi ma Y-Nathan,$b$,true),
('bunong-vn','1CH',17,4,null,$b$“Hăn mbơh hom ma oh mon gâp Y-Đavit. “Pô aơ Yêhôva lah: May mâu mra ndâk ôh du rplay ngih ăn gâp gŭ.$b$,false),
('bunong-vn','1CH',17,5,null,$b$Yor lah gâp mâu mâp gŭ ôh tâm du mlâm ngih ntơm bơh nar gâp njŭn ngluh jêh phung Israel tât ma nar aơ, ƀiă lah gâp nsong jêh tă bơh ngih bok aơ tât ma ngih bok êng, ntơm bơh ntŭk aơ rlet ma ntŭk gŭ ri.$b$,false),
('bunong-vn','1CH',17,6,null,$b$Tâm lĕ rngôch ntŭk gâp nsong jêh ndrel ma lĕ rngôch phung Israel, gâp mâp ngơi lĕ du tong lah đah kôranh phat dôih phung Israel, ma khân păng gâp ntĭnh jêh ăn jêng rmăk biăp ma phung ƀon lan gâp, mâu lah, “Mâm khân may mâu ndâk ôh ma gâp du mlâm ngih ma tơm si Sêdar?”$b$,false),
('bunong-vn','1CH',17,7,null,$b$Yor nây aƀaơ ri, ăn may lah pô aơ ma oh mon (oh mon) gâp Y-Đavit, ‘Pô aơ Yêhôva ma phung ta han lah: Gâp sŏk may tă bơh ndrêch gơ̆ dôl may tĭng groi biăp, gay ma may jêng kôranh chiă uănh phung ƀon lan gâp Israel;$b$,true),
('bunong-vn','1CH',17,8,null,$b$jêh ri gâp gŭ jêng ndrel ma may ta ntŭk may hăn, jêh ri gâp ƀư rai jêh lĕ rngôch phung rlăng may ta năp măt may; jêh ri gâp mra ăn may geh amoh lư n'găr nâm bu amoh phung toyh ta neh ntu.$b$,false),
('bunong-vn','1CH',17,9,null,$b$Jêh ri gâp mra săch du ntŭk ma phung ƀon lan gâp Israel, jêh ri gâp mra tăm khân păng, gay ma khân păng dơi gŭ tâm ntŭk khân păng nơm, jêh ri bu mâu dơi rkhŭk ôh khân păng; jêh ri phung djơh mhĭk mâu hôm ƀư rai đŏng ôh khân păng nâm bu rnôk sa ơm.$b$,false),
('bunong-vn','1CH',17,10,null,$b$Ntơm bơh nôk gâp dơm jêh phung kôranh phat dôih chiă uănh phung ƀon lan gâp Israel; jêh ri gâp mra ăn lĕ rngôch phung rlăng may plơ̆ lăp may. Rmeh ma nau nây gâp mbơh ma may ma Yêhôva mra ndâk ma may du mlâm ngih.$b$,true),
('bunong-vn','1CH',17,11,null,$b$Tơ lah tât jêh nar may mra khĭt hăn gŭ ndrel ma phung chô che may, gâp mra n'hao du huê thoi may, du huê tâm phung kon bu klâu may nơm, jêh ri gâp mra ƀư nâp ƀon bri hađăch păng.$b$,false),
('bunong-vn','1CH',17,12,null,$b$Păng yơh mra ndâk du mlâm ngih ma gâp, jêh ri gâp mra ăn nâp sưng hađăch păng n'ho ro.$b$,false),
('bunong-vn','1CH',17,13,null,$b$Gâp mra jêng mbơ̆ păng, jêh ri păng mra jêng kon bu klâu gâp, gâp mâu mra sŏk sĭt lơi ôh nau gâp rŏng nanê̆ ngăn ma păng nâm bu gâp sŏk sĭt jêh tă bơh nơm lor pa năp may,$b$,false),
('bunong-vn','1CH',17,14,null,$b$ƀiă lah gâp mra ƀư ăn nâp păng tâm ngih gâp jêh ri tâm ƀon bri hađăch gâp n'ho ro, jêh ri sưng hađăch păng mra jêng nâp n'ho ro.”$b$,false),
('bunong-vn','1CH',17,15,null,$b$Tĭng nâm lĕ rngôch nau tâm saơ amoh Y-Nathan ngơi jêh ma Y-Đavit.$b$,true),
('bunong-vn','1CH',17,16,null,$b$Jêh ri Hađăch Đavit lăp jêh ri gŭ ta năp Yêhôva jêh ri lah, “Mbu gâp jêng, Hơi Yêhôva Brah Ndu, jêh ri moh jêng ngih gâp, dĭng may njŭn gâp ta aơ$b$,true),
('bunong-vn','1CH',17,17,null,$b$Nau aơ jêng du ndơ jê̆ ta năp măt may, Hơi Brah Ndu; may ngơi tâm ban đŏng di ma ngih oh mon may ma âk rô̆ mra tât, jêh ri kơp jêh gâp nâm bu bunuyh geh nau yơk lơn$b$,false),
('bunong-vn','1CH',17,18,null,$b$May ƀư ăn oh mon may geh nau yơk jêh pô nây, moh Y-Đavit hôm dơi ngơi đŏng? Yor lah may gĭt năl jêh oh mon may.$b$,false),
('bunong-vn','1CH',17,19,null,$b$Hơi Yêhôva! May hŏ tĭng nâm nuih n'hâm may nơm ŭch jêh lĕ nau toyh aơ, ăn gâp gĭt lĕ rngôch nau toyh aơ.$b$,false),
('bunong-vn','1CH',17,20,null,$b$Hơi Yêhôva! Mâu geh ôh nơm tâm ban ma may, tĭng nâm lĕ nau hên tăng ma tôr hên, rmeh ma may mâu geh ôh nơm jêng Brah Ndu$b$,false),
('bunong-vn','1CH',17,21,null,$b$Mbu ndŭl mpôl êng ta neh ntu jêng bu phung ƀon lan may Israel, phung Brah Ndu Sâm Chuai an jêng phung ƀon lan păng, njêng ma may nơm du amoh toyh jêh ri khư ma bu klach, dôl may mprơh phung ndŭl mpôl êng ta năp phung ƀon lan may, phung may tâm chuai jêh tă bơh n'gor bri Êjipt?$b$,false),
('bunong-vn','1CH',17,22,null,$b$May ăn phung ƀon lan may Israel phung ƀon lan may nơm ƀa ƀơ n'ho ro; jêh ri may, Hơi Yêhôva, jêng jêh Brah Ndu khân păng.$b$,false),
('bunong-vn','1CH',17,23,null,$b$Jêh ri aƀaơ, Hơi Yêhôva, ăn nau may ngơi jêh di ma oh mon may jêh ri ma ngih păng gŭ nâp ƀa ƀơ n'ho ro, jêh ri ƀư hom tĭng nâm nau may ngơi jêh;$b$,true),
('bunong-vn','1CH',17,24,null,$b$jêh ri may mra jêng nâp jêh ri geh nau bu tâm rnê ƀa ƀơ n'ho ro, gay ăn bu lah pô aơ: ‘Yêhôva ma phung ta han, Brah Ndu phung Israel, jêng Brah Ndu phung Israel! Jêh ri ngih oh mon may Y-Đavit mra jêng nâp ta năp may.$b$,false),
('bunong-vn','1CH',17,25,null,$b$Hơi Brah Ndu gâp! May tâm mpơl jêh ma oh mon may nau may mra ndâk du mlâm ngih ma păng; yor nây oh mon may geh nau janh mbơh sơm ta năp may.$b$,false),
('bunong-vn','1CH',17,26,null,$b$Hơi Yêhôva! May jêng Brah Ndu, May ton jêh nau ueh aơ ma oh mon may,$b$,false),
('bunong-vn','1CH',17,27,null,$b$pô ri aƀaơ gâp dăn ma may maak mât ton ma ngih oh mon may; gay ma păng dơi gŭ ƀa ƀơ n'ho ro ta năp may; yor lah, Hơi Yêhôva moh ndơ may mât ton jêh mra geh nau mât ton ƀa ƀơ n'ho ro.”$b$,false),
('bunong-vn','1CH',18,1,null,$b$Jêh nau nây, Y-Đavit dơi đah phung Philistin, jêh nây nglăp khân păng; jêh ri pit sŏk bơh ti khân păng ƀon Gat jêh ri lĕ rngôch ƀon jê̆ jê̆ păng.$b$,true),
('bunong-vn','1CH',18,2,null,$b$Jêh ri păng dơi đah phung Môap, jêh ri phung Môap jêng oh mon ma Y-Đavit jêh ri chê̆ pi ma păng.$b$,false),
('bunong-vn','1CH',18,3,null,$b$Tâm ban đŏng Y-Đavit dơi đah Y-Hadarêser hađăch ƀon Sêba mpeh ma ƀon Hamat, dôl păng hăn ƀư ăn nâp nau păng chiă uănh tât ta dak krong Ơphrat.$b$,true),
('bunong-vn','1CH',18,4,null,$b$Y-Đavit sŏk gro bơh păng du rbăn bôk ndeh seh, pơh rbăn ta han ncho seh, jêh ri bar rmưn ta han hăn jâng; jêh ri Y-Đavit siăt rse suan ndơl jâng lĕ rngôch seh dui ndeh, ƀiă lah om ăp ma du rhiăng bôk ndeh.$b$,true),
('bunong-vn','1CH',18,5,null,$b$Tơ lah phung Siri bơh ƀon Damas văch koh dŏng Y-Hadarêser hađăch ƀon Sôba, Y-Đavit nkhĭt bar rmưn bar rbăn nuyh ta han phung Siri.$b$,true),
('bunong-vn','1CH',18,6,null,$b$Jêh ri Y-Đavit ndâk pôih ta han tâm n'gor bri Siri ndơ ƀon Damas; jêh ri phung Siri jêng oh mon ma Y-Đavit jêh ri chê̆ pi ma păng. Yêhôva ăn Y-Đavit geh nau dơi tâm nau tâm lơh ăp ntŭk păng hăn.$b$,true),
('bunong-vn','1CH',18,7,null,$b$Y-Đavit pit in khêl mah phung oh mon Y-Hadarêser djôt, jêh ri leo ma ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',18,8,null,$b$Ntơm bơh ƀon Tibhat jêh ri Kun, bar ƀon Y-Hadarêser, Y-Đavit pit in âk ngăn kông; ma ndơ nây Y-Salômôn dŏng ƀư drŏng dư̆ ng dak jêh ri meh jêh nây khăl ngan ma kông.$b$,false),
('bunong-vn','1CH',18,9,null,$b$Tơ lah Y-Tôu hađăch ƀon Hamat tăng lư ma Y-Đavit dơi jêh đah lĕ phung ta han Y-Hadarêser hađăch ƀon Sôba,$b$,true),
('bunong-vn','1CH',18,10,null,$b$păng prơh hăn kon bu klâu păng Y-Hadôram rlet ma Hađăch Đavit gay mbah jêh ri mât ton ma ô băl yor lah păng tâm lơh dơi jêh đah Y-Hadarêser; yor lah Y-Hadarêser vay tâm lơh đah Y-Tôu mro mrăng. Păng njuăl ăp ntil ndơ ƀư ma mah, ma prăk, jêh ri ma kông;$b$,false),
('bunong-vn','1CH',18,11,null,$b$ndơ nây tâm ban đŏng Hađăch Đavit nhhơr prăp ma Yêhôva, ndrel ma prăk jêh ri mah păng pit in jêh bơh lĕ rngôch ndŭl mpôl bunuyh êng bơh n'gor Êđôm, n'gor Môap, n'gor Amôn, n'gor Philistin, jêh ri n'gor Amalek.$b$,false),
('bunong-vn','1CH',18,12,null,$b$Y-Abisai kon bu klâu Y-Sêruia nkhĭt du rmưn pham rbăn phung Êđôm tâm Rlŭng-Boh.$b$,true),
('bunong-vn','1CH',18,13,null,$b$Păng ndâk pôih ta han tâm n'gor Êđôm; jêh ri lĕ rngôch phung Êđôm jêng oh mon ma Y-Đavit. Jêh ri Yêhôva ăn Y-Đavit geh nau dơi tâm nau tâm lơh ăp ntŭk păng hăn.$b$,false),
('bunong-vn','1CH',18,14,null,$b$Pô ri Y-Đavit jêng hađăch chiă uănh lĕ rngôch phung Israel; jêh ri păng phat dôih ma nau sŏng jêh ri nau di ma lĕ rngôch phung ƀon lan păng.$b$,true),
('bunong-vn','1CH',18,15,null,$b$Y-Jôap kon bu klâu Y-Sêruia jêng kôranh toyh ma lĕ rngôch phung ta han; jêh ri Y-Jôsaphat kon bu klâu Y-Ahilut jêng nơm kâp chih sămƀŭt prăp nau tât;$b$,false),
('bunong-vn','1CH',18,16,null,$b$Y-Sadôk kon bu klâu Y-Ahitup jêh ri Y-Ahimêlek kon bu klâu Y-Abiathar jêng phung kôranh ƀư brah; Y-Sava jêng kôranh chih sămƀŭt.$b$,false),
('bunong-vn','1CH',18,17,null,$b$Y-Bênaya kon bu klâu Y-Jêhôda jêng kôranh ma phung Kêrêthit jêh ri phung Pêlêthit; jêh ri phung kon bu klâu Y-Đavit jêng phung kôranh toyh tâm kan hađăch.$b$,false),
('bunong-vn','1CH',19,1,null,$b$Jêh nau nây, Y-Nahas hađăch Amôn khĭt, jêh ri kon bu klâu păng jêng hađăch chiă uănh thoi păng.$b$,true),
('bunong-vn','1CH',19,2,null,$b$Y-Đavit lah, “Gâp mra ƀư ma nau răp jăp ma Y-Hanun kon bu klâu Y-Nahas, yor lah mbơ̆ păng ƀư jêh nau răp jăp ma gâp.” Pô ri Y-Đavit prơh hăn phung mbơh gay bonh leng păng yor lah nau tât ma mbơ̆ păng. Jêh ri phung oh mon Y-Đavit hăn tât ma Y-Hanun tâm n'gor Amôn gay bonh leng păng.$b$,false),
('bunong-vn','1CH',19,3,null,$b$Ƀiă lah phung kôranh Amôn lah ma Y-Hanun, “May mĭn lĕ ma Y-Đavit prơh hăn jêh phung bonh leng may, nau nây jêng nau păng yơk ma mbơ̆ may? Mâu hĕ di phung oh mon păng văch jêh ma gay joi sek uănh jêh ri n'glưh n'gor bri aơ?”$b$,false),
('bunong-vn','1CH',19,4,null,$b$Pô ri Y-Hunan nhŭp phung oh mon Y-Đavit, poih lơi têp khân ô băl, jêh ri koh lơi kho ao khân ô băl ta nklang n'gul gang bŭt khân ô băl, jêh ri mprơh khân ô băl sĭt$b$,false),
('bunong-vn','1CH',19,5,null,$b$Tơ lah Y-Đavit tăng lư bu nkoch bri nau tât ma phung nây, păng prơh bunuyh hăn tâm mâp đah khân ô băl, yor lah phung nây bêng ma nau prêng. Jêh ri hađăch lah, “Gŭ hom ta ƀon Yêrikô tât têp khân may jong jêh, jêh ri mơ khân may plơ̆ sĭt.”$b$,false),
('bunong-vn','1CH',19,6,null,$b$Tơ lah phung Amôn gĭt nau khân păng ƀư ma Y-Đavit tâm rmot ma khân păng, Y-Hanun jêh ri phung Amôn djôt leo du rbăn talâng prăk hăn tât n'gor Mêsôpôtami, n'gor Aram-Maka, jêh ri n'gor Sôba gay manh ăn khân păng phung ndeh seh jêh ri ta han ncho seh.$b$,true),
('bunong-vn','1CH',19,7,null,$b$Khân păng nkhôm gay ăn ma khân păng pe rmưn bar rbăn ndeh seh, jêh ri hađăch Maka ndrel ma phung ta han păng; khân păng văch jêh ri njơh rmlak ta pa năp ƀon Mêdêba. Phung Amôn tă bơh ƀon khân păng văch ma nau tâm lơh.$b$,false),
('bunong-vn','1CH',19,8,null,$b$Tơ lah Y-Đavit tăng nau nây, păng prơh hăn Y-Jôap jêh ri lĕ rngôch phung ta han janh ktang păng.$b$,false),
('bunong-vn','1CH',19,9,null,$b$Phung Amôn luh jêh ri dăp ta han bra ta ntŭk lăp ƀon, jêh ri hađăch păng nkhôm jêh ri gŭ tâm bri.$b$,false),
('bunong-vn','1CH',19,10,null,$b$Tơ lah Y-Jôap saơ bu nkra nau tâm lơh đah păng pa năp jêh ri pa kơi, păng săch ƀa ƀă phung ta han ueh lơn tâm phung Israel, jêh ri dăp ăn khân păng bra tâm lơh đah phung Siri.$b$,true),
('bunong-vn','1CH',19,11,null,$b$Phung ta han păng hôm e păng jao ma oh păng Y-Abisai, jêh ri dăp tâm lơh đah phung Amôn.$b$,false),
('bunong-vn','1CH',19,12,null,$b$Păng lah, “Tơ lah phung Siri ktang ir ma gâp, nôk nây ăn may kơl gâp; ƀiă lah tơ lah phung Amôn ktang ir ma may, nôk nây gâp mra kơl may.$b$,false),
('bunong-vn','1CH',19,13,null,$b$Ƀư nănh hom jêh ri ăn he jêng bunuyh ktang yor phung ƀon lan he, jêh ri ăn Yêhôva ƀư tĭng nâm păng mĭn ueh.”$b$,false),
('bunong-vn','1CH',19,14,null,$b$Pô ri Y-Jôap jêh ri phung ƀon lan ndrel ma păng hăn dăch pa năp phung Siri gay tâm lơh; jêh ri phung Siri du ta năp khân păng.$b$,true),
('bunong-vn','1CH',19,15,null,$b$Tơ lah phung Amôn saơ phung Siri du jêh, khân păng tâm ban đŏng du ta năp Y-Abisai oh Y-Jôap, jêh ri lăp tâm ƀon. Y-Jôap plơ̆ sĭt rlet ma ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',19,16,null,$b$Ƀiă lah tơ lah phung Siri saơ ma phung Israel dơi jêh đah khân păng, khân păng prơh bunuyh hăn mbơh jêh ri leo phung Siri văch tă bơh kăl tê̆ dak krong Ơphrat, geh Y-Sôpach kôranh ma phung ta han Y-Hadarêser jêng nơm chiă uănh khân păng.$b$,true),
('bunong-vn','1CH',19,17,null,$b$Y-Đavit gĭt nau nây, păng tâm rƀŭn ndrel lĕ rngôch phung Israel, rgăn kăl tê̆ dak krong Yurdan, hăn tât ma phung Siri jêh ri dăp ta han bra tâm lơh đah khân păng. Pô nây, tơ lah Y-Đavit dăp ta han bra tâm lơh đah phung Siri, khân păng tâm lơh đah păng.$b$,true),
('bunong-vn','1CH',19,18,null,$b$Jêh ri phung Siri du ta năp phung Israel; jêh ri Y-Đavit nkhĭt phung Siri pơh rbăn nuyh ncho ndeh seh, jêh ri puăn rmưn nuyh ta han hăn jâng, jêh ri nkhĭt đŏng Y-Sôpach kôranh ma phung ta han khân păng.$b$,false),
('bunong-vn','1CH',19,19,null,$b$Tơ lah phung oh mon Y-Hadarêser saơ phung Israel dơi jêh đah khân păng; khân păng ƀư nau đăp mpăn đah Y-Đavit, jêh ri lăp păng. Pô ri phung Siri mâu hôm ŭch kơl ôh phung Amôn.$b$,false),
('bunong-vn','1CH',20,1,null,$b$Lăp năm mhe, dôl phung hađăch vay hăn tâm lơh, Y-Jôap leo phung ta han jêh ri ƀư rai lơi lĕ n'gor Amôn, jêh ri văch tât nchueng ƀon Raba. Ƀiă lah Y-Đavit hôm e ta ƀon Yêrusalem. Y-Jôap tâm lơi dơi đah ƀon Raba.$b$,true),
('bunong-vn','1CH',20,2,null,$b$Y-Đavit sŏk lơi đon hađăch khân păng tă bơh bôk păng; păng saơ nau jâk đon hađăch nây du ta lâng mah, jêh ri tâm đon hađăch nây geh du găr lŭ khlay. Bu ndô đon hađăch nây ta bôk Y-Đavit. Păng sŏk djôt ndơ pit bơh ƀon geh âk ngăn.$b$,false),
('bunong-vn','1CH',20,3,null,$b$Păng leo njŭn phung ƀon lan tă bơh ƀon nây jêh ri ăn khân păng pah kan đah ndruih, kau loih, jêh ri sung loih. Tâm ban pô nây Y-Đavit ƀư ma lĕ rngôch ƀon phung Amôn. Pô nây Y-Đavit jêh ri lĕ rngôch phung ƀon lan păng sĭt tay ma ƀon Yêrusalem.$b$,false),
('bunong-vn','1CH',20,4,null,$b$Jêh ta nây, geh nau tâm lơh đah phung Philistin ta ƀon Gêser; nôk nây Y-Sêbêkai du huê Husat nkhĭt Y-Sipai du huê tâm phung kon bu klâu phung bunuyh toyh juat. Jêh ri phung Philistin lăp khân păng.$b$,true),
('bunong-vn','1CH',20,5,null,$b$Jêh ri geh tay đŏng nau tâm lơh đah phung Philistin; jêh ri Y-Êlhanan kon bu klâu Y-Jar nkhĭt Y-Lahmi oh Y-Gôliat bu klâu du huê Gitit, brâm tak păng jêng nâm bu mâng mpeh tanh.$b$,true),
('bunong-vn','1CH',20,6,null,$b$Geh đŏng nau tâm lơh ta ƀon Gat, ta nây geh du huê bu klâu toyh săk jăn geh prao mlâm nglau ti ta ăp mlâm ti jêh ri prao mlâm nglau ta ăp jâng, lĕ rngôch geh bar jât ma puăn nglau; jêh ri păng tâm ban đŏng jêng kon sau phung bunuyh toyh juat.$b$,true),
('bunong-vn','1CH',20,7,null,$b$Tơ lah bu mưch ma phung Israel, Y-Jônathan kon bu klâu Y-Sêmêa, nâu Y-Đavit nkhĭt păng.$b$,false),
('bunong-vn','1CH',20,8,null,$b$Phung nây jêng phung kon sau phung bunuyh toyh juat ta ƀon Gat; jêh ri khân păng nkhĭt ma ti Y-Đavit jêh ri ma ti phung oh mon păng.$b$,false),
('bunong-vn','1CH',21,1,null,$b$Satan dâk ŭch tâm rdâng đah phung Israel, jêh ri gay nsŭk Y-Đavit kơp rnoh phung Israel.$b$,true),
('bunong-vn','1CH',21,2,null,$b$Pô nây Y-Đavit lah ma Y-Jôap jêh ri ma phung kôranh ta han păng, “Hăn kơp hom phung Israel, ntơm bơh Bêrsêba tât ma ƀon Dan, jêh ri sĭt mbơh ma gâp gay ma gâp dơi gĭt ndah âk nuyh khân păng.”$b$,false),
('bunong-vn','1CH',21,3,null,$b$Ƀiă lah Y-Jôap lah, “Dăn ma Yêhôva ntop đŏng ma phung ƀon lan păng du rhiăng tơ̆ âk lơn ma khân păng jêng aƀaơ ri! Hơi hađăch kôranh gâp! Lĕ rngôch khân păng, mâm, mâu hĕ jêng oh mon ma kôranh gâp? Mâm ƀư kôranh gâp ntĭnh ƀư nau nây? Mâm dĭng kôranh gâp nsŭk nau tih ăn phung$b$,false),
('bunong-vn','1CH',21,4,null,$b$Ƀiă lah nau ngơi hađăch dơi lơn đah nau ngơi Y-Jôap. Yor nây, Y-Jôap dâk hăn lam n'gor Israel, jêh ri plơ̆ sĭt ma Yêrusalem.$b$,false),
('bunong-vn','1CH',21,5,null,$b$Y-Jôap ăn rnoh phung ƀon lan păng kơp jêh ma Y-Đavit. Tâm lĕ n'gor Israel geh du rkeh ma du rsen bu klâu dơi djôt đao; jêh ri tâm n'gor Yuđa puăn rsen pơh rmưn dơi djôt đao.$b$,true),
('bunong-vn','1CH',21,6,null,$b$Ƀiă lah păng mâu kơp ôh nđâp phung Lêvi jêh ri phung Benjamin, yor lah Y-Jôap tâm rmot ngăn ma nau hađăch ntĭnh.$b$,false),
('bunong-vn','1CH',21,7,null,$b$Ƀiă lah Brah Ndu mâu maak ôh ma nau nây, jêh ri păng dong phung$b$,true),
('bunong-vn','1CH',21,8,null,$b$Pô nây Y-Đavit lah ma Brah Ndu, “Gâp ƀư nau nây, tih toyh ngăn; ƀiă aƀaơ ri, gâp dăn ma may, lơi klăp ndăng lĕ nau kue bơh oh mon may; yor lah gâp ƀư jêh ma nau rluk ngăn.”$b$,false),
('bunong-vn','1CH',21,9,null,$b$Yêhôva ngơi ma Y-Gat nơm gĭt tâm saơ an ma Y-Đavit, lah,$b$,true),
('bunong-vn','1CH',21,10,null,$b$“Hăn hom lah ma Y-Đavit, ‘Pô aơ Yêhôva lah, Gâp ntŭp pe nau tât ƀư mhĭk ta năp may, săch hom du ntil tâm nau nây, gay ma gâp dơi ƀư nau nây ma may.’ ”$b$,false),
('bunong-vn','1CH',21,11,null,$b$Pô nây Y-Gat hăn ma Y-Đavit jêh ri lah ma păng, “Pô aơ Yêhôva lah, ‘Săch hom moh nau may ŭch:$b$,false),
('bunong-vn','1CH',21,12,null,$b$Gĭt lah pe năm sa sât ji ngot; gĭt lah pe khay nau ƀư rai tă bơh phung rlăng may, jêh ri đao phung rlăng may ban lơh may; mâu lah pe nar ma đao Yêhôva, nâm bu ntĭt nau ji nkhĭt lam neh n'gor, jêh ri tông mpăr Yêhôva ƀư rai lam n'gor bri Israel! Aƀaơ ri săch hom nau gâp mra plơ̆ lah ma Nơm prơh gâp hăn.”$b$,false),
('bunong-vn','1CH',21,13,null,$b$Pô ri Y-Đavit lah ma Y-Gat. “Gâp nđêh nji toyh ngăn; ăn gâp tŭp tâm ti Yêhôva, yor lah nau păng yô̆ toyh ngăn; ƀiă lah lơi ăn ôh gâp tŭp tâm ti bunuyh.”$b$,false),
('bunong-vn','1CH',21,14,null,$b$Pô nây Yêhôva njuăl nau ji nkhĭt tât ma phung Israel; jêh ri geh pơh rmưn bu klâu Israel khĭt.$b$,true),
('bunong-vn','1CH',21,15,null,$b$Jêh ri Brah Ndu prơh hăn tông mpăr ueh ƀư rai ƀon Yêrusalem; ƀiă lah tơ lah păng dăch ntơm ƀư rai ƀon Yêrusalem, Yêhôva saơ jêh ri păng tâm rgâl nau mĭn ƀư nau mhĭk; jêh ri păng lah ma tông mpăr ueh nơm gŭ ƀư rai, “Găp jêh dah nây; nkân lơi ti may.” Tông mpăr ueh Yêhôva dâk dăch ntŭk mprah ba Y-Ôrnan bunuyh Jêbusit.$b$,false),
('bunong-vn','1CH',21,16,null,$b$Y-Đavit n'gơr uănh saơ tông mpăr ueh Yêhôva dâk vah vang neh đah trôk, ti păng djôt đao yơr ta klơ ƀon Yêrusalem. Nôk nây Y-Đavit jêh ri phung bu bŭnh bu ranh nsoh ao dŭr chon mon chŭn muh măt khân păng ta neh.$b$,true),
('bunong-vn','1CH',21,17,null,$b$Jêh ri Y-Đavit lah ma Brah Ndu “Mâu hĕ gâp yơh, nơm ntĭnh jêh ăn kơp phung ƀon lan? Gâp nơm ƀư jêh nau tih jêh ri nau kue ngăn. Ƀiă lah moh phung biăp aơ hŏ mâp ƀư jêh? Hơi Yêhôva Brah Ndu gâp, gâp dăn ma may ăn ti may ƀư ma gâp, jêh ri ma mbơ̆ gâp, ƀiă lah lơi ăn ôh nau ji nkhĭt ƀư ma phung ƀon lan may.”$b$,false),
('bunong-vn','1CH',21,18,null,$b$Nôk nây tông mpăr ueh Yêhôva ntĭnh ma Y-Gat lah an ma Y-Đavit, gay ma Y-Đavit hăn ndâk du mlâm nơng ma Yêhôva ta ntŭk mprah ba Y-Ôrnan bunuyh Jêbusit.$b$,true),
('bunong-vn','1CH',21,19,null,$b$Pô ri Y-Đavit hăn ƀư tĭng nâm nau Y-Gat ngơi, nau păng hŏ ngơi tâm amoh Yêhôva.$b$,true),
('bunong-vn','1CH',21,20,null,$b$Y-Ôrnan gŭ mprah ba; păng n'gĭl saơ tông mpăr ueh; bi puăn nuyh kon bu klâu păng dôl gŭ ta nây du krap.$b$,true),
('bunong-vn','1CH',21,21,null,$b$Hađăch Đavit văch ma Y-Ôrnan, tơ lah saơ Y-Đavit, Y-Ôrnan luh tă bơh ntŭk mprah ba jêh ri mbah ma Y-Đavit chŭn muh măt ta neh.$b$,true),
('bunong-vn','1CH',21,22,null,$b$Y-Đavit lah ma Y-Ôrnan, “Ăn ma gâp ntŭk mprah ba aơ gay ma gâp dơi ndâk du mlâm nơng ma Yêhôva ta aơ- tăch hom ma gâp di moh păng-gay ma nau ji nkhĭt der du bơh phung ƀon lan.”$b$,false),
('bunong-vn','1CH',21,23,null,$b$Pô ri Y-Ôrnan lah ma Y-Đavit, “Sŏk hom, ăn hađăch kôranh gâp, ƀư hom moh nau may mĭn ueh. Aơ, gâp ăn ndrôk prăp ma ndơ nhhơr gŭch, jêh ri ndơ mprah ba ƀư long, ba prăp ndơ nhhơr rnih muy. Gâp ăn lĕ ndơ nây.”$b$,false),
('bunong-vn','1CH',21,24,null,$b$Ƀiă lah hađăch Đavit lah ma Y-Ôrnan, “Mâu ôh, gâp ŭch rvăt păng di rnoh; gâp mâu mra sŏk ôh ndơ may ŭch nhhơr ma Yêhôva, gâp mâu nhhơr ôh du ndơ nhhơr gŭch ƀiă lah mâu huach ôh ndơ rvăt.”$b$,false),
('bunong-vn','1CH',21,25,null,$b$Pô ri Y-Đavit njing ăn ma Y-Ôrnan prăm rhiăng Sêkel mah gay rvăt ntŭk nây.$b$,false),
('bunong-vn','1CH',21,26,null,$b$Y-Đavit ndâk ta nây du mlâm nơng ma Yêhôva jêh ri nhhơr ndơ nhhơr gŭch jêh ri ndơ nhhơr ma nau đăp mpăn, jêh nây kuăl mbơh sơm ma amoh Yêhôva; Păng plơ̆ lah ma ŭnh bơh klơ trôk trŭnh ta klơ nơng ndơ nhhơr gŭch.$b$,true),
('bunong-vn','1CH',21,27,null,$b$Jêh ri Yêhôva ntĭnh ma tông mpăr ueh, jêh ri tông mpăr ueh ntrŭp đao tâm ndrop.$b$,false),
('bunong-vn','1CH',21,28,null,$b$Tơ lah Y-Đavit saơ Yêhôva plơ̆ lah nau mbơh sơm păng ta ntŭk mprah ba Y-Ôrnan bunuyh Jêbusit, hađăch nhhơr ndơ nhhơr ƀư brah ta nây.$b$,true),
('bunong-vn','1CH',21,29,null,$b$Yor lah nôk nây ngih bok Yêhôva Y-Môis hŏ ƀư jêh tâm bri rdah jêh ri nơng prăp ma ndơ nhhơr gŭch gŭ ta ntŭk prêh ta ƀon Gabaôn;$b$,false),
('bunong-vn','1CH',21,30,null,$b$ƀiă lah Y-Đavit mâu dơi hăn ôh pa năp nơng gay ôp ma Brah Ndu, yor lah păng klach ma đao tông mpăr ueh Yêhôva.$b$,false),
('bunong-vn','1CH',22,1,null,$b$Nôk nây Hađăch Đavit lah, “Ntŭk aơ mra jêng ntŭk ma ngih Yêhôva Brah Ndu; jêh ri nơng prăp ăn ma phung Israel nhhơr ndơ nhhơr gŭch ăt ta aơ đŏng.”$b$,true),
('bunong-vn','1CH',22,2,null,$b$Y-Đavit ntĭnh ăn rgum phung bu năch gŭ tâm n'gor Israel, jêh ri păng ntĭnh ma phung trah lŭ nkra lŭ gay ma kan ndâk ngih Brah Ndu.$b$,true),
('bunong-vn','1CH',22,3,null,$b$Tâm ban đŏng Y-Đavit lĕ ndrăp âk ngăn loih prăp ƀư loih kđĭn ma mpông tâm mpông pêr jêh ri prăp ƀư loih tâm nkrêp mpông, nđâp kông âk ngăn ngên kŏ tât mâu dơi njing lĕ,$b$,false),
('bunong-vn','1CH',22,4,null,$b$jêh ri tơm si sêdar mâu dơi kơp ôh; yor lah phung Sidôn jêh ri phung Tir njŭn âk ngăn tơm si Sêdar ma Y-Đavit.$b$,false),
('bunong-vn','1CH',22,5,null,$b$Hađăch Đavit lah: “Y-Salômôn, kon bu klâu gâp hôm e kon se ê hŏ blau kan ôh, jêh ri ngih ŭch ndâk ma Yêhôva mra jêng ueh nchrat nchrang ngăn ngên geh nau lơp rmah jêh ri lư n'găr lam bri dak; pô nây gâp mra nkra ma kan nây.” Yor nây Y-Đavit joi ăn geh âk ndơ ê lor păng khĭt.$b$,false),
('bunong-vn','1CH',22,6,null,$b$Jêh nây păng kuăl Y-Salômôn kon bu klâu păng, jêh ri ntĭnh ma păng gay ăn păng ndâk du mlâm ngih ma Yêhôva Israel.$b$,true),
('bunong-vn','1CH',22,7,null,$b$Hađăch Đavit lah ma Y-Salômôn, “Hơi kon, nuih n'hâm gâp geh nau ŭch ndâk du mlâm ngih ma Amoh Yêhôva Brah Ndu gâp.$b$,true),
('bunong-vn','1CH',22,8,null,$b$Ƀiă lah Yêhôva ngơi ma gâp, lah, ‘May hŏ ƀư pling mham bu âk jêh, hŏ ƀư jêh âk nau tâm lơh toyh; may mâu mra ndâk du mlâm ngih ma Amoh gâp ôh, yor lah may ƀư pling jêh âk ir mham ta năp gâp ta klơ neh ntu.$b$,true),
('bunong-vn','1CH',22,9,null,$b$Aơ, bu mra deh ma may du huê kon bu klâu; păng mra jêng du huê đăp mpăn. Gâp mra ăn ma păng nau đăp mpăn, mâu geh phung rlăng gŭ jŭm păng văch lơh ôh; yor lah amoh păng jêng Y-Salômôn; tâm rô̆ păng gâp mra ăn phung Israel đăp mpăn, gŭ păn thơ.$b$,false),
('bunong-vn','1CH',22,10,null,$b$Păng mra ndâk du mlâm ngih ma Amoh gâp. Păng mra jêng kon bu klâu gâp, jêh ri gâp mra ăn nâp sưng hađăch păng tâm n'gor Israel ƀa ƀơ n'ho ro$b$,false),
('bunong-vn','1CH',22,11,null,$b$Aƀaơ ri, Hơi kon, ăn Yêhôva gŭ n'hanh may, pô ri mơ may dơi ndâk ngih ma Yêhôva Brah Ndu may, tĭng nâm păng ngơi jêh nau di ma may.$b$,false),
('bunong-vn','1CH',22,12,null,$b$Knŏng dăn ma Yêhôva ăn ma may nau gĭt mĭn jêh ri nau gĭt rbăng, tơ lah păng ăn kan ma may chiă uănh phung Israel may dơi djôt prăp nau vay Yêhôva Brah Ndu$b$,false),
('bunong-vn','1CH',22,13,null,$b$Pô ri may mra geh nau chăt jêng tơ lah may njrăng gay ƀư tĭng nau vay jêh ri nau ntĭnh Yêhôva hŏ ăn jêh ma Y-Môis di ma phung Israel. Jêng ktang hom, jêh ri jêng janh hom. Lơi klach ôh, lơi rdja nuih ôh.$b$,false),
('bunong-vn','1CH',22,14,null,$b$Ma nau hŏt ra ah ngăn gâp joi jêh gay dơi geh ndơ nkra ngih Yêhôva, du rsen talâng mah, du rkeh talâng prăk, jêh ri kông nđâp loih mâu dơi njing ôh, yor lah geh âk ir. Gâp joi lĕ jêh tơm si jêh ri lŭ tâm ban đŏng. Ăn may ntop đŏng ma ndơ aơ.$b$,false),
('bunong-vn','1CH',22,15,null,$b$May geh đŏng âk ngăn bunuyh pah kan: Phung trah lŭ, phung ndâk lŭ, phung trah meh, jêh ri ăp ntil phung blau pah mâu dơi kơp ôh, phung n'hăk ƀư kan,$b$,true),
('bunong-vn','1CH',22,16,null,$b$ma mah, prăk, kông jêh ri loih. Dâk ƀư hom! Dăn ma Yêhôva gŭ n'hanh may!”$b$,false),
('bunong-vn','1CH',22,17,null,$b$Tâm ban đŏng Y-Đavit ntĭnh jêh ma lĕ rngôch phung kôranh Israel ăn kơl Y-Salômôn kon bu klâu păng, lah,$b$,true),
('bunong-vn','1CH',22,18,null,$b$“Mâu hĕ di Yêhôva Brah Ndu khân may gŭ ndrel ma khân may? Jêh ri mâu hĕ di păng ăn jêh nau đăp mpăn ma khân may gŭ văr jŭm pŭng? Yor lah păng jao jêh phung gŭ ta n'gor tâm ti may; jêh ri nklang n'gor aơ hŏ lăp jêh khân may ta năp Yêhôva jêh ri phung ƀon lan păng.$b$,false),
('bunong-vn','1CH',22,19,null,$b$Aƀaơ ri sơm ton hom tâm nau mĭn jêh ri nuih n'hâm khân may gay joi Yêhôva Brah Ndu khân may. Dâk hom jêh ri ndâk ntŭk kloh ueh ma Yêhôva Brah Ndu, gay ma hip nau tâm rnglăp Yêhôva jêh ri khăl ngan kloh ueh Brah Ndu mra dơi leo nglăp dơm tâm du mlâm ngih ndâk jêh ma Yêhôva.”$b$,false),
('bunong-vn','1CH',23,1,null,$b$Tơ lah Y-Đavit hŏ ranh, jŏk rêh jêh, păng njêng Y-Salômôn kon bu klâu păng hađăch chiă uănh phung Israel.$b$,true),
('bunong-vn','1CH',23,2,null,$b$Y-Đavit rgum lĕ rngôch phung kôranh mât uănh Israel, phung kôranh ƀư brah, jêh ri phung Lêvi.$b$,true),
('bunong-vn','1CH',23,3,null,$b$Bu kơp phung Lêvi ntơm pe jât năm leo klơ, lĕ rngôch geh pe jât ma pham nuyh bu klâu.$b$,false),
('bunong-vn','1CH',23,4,null,$b$Y-Đavit lah,” Bar rmưn puăn rbăn phung aơ mra chiă uănh kan tâm ngih Yêhôva, prao rbăn nuyh mra jêng phung kôranh toyh jêh ri phung kôranh phat dôih,$b$,false),
('bunong-vn','1CH',23,5,null,$b$puăn rbăn nuyh mât njrăng mpông pêr, jêh ri puăn rbăn nuyh mra nhhơr nau tâm rnê ma Yêhôva ma dĭng mpât mprơ, ndơ nây hŏ ƀư jêh prăp ma kan tâm rnê.”$b$,false),
('bunong-vn','1CH',23,6,null,$b$Y-Đavit tâm pă khân păng tĭng mbŭch êng êng ăn di ma phung kon bu klâu Y-Lêvi: Jêng Y-Gersôm, Y-Kôhat jêh ri Y-Mêrari.$b$,true),
('bunong-vn','1CH',23,7,null,$b$Phung kon bu klâu Y-Gersôm geh: Y-Ladan jêh ri Y-Simei.$b$,true),
('bunong-vn','1CH',23,8,null,$b$Phung kon bu klâu Y-Ladan: Y-Jêhiêl jêng kôranh, jêh nây tât Y-Sêthan jêh ri Y-Yôel, geh pe nuyh.$b$,false),
('bunong-vn','1CH',23,9,null,$b$Phung kon bu klâu Y-Simei: Y-Sêlêmôt, Y-Hasiêl, jêh ri Y-Haran jêng pe nuyh.$b$,false),
('bunong-vn','1CH',23,10,null,$b$Jêh ri phung kon bu klâu Y-Simei jêng: Y-Jahat, Y-Sina, Y-Jêus, jêh ri Y-Bêria. Aơ jêng puăn nuyh kon bu klâu Y-Simei.$b$,false),
('bunong-vn','1CH',23,11,null,$b$Y-Jahat jêng kôranh, Y-Sisa jêng nơm rơh bar; ƀiă lah Y-Jêus jêh ri Y-Bêria mâu geh ôh âk kon bu klâu, yor nây bu kơp khân păng jêng phung du ndŭl deh.$b$,false),
('bunong-vn','1CH',23,12,null,$b$Phung kon bu klâu Y-Kôhat jêng: Y-Am ram, Y-Ishar, Y-Hêbron, jêh ri Y-Usiêl, puăn nuyh.$b$,true),
('bunong-vn','1CH',23,13,null,$b$Phung kon bu klâu Y-Amram jêng: Y-Arôn, jêh ri Y-Môis; Y-Arôn bu rnglah êng, păng jêh ri noi deh păng gay prăp ma kan nhhơr lĕ ndơ kloh ueh ngăn, jêh ri n'ho ro nhhơr su ndơ ƀâu kah pa năp Yêhôva, jêh ri pah kan ma Păng, jêh nây ntĭnh nau mât ton tâm amoh Păng mro mrăng.$b$,false),
('bunong-vn','1CH',23,14,null,$b$Y-Môis jêng bunuyh Brah Ndu; phung kon bu klâu păng mra kơp ndrel ma mpôl Lêvi.$b$,true),
('bunong-vn','1CH',23,15,null,$b$Phung kon bu klâu Y-Môis jêng: Y-Gersôm jêh ri Y-Êliêser.$b$,false),
('bunong-vn','1CH',23,16,null,$b$Tâm phung kon bu klâu Y-Gersôm: Y-Sêbuel jêng kôranh.$b$,false),
('bunong-vn','1CH',23,17,null,$b$Kon bu klâu Y-Êliêse jêng Y-Rêhabia jêng kôranh; Y-Êliêser mâu geh ôh phung kon bu klâu, ƀiă lah Y-Rêhabia geh âk ngăn kon bu klâu.$b$,true),
('bunong-vn','1CH',23,18,null,$b$Tâm phung kon bu klâu Y-Y- Ishar: Y-Sêlônit jêng kôranh.$b$,false),
('bunong-vn','1CH',23,19,null,$b$Tâm phung kon bu klâu Y-Hêbron: Y-Jêria jêng kôranh, Y-Amaria jêng nơm rơh bar, Y-Jahasiêl jêng nơm rơh pe, jêh ri Y-Jêkamêan jêng nơm rơh puăn$b$,false),
('bunong-vn','1CH',23,20,null,$b$Phung kon bu klâu Y-Usiel: Y-Mika jêng kôranh jêh ri Y-Isiya jêng nơm rơh bar.$b$,false),
('bunong-vn','1CH',23,21,null,$b$Phung kon bu klâu Y-Mêrari: Y-Mahli jêh ri Y-Musi Phung kon bu klâu Y-Mahli: Y-Êleasar jêh ri Y-Kis.$b$,true),
('bunong-vn','1CH',23,22,null,$b$Y-Êlêasar khĭt mâu geh ôh kon bu klâu, geh dơm knŏng kon bu ur; jêh ri phung kon bu klâu Y-Kis, jêng mpôl, khân păng tâm gŭ ƀư ur.$b$,false),
('bunong-vn','1CH',23,23,null,$b$Phung kon bu klâu Y-Musi: Y-Mahli, Y-Êder jêh ri Y-Jêrêmôt pe nuyh.$b$,false),
('bunong-vn','1CH',23,24,null,$b$Aơ jêng phung kon sau Y-Lêvi tĭng nâm ndŭl deh khân păng; jêng kôranh ma ndŭl deh bu chih amoh khân păng tĭng nâm ndah âk amoh săk ăp nơm ntơm bơh bar jât năm leo Klơ, phung prăp ma kan tâm ngih Yêhôva.$b$,true),
('bunong-vn','1CH',23,25,null,$b$Yor lah Hađăch Đavit lah: “Yêhôva Brah Ndu phung Israel ăn jêh nau đăp mpăn ma phung ƀon lan păng; jêh ri păng gŭ tâm ƀon Yêrusalem n'ho ro.$b$,false),
('bunong-vn','1CH',23,26,null,$b$Pô ri phung Lêvi mâu hôm ôh tung ngih bok mâu lah ndơ prăp ma kan tâm ngih bok.”$b$,false),
('bunong-vn','1CH',23,27,null,$b$Yor lah tĭng nâm nau Hađăch Đavit ngơi dăch dŭt jêng rnoh kơp phung Lêvi ntơm bơh bar jât năm leo klơ$b$,true),
('bunong-vn','1CH',23,28,null,$b$“ƀiă lah kan jao jêh ma khân păng mra kơl phung kon bu klâu Y-Arôn tâm kan ma ngih Yêhôva, geh kan mât mray nhuang jêh ri jrô, kan ăn kloh lĕ rngôch ndơ kloh ueh, jêh ri moh kan di ma ngih Yêhôva;$b$,false),
('bunong-vn','1CH',23,29,null,$b$gay kơl ma kan ƀư rnih nhhơr ma Brah Ndu, rnih muy prăp ma ndơ nhhơr rnih muy; ƀănh mâu geh ndrui, ndơ nhhơr rnih muy gŭch (piăng pưng), ndơ nhhơr tâm pot dak play ôlivơ, lĕ rngôch ndơ njing âk mâu lah toyh.$b$,false),
('bunong-vn','1CH',23,30,null,$b$Jêh ri khân păng mra dâk ăp ôi tâm rnê mât ton ma Yêhôva, jêh ri ƀư tâm ban đŏng ăp tơ̆ kêng măng,$b$,true),
('bunong-vn','1CH',23,31,null,$b$jêh ri tơ lah bu nhhơr ndơ nhhơr gŭch ma Yêhôva ta nar Saƀat, ta nar mhe luh, ta nar năng ƀun toyh, tĭng nâm rnoh bu ntĭnh ma khân păng ƀa ƀơ mro mrăng pa năp Yêhôva.$b$,false),
('bunong-vn','1CH',23,32,null,$b$Pô nây mơ khân păng mra djôt kan ngih bok tâm rƀŭn jêh ri jrô kloh ueh, jêh nây mra kơl phung kon bu klâu Y-Arôn, phung oh nâu khân păng tâm kan ngih Yêhôva.”$b$,false),
('bunong-vn','1CH',24,1,null,$b$Tâm pă mbŭch tâm phung kon bu klâu Y-Arôn pô aơ. Phung kon bu klâu Y-Arôn: Y-Nadap, Y-Abihu, Y-Êlêasar, jêh ri Y-Athamar.$b$,true),
('bunong-vn','1CH',24,2,null,$b$Ƀiă lah Y-Nadap jêh ri Y-Abihu khĭt lor ma mbơ̆ khân păng, jêh ri khân păng mâu geh ôh kon, pô ri Y-Êlêasar jêh ri Y-Ithamar jêng phung kôranh ngih brah.$b$,false),
('bunong-vn','1CH',24,3,null,$b$Hađăch Đavit ndrel ma Y-Sadôk, jêng noi deh Y-Êlêaser, jêh ri Y-Abimêlek noi deh Y-Ithamar, tâm pă mbŭch khân păng tĭng nâm kan khân păng pah.$b$,false),
('bunong-vn','1CH',24,4,null,$b$Tâm nklang phung kon bu klâu Y-Êlêasar geh âk lơn phung kôranh ma noi deh ma đah phung kon bu klâu Y-Ithamar, yor ri bu tâm pă nâm bu pô aơ: Jât ma prao nuyh phung kôranh ma noi deh phung kon bu klâu Y-Êlêasar, jêh ri pham nuyh kôranh phung kon bu klâu Y-Ithamar.$b$,false),
('bunong-vn','1CH',24,5,null,$b$Phung aơ dơi tâm pă tĭng mbŭch ma nau nchroh tâm lĕ rngôch tâm ban, yor lah geh phung jêng kôranh ma jrô kloh ueh jêh ri kôranh ma kan Brah Ndu tâm lĕ bar phung kon bu klâu Y-Êlêasar jêh ri phung kon bu klâu Y-Ithamar.$b$,false),
('bunong-vn','1CH',24,6,null,$b$Kôranh chih săm ƀŭt Y-Sêmaya kon bu klâu Y-Nêthanel du huê ndŭl mpôl Lêvi, chih prăp amoh khân păng ta năp hađăch, jêh ri ta năp phung kôranh ƀư brah Y-Sadôk, Y-Ahimalek, kon bu klâu Y-Abiathar, jêh ri phung kôranh noi deh ma phung kôranh ƀư brah jêh ri phung Lêvi: Bu săch du phung noi deh ma Y-Êlêasar jêh ri du phung êng ma Y-Ithamar.$b$,false),
('bunong-vn','1CH',24,7,null,$b$Nau tâm nchroh ntơm sa ơm di ma Y-Jêhôyarip, tơ̆ bar di ma Y-Jêdaya,$b$,true),
('bunong-vn','1CH',24,8,null,$b$tơ̆ pe di ma Y-Harim, tơ̆ puăn di ma Y-Sêôrim,$b$,false),
('bunong-vn','1CH',24,9,null,$b$tơ̆ prăm di ma Y-Malkija, tơ̆ prao di ma Y-Mijamin,$b$,false),
('bunong-vn','1CH',24,10,null,$b$tơ̆ pơh di ma Y-Hakôs, tơ̆ pham di ma Y-Abija,$b$,false),
('bunong-vn','1CH',24,11,null,$b$tơ̆ sĭn di ma Y-Jêsua, tơ̆ jât di ma Y-Sêkania,$b$,false),
('bunong-vn','1CH',24,12,null,$b$tơ̆ jât ma nguay di ma Y-Êliasip, tơ̆ jât ma bar di ma Y-Jakim,$b$,false),
('bunong-vn','1CH',24,13,null,$b$tơ̆ jât ma pe di ma Y-Hupa, tơ̆ jât ma puăn di ma Y-Jêsêbêap,$b$,false),
('bunong-vn','1CH',24,14,null,$b$tơ̆ jât ma prăm di ma Y-Bilga, tơ̆ jât ma prao di ma Y-Imer,$b$,false),
('bunong-vn','1CH',24,15,null,$b$tơ̆ jât ma pơh di ma Y-Hêsir, tơ̆ jât ma pham di ma Y-Hapisês$b$,false),
('bunong-vn','1CH',24,16,null,$b$tơ̆ jât ma sĭn di ma Y-Pêrahia, tơ̆ bar jât di ma Y-Jêhêkel,$b$,false),
('bunong-vn','1CH',24,17,null,$b$tơ̆ bar jât ma nguay di ma Y-Jakin, tơ̆ bar jât ma bar di ma Y-Gamul,$b$,false),
('bunong-vn','1CH',24,18,null,$b$tơ̆ bar jât ma pe di ma Y-Dêlaya, tơ̆ bar jât ma puăn di ma Y-Masia.$b$,false),
('bunong-vn','1CH',24,19,null,$b$Phung nây geh kan bu dơm jêh ăn khân păng lăp tâm ngih Yêhôva tĭng nâm nau Y-Arôn che khân păng ntĭnh jêh ma khân păng, tĭng nâm Yêhôva Brah Ndu Israel ntĭnh jêh ma păng.$b$,false),
('bunong-vn','1CH',24,20,null,$b$Phung kon sau hôm e bơh Y-Lêvi: Tâm phung kon bu klâu bơh Y-Amram, Y-Subaêl; tâm phung kon bu klâu Y-Sabaêl geh Y-Jêhdêa.$b$,true),
('bunong-vn','1CH',24,21,null,$b$Bi ma phung kon bu klâu Y-Rêhabia; Y-Tsiya jêng kôranh.$b$,false),
('bunong-vn','1CH',24,22,null,$b$Tâm phung Isharit geh Y-Sêlômôt; bơh phung kon bu klâu Y-Sêlômôt geh Y-Jahat.$b$,false),
('bunong-vn','1CH',24,23,null,$b$Phung kon bu klâu Hêbron: Geh Y-Jêria jêng kôranh, Y-Amaria nơm rơh bar, Y-Jahasiêl nơm rơh pe, Y-Jêkamêam nơm rơh puăn.$b$,true),
('bunong-vn','1CH',24,24,null,$b$Tâm phung kon bu klâu Y-Usiêl geh Y-Maka; tâm phung kon bu klâu Y-Mika geh Y-Samir.$b$,false),
('bunong-vn','1CH',24,25,null,$b$Oh Y-Mika jêng Y-Isiya; tâm phung kon bu klâu Y-Isiya geh Y-Sakari.$b$,false),
('bunong-vn','1CH',24,26,null,$b$Tâm phung kon bu klâu Y-Mêrari geh Y-Mahli jêh ri Y-Musi; tâm phung kon bu klâu Y-Jasia geh Y-Bênô.$b$,true),
('bunong-vn','1CH',24,27,null,$b$Phung kon bu klâu Y-Mêrari: Bơh Y-Jasia, Y-Bênô, Y-Sôham, Y-Sakur jêh ri Y-Ibri.$b$,false),
('bunong-vn','1CH',24,28,null,$b$Tă bơh Y-Mahli geh Y-Êlêasar, jêng nơm mâu geh kon ôh.$b$,false),
('bunong-vn','1CH',24,29,null,$b$Tâm phung kon bu klâu Y-Kis geh Y-Jêrahmêel.$b$,false),
('bunong-vn','1CH',24,30,null,$b$Phung kon bu klâu Y-Musi jêng Y-Mahli, Y-Êder, jêh ri Y-Jêrimôt. Nây jêng phung kon bu klâu Y-Lêvi tĭng nâm noi deh khân păng.$b$,false),
('bunong-vn','1CH',24,31,null,$b$Phung nây tâm ban đŏng jêng phung kôranh ma ăp noi deh khân păng jêh ri phung oh khân păng tâm ban lĕ ƀư nau tâm nchroh, nâm bu phung oh nâu kon bu klâu Y-Arôn, ta năp Hađăch Đavit, Y-Sadôk, Y-Ahimalek, jêh ri phung kôranh ma noi deh phung kôranh ƀư brah jêh ri phung Lêvi.$b$,false),
('bunong-vn','1CH',25,1,null,$b$Hađăch Đavit jêh ri phung kôranh toyh ma phung ta han gay ŭch rnglah êng đŏng ƀa ƀă phung kon bu klâu Y-Asap, ƀa ƀă phung kon bu klâu Y-Hêman, jêh ri ƀa ƀă phung kon bu klâu Y-Yêduthun ma kan mra mbơh lor ndrel ma nau uh n'hôm kreh gong rêng, jêh ri rgu dang nteh. Amoh phung pah kan nây jêh ri kan khân păng pô aơ:$b$,true),
('bunong-vn','1CH',25,2,null,$b$Phung kon bu klâu Y-Asap geh: Y-Sakur, Y-Yôsep, Y-Nêthania, jêh ri Y-Asarêla. Phung kon bu klâu Y-Asap pah kan tâm dâng nau dơi păng leo, bi ma Y-Asap nơm nau mbơh lor tâm dâng nau dơi hađăch gai.$b$,false),
('bunong-vn','1CH',25,3,null,$b$Tâm phung kon bu klâu Y-Yêduthun geh: Y-Gêdalia, Y-Sêri, Y-Jêsaya, Y-Simei, Y-Hasabia, jêh ri Y-Matithia, prao nuyh lĕ rngôch pah kan tâm dâng nau dơi mbơ̆ khân păng nơm, Y-Yêduthun leo; Y-Yêduthun nơm mbơh lor ndrel ma nau uh n'hôm ma nau tâm rnê jêh ri mât ton ma Yêhôva.$b$,false),
('bunong-vn','1CH',25,4,null,$b$Bơh phung kon bu klâu Y-Hêman geh: Y-Bukia, Y-Matania, Y-Usiêl, Y-Sêbuel, jêh ri Y-Jêrêmôt, Y-Hanania, Y-Êliathan, Y-Gidalti, jêh ri Y-Rômamti-Êser, Y-Jôsbêkasa, Y-Môlôthi, Y-Hôthir Y-Mahasiôt.$b$,true),
('bunong-vn','1CH',25,5,null,$b$Lĕ rngôch phung aơ jêng phung kon bu klâu Y-Hêman nơm gĭt tâm saơ an ma hađăch, tĭng nâm nau Brah Ndu ton gay yơk n'hao păng; Brah Ndu ăn jêh ma Y-Hêman jât ma puăn nuyh kon bu klâu jêh ri pe nuyh kon bu ur.$b$,false),
('bunong-vn','1CH',25,6,null,$b$Lĕ rngôch khân păng gŭ tâm dâng nau dơi mbơ̆ khân păng leo tâm nau kâp mprơ tâm ngih Yêhôva ma dang nteh, gong rêng, n'hôm tâm dâng nau dơi Y-Asap, Y-Jêduthun, jêh ri Y-Hêman tĭng nau ntrŭnh bơh hađăch gay pah kan ngih Brah Ndu.$b$,true),
('bunong-vn','1CH',25,7,null,$b$Rnoh kơp khân păng ndrel ma phung ôh nâu khân păng bu hŏ sâm nti jêh tâm nau mprơ ma Yêhôva, lĕ rngôch phung n'hăk, geh bar rhiăng pham jât ma pham nuyh.$b$,true),
('bunong-vn','1CH',25,8,null,$b$Khân păng ƀư nau tâm nchroh yor kan khân păng, nơm jê̆ tâm ban ma nơm toyh, nai nti tâm ban ma nơm kâp nti.$b$,true),
('bunong-vn','1CH',25,9,null,$b$Nau tâm nchroh ntơm sa ơm ma kan Y-Asap di ma Y-Yôsep; tơ̆ bar di ma Y-Gêdalia, ma păng, ma phung oh nâu păng jêh ri phung kon bu klâu păng, jât ma bar nuyh;$b$,true),
('bunong-vn','1CH',25,10,null,$b$tơ̆ pe di ma Y-Sakur phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,11,null,$b$tơ̆ puăn di ma Y-Iri, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh.$b$,false),
('bunong-vn','1CH',25,12,null,$b$Tơ̆ prăm di ma Y-Nêthania, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,13,null,$b$tơ̆ prao di ma Y-Bukia, phung kon bu klâu păng jêh ri phung oh nâu păng; geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,14,null,$b$tơ̆ pơh di ma Y-Jêsarêla, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,15,null,$b$tơ̆ pham di ma Y-Jêsaya, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,16,null,$b$tơ̆ sĭn di ma Y-Matania, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,17,null,$b$tơ̆ jât di ma Y-Simei, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,18,null,$b$tơ̆ jât ma nguay di ma Y-Asarel, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,19,null,$b$tơ̆ jât ma bar di ma Y-Hasabia, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,20,null,$b$tơ̆ jât ma pe di ma Y-Subaêl, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,21,null,$b$tơ̆ jât ma puăn di ma Y-Matithia, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,22,null,$b$tơ̆ jât ma prăm di ma Y-Jêrêmôt, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,23,null,$b$tơ̆ jât ma prao di ma Y-Hanania, phung kon bu klâu păng jêh ri phung oh nâu păng geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,24,null,$b$tơ̆ jât ma pơh di ma Y-Jôsbêkasa, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,25,null,$b$tơ̆ jât ma pham di ma Y-Hanani di ma, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,26,null,$b$tơ̆ jât ma sĭn di ma Y-Malôthi, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,27,null,$b$tơ̆ bar jât di ma Y-Êliatha, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,28,null,$b$tơ̆ bar jât ma nguay di ma Y-Hôthir, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,29,null,$b$tơ̆ bar jât ma bar di ma Y-Gidalti, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,30,null,$b$tơ̆ bar jât ma pe di ma Y-Mahasiôt, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh;$b$,false),
('bunong-vn','1CH',25,31,null,$b$tơ̆ bar jât ma puăn di ma Y-Rômamtiêser, phung kon bu klâu păng jêh ri phung oh nâu păng, geh jât ma bar nuyh.$b$,false),
('bunong-vn','1CH',26,1,null,$b$Aơ phung mât njrăng mpông pêr: Bơh phung noi Kôra, Y-Nêsêlêmia kon bu klâu Y-Kôrê, sau Y-Asap.$b$,true),
('bunong-vn','1CH',26,2,null,$b$Y-Nêsêlêmia, geh phung kon bu klâu: Y-Sakari, kon bôk rah, Y-Jêdiêl kon rơh bar, Y-Sêbadia kon rơh pe, Y-Jatniêl kon rơh puăn,$b$,false),
('bunong-vn','1CH',26,3,null,$b$Y-Êlam kon rơh prăm, Y-Jêhôhanan kon rơh prao, Y-Êliôhênai kon rơh pơh,$b$,false),
('bunong-vn','1CH',26,4,null,$b$Y-Ôbet-Êđôm geh phung kon bu klâu: Y-Sêmaya, kon bôk rah, Y-Jêhôsabat, kon rơh bar, Y-Jôa, kon rơh pe, Y-Sakar kon rơh puăn, Y-Nêthanel kon rơh prăm,$b$,false),
('bunong-vn','1CH',26,5,null,$b$Y-Amiêl kon rơh prao, Y-Isakar kon rơh pơh, Y-Pêulêthai kon rơh pham; yor lah Brah Ndu ăn nau ueh lăng ma păng.$b$,false),
('bunong-vn','1CH',26,6,null,$b$Tâm ban đŏng ma kon bu klâu păng Y-Sêmaya bu deh an âk kon bu klâu jêng kôranh ma noi deh khân păng nơm yor lah khân păng jêng phung bu klâu geh nau dơi ngăn.$b$,false),
('bunong-vn','1CH',26,7,null,$b$Phung kon bu klâu Y-Sêmaya: Y-Ôthni, Y-Rêphaêl, Y-Ôbet, jêh ri Y-Êlsabat; phung oh khân păng jêng Y-Êlihu jêh ri Y-Sêmakia jêng phung bu klâu geh nau dơi ngăn.$b$,true),
('bunong-vn','1CH',26,8,null,$b$Lĕ rngôch phung nây jêng phung kon sau Y-Ôbet-Êđôm da dê; ndrel ma phung kon bu klâu khân păng jêng phung geh nau dơi ngăn, dơi ƀư kan aơ; geh prao jât ma bar nuyh jêng noi deh Y-Ôbet-Êđôm.$b$,false),
('bunong-vn','1CH',26,9,null,$b$Y-Mêsêlêmia geh phung kon bu klâu jêh ri phung ndŭl mpôl, lĕ rngôch geh jât ma pham nuyh, jêng phung geh nau dơi ngăn da dê.$b$,true),
('bunong-vn','1CH',26,10,null,$b$Y-Hôsa bơh noi Y-Mêrari geh phung kon bu klâu: Y-Simri jêng kôranh (nđâp tơ lah păng mâu jêng kon dak bôk kđôi, mbơ̆ păng jêng păng kôranh),$b$,false),
('bunong-vn','1CH',26,11,null,$b$Y-Hilkia kon rơh bar, Y-Jêbalia kon rơh pe, Y-Sakari kon rơh puăn; lĕ rngôch phung kon bu klâu jêh ri ndŭl mpôl Y-Hôsa geh jât ma pe nuyh.$b$,false),
('bunong-vn','1CH',26,12,null,$b$Aơ jêng mbŭch mât njrăng mpông pêr geh kan tĭng nâm kôranh khân păng êng êng, nâm bu oh nâu khân păng geh jêh, pah kan tâm ngih Yêhôva.$b$,true),
('bunong-vn','1CH',26,13,null,$b$Khân păng ƀư nau tâm chroh tĭng nâm noi deh khân păng, bu mom tâm ban ma bu ranh tâm chroh da dê dơn mât njrăng mpông pêr.$b$,false),
('bunong-vn','1CH',26,14,null,$b$Nau tâm nchroh ma mpông pêr pa lơ di ma Y-Sêlêmia. Khân păng tâm nchroh ma mpông pêr mpeh dor di ma Y-Sakari, kon Y-Sêlêmia; du huê nchră geh nau gĭt mĭn.$b$,true),
('bunong-vn','1CH',26,15,null,$b$Nau tâm nchroh ma mpông pêr tâm rđŭng di ma Y-Ôbet-Êđôm, jêh ri bu jao ma kon bu klâu păng chiă uănh jay drăp.$b$,false),
('bunong-vn','1CH',26,16,null,$b$Nau tâm nchroh ma Y-Supim jêh ri Y-Hôsa di ma mpông pêr mpeh pa dâng, ta mpông per Salêket, ta trong hao klơ sop. Ntŭk gak aơ tâm tham đah ntŭk gak ri.$b$,false),
('bunong-vn','1CH',26,17,null,$b$Ăp nar geh prao nuyh phung Lêvi gak mpông pêr pa lơ, puăn nuyh gak mpông pêr mpeh dor, puăn nuyh gak mpông pêr tâm rđŭng jêh ri geh đŏng bar hê tâm ăp jay drăp, jay drăp aơ jêh ri jay drăp ri.$b$,false),
('bunong-vn','1CH',26,18,null,$b$Geh puăn nuyh gŭ ta gâng mpêr ta trong, jêh ri bar hê ta gâng nkual.$b$,false),
('bunong-vn','1CH',26,19,null,$b$Nây jêng mbŭch phung mât njrăng mpông pêr ta nklang phung Kôra jêh ri Y-Mêrari.$b$,false),
('bunong-vn','1CH',26,20,null,$b$Tâm phung Lêvi, mpôl khân păng mât mray drăp ngih Brah Ndu jêh ri drăp ndơ bu nhhơr.$b$,true),
('bunong-vn','1CH',26,21,null,$b$Phung kon bu klâu Y-Ladan, jêng noi mpôl phung Gersôn; kôranh noi deh ma mpôl Y-Landan, bunuyh Gersôn jêng Y-Jêhiêli$b$,false),
('bunong-vn','1CH',26,22,null,$b$Phung kon bu klâu Y-Jêhiêli jêng Y-Sêtham jêh ri oh păng Y-Jôel chiă drăp ngih Yêhôva.$b$,false),
('bunong-vn','1CH',26,23,null,$b$Tâm phung Amram, phung Ishar, phung Hêbron, jêh ri phung Usiêl.$b$,false),
('bunong-vn','1CH',26,24,null,$b$Geh Y-Sêbuêl kon bu klâu Y-Gersôm jêng noi mpôl Y-Môis, jêng kôranh toyh chiă drăp.$b$,true),
('bunong-vn','1CH',26,25,null,$b$Phung ndŭl mpôl păng: Bơh Y-Êliêser geh kon păng Y-Rêhabia, jêh ri kon păng Y-Jêsaya, jêh nây kon păng Y-Jôram kon păng Y-Sikri, kon păng Y-Sêlômôt,$b$,false),
('bunong-vn','1CH',26,26,null,$b$Y-Sêlômôt jêh ri phung oh nâu păng mât mray lĕ ntil drăp lĕ ntil ndơ nhhơr, Hađăch Đavit, phung kôranh ma ndŭl deh, phung kôranh ma du rbăn nuyh jêh ri phung kôranh ma du rhiăng nuyh, jêh ri phung kôranh ma phung ta han nhhơr jêh.$b$,false),
('bunong-vn','1CH',26,27,null,$b$Tă bơh ndơ pit in tâm nau tâm lơh khân păng nhhơr ma nau nkra ngih Yêhôva.$b$,false),
('bunong-vn','1CH',26,28,null,$b$Tâm ban đŏng lĕ rngôch ndơ nơm gĭt tâm saơ Y-Samuel, Y-Sôl kon bu klâu Y-Kis, Y-Apner, kon bu klâu Y-Ner, jêh ri Y-Jôap kon bu klâu Y-Sêruia nhhơr lĕ rngôch ndơ bu nhhơr jêh bu jao ma Y-Sêlômôt jêh ri phung Oh nâu păng chiă uănh.$b$,true),
('bunong-vn','1CH',26,29,null,$b$Tâm noi phung Ishar bu dơm Y-Kênania jêh ri phung kon bu klâu păng ma kan ƀon lan Israel, jêng kôranh chiă uănh jêh ri phung kôranh phat dôih.$b$,true),
('bunong-vn','1CH',26,30,null,$b$Tâm noi phung Hêbron, Y-Hasabia jêh ri phung oh nâu păng, du rbăn pơh rhiăng nuyh bu klâu geh nau dơi, jêng kôranh chiă uănh phung Israel mpeh pa dâng dak krong Yurdan tâm lĕ kan Yêhôva jêh ri kan hađăch.$b$,false),
('bunong-vn','1CH',26,31,null,$b$Bơh phung Hêbron, Y-Jêrija jêng kôranh ma phung Hêbron tă bơh mbu mpôl mâu lah noi deh păng. (Tâm năm rơh puăn jât Hađăch Đavit chiă uănh bu joi sek uănh jêh ri saơ phung bu klâu geh nau dơi toyh ta nklang khân păng ta ƀon Jaser tâm n'gor Galaat).$b$,false),
('bunong-vn','1CH',26,32,null,$b$Hađăch Đavit dơm păng jêh ri phung oh nâu păng, bar pơh rhiăng nuyh bu klâu geh nau dơi, kôranh ma noi deh khân păng, gay chiă uănh phung Ruben, phung Gat, jêh ri du n'gul mpôl Manasê tâm ăp ntil kan di ma Brah Ndu jêh ri ma kan hađăch.$b$,false),
('bunong-vn','1CH',27,1,null,$b$Aơ jêng săm ƀŭt chih amoh phung ƀon lan Israel, phung kôranh ma noi deh, kôranh ma du rbăn nuyh jêh ri du rhiăng nuyh jêh nây phung kôranh pah kan ma hađăch lĕ rngôch ntil tâm phung kan ta han; tĭng nâm mpôl lăp jêh ri luh ăp khay lĕ du năm, ăp mpôl geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,2,null,$b$Kôranh ma mpôl rơh nguay tâm khay rơh nguay jêng Y-Jasôbêam, kon bu klâu Y-Sap diêl; mpôl aơ geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,3,null,$b$Păng jêng kon sau Y-Pêres, jêng kôranh ma lĕ rngôch phung kôranh ta han tâm mpôl khay rơh nguay.$b$,false),
('bunong-vn','1CH',27,4,null,$b$Kôranh ma mpôl tâm khay rơh bar jêng Y-Dôdai; du huê Alôhi; Y-Miklôt jêng kôranh ma mpôl nây; mpôl aơ geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,5,null,$b$Kôranh ma mpôl tâm khay rơh pe jêng Y-Bênaya, kon bu klâu Y-Jêhôida, kôranh ƀư brah, jêng kôranh; mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,6,null,$b$Y-Bênaya jêng du huê janh ktang tâm pe jât nuyh nây jêh ri păng jêng kôranh ma phung pe jât nuyh nây; Y-Amisabat, kon bu klâu păng gĭt jêng kôranh tâm mpôl păng đŏng.$b$,false),
('bunong-vn','1CH',27,7,null,$b$Kôranh ma mpôl tâm khay rơh puăn jêng Y-Asahel, oh Y-Jôap; kon bu klâu păng jêng Y-Sêbadia ntrok jêh păng; mpôl ta han păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,8,null,$b$Kôranh ma mpôl tâm khay rơh prăm jêng Y-Samhut, du huê Isra; mpôl ta han păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,9,null,$b$Kôranh ma mpôl rơh prao tâm khay prao geh Y-Ira, kon bu klâu Y-Ikês bunuyh ƀon Têkôa; tâm mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,10,null,$b$Kôranh ma mpôl rơh pơh tâm khay pơh geh Y-Hêles păng jêng du huê phung noi Êphraim gŭ ta Pêlôn; tâm mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,11,null,$b$Kôranh ma mpôl rơh pham tâm khay pham geh Y-Sêbêkai jêng ndŭl mpôl Sêra gŭ ta Husa; mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,12,null,$b$Kôranh ma mpôl rơh sĭn geh Y-Ahiêser, gŭ ta Anathôt, du huê Benjamin; tâm mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,13,null,$b$Kôranh ma mpôl rơh jât tâm khay jât geh Y-Maharai gŭ ta ƀon Nêtôpha jêng mpôl Sêra; tâm mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,14,null,$b$Kôranh ma mpôl rơh jât ma nguay tâm khay jât ma nguay geh Y-Bênaya jêng mpôl Êphraim gŭ ta ƀon Pirathôn; mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,15,null,$b$Kôranh ma mpôl rơh jât ma bar tâm khay jât ma bar geh Y-Hêldai jêng ndŭl mpôl Y-Ôtniêl gŭ ta ƀon Nêtôphat; mpôl păng geh bar rmưn puăn rbăn nuyh.$b$,true),
('bunong-vn','1CH',27,16,null,$b$Phung chiă uănh nkual Israel: Ma phung Ruben geh Y-Êliêser kon bu klâu Y-Sikri jêng kôranh; Y-Sêphatia, kon bu klâu Y-Maka jêng kôranh ma ndŭl mpôl phung Simêôn;$b$,true),
('bunong-vn','1CH',27,17,null,$b$Y-Hasabia, kon bu klâu Y-Kêmuel chiă uănh phung Lêvi; Y-Sadôk chiă uănh kon sau Y-Arôn;$b$,false),
('bunong-vn','1CH',27,18,null,$b$Y-Êlihu, nâu Y-Đavit chiă uănh ndŭl mpôl phung Yuđa; Y-Ômri, kon bu klâu Y-Mikel chiă uănh ndŭl mpôl phung Isakar;$b$,false),
('bunong-vn','1CH',27,19,null,$b$Y-Ismaya, kon bu klâu Y-Ôbadia chiă uănh ndŭl mpôl phung Sabulôn; Y-Jêrêmôt, kon bu klâu Y-Asriêl chiă uănh ndŭl mpôl phung Naptali.$b$,false),
('bunong-vn','1CH',27,20,null,$b$Y-Hôsêa, kon bu klâu Y-Asasia chiă uănh ndŭl mpôl phung Êphraim; Y-Jôel, kon bu klâu Y-Pêdaya chiă uănh du n'gul ndŭl mpôl Manasê;$b$,true),
('bunong-vn','1CH',27,21,null,$b$Y-Idô, kon bu klâu Y-Sakari, chiă uănh du n'gul ndŭl mpôl Manasê tâm n'gor Galaat; Y-Jasiêl, kon bu klâu Y-Apner, chiă uănh ndŭl mpôl Benjamin;$b$,false),
('bunong-vn','1CH',27,22,null,$b$Y-Asarel, kon bu klâu Y-Jêrôham, chiă uănh ndŭl mpôl Dan. Nây phung kôranh chiă uănh noi mpôl Israel.$b$,false),
('bunong-vn','1CH',27,23,null,$b$Hađăch Đavit mâu kơp ôh phung tâm dâng bar jât năm, yor lah Yêhôva ton jêh Păng mra ƀư ăn phung Israel jêng bĭk rơ̆ nâm bu mănh klơ trôk.$b$,false),
('bunong-vn','1CH',27,24,null,$b$Y-Jôap kon bu klâu Y-Sêruia ntơm kơp ƀiă lah mâu dơi lôch ôh; yor lah kan nây nau Brah Ndu ji nuih tât ma phung Israel jêh ri păng mâu chih ôh amoh kơp tâm ndrom săm ƀŭt chih nau nkoch bri ma Hađăch Đavit.$b$,false),
('bunong-vn','1CH',27,25,null,$b$Y-Asmavet, kon bu klâu Y-Adiêl jêng kôranh mât uănh drăp hađăch; Y-Jônathan, kon bu klâu Y-Usia jêng kôranh mât uănh drăp tâm n'gor, tâm ƀon, tâm ƀon jê̆ jê̆; jêh ri ngih tŭm;$b$,true),
('bunong-vn','1CH',27,26,null,$b$jêh ri Y-Êsri, kon bu klâu Y-Kelup, jêng kôranh Chiă uănh phung pah kan kai mir,$b$,false),
('bunong-vn','1CH',27,27,null,$b$Y-Simei bunuyh Ramat jêng kôranh chiă uănh lôk mir play kriăk ƀâu; jêh ri Y-Sapdi du huê Sipa jêng kôranh chiă uănh play kriăk ƀâu bu pĕ jêh ri kĭn păt;$b$,false),
('bunong-vn','1CH',27,28,null,$b$Y-Baal-Hanan, bunuyh Gê der, jêng kôranh chiă uănh tơm si Ôlivơ jêh ri tơm si Sikamôr tâm n'gor Sêphêla; jêh ri Y-Jôas chiă uănh dak play Ôlivơ.$b$,false),
('bunong-vn','1CH',27,29,null,$b$Y-Sitrai du huê Sarôn, jêng kôranh chiăp uănh ndrôk phung rong tâm neh lâng Sarôn; Y-Saphat, kon bu klâu Y-Adlai jêng kôranh chiăp ndrôk tâm rlŭng.$b$,false),
('bunong-vn','1CH',27,30,null,$b$Y-Ôbil, du huê Ismaêl, jêng kôranh chiăp uănh seh samô; Y-Jêhdeyah, du huê Mêrônôt, jêng kôranh chiăp uănh seh bri me. Y-Jasis bunuyh Hagrit jêng kôranh chiăp uănh biăp, be.$b$,false),
('bunong-vn','1CH',27,31,null,$b$Lĕ rngôch phung nây jêng phung mât uănh drăp ndơ Hađăch Đavit.$b$,true),
('bunong-vn','1CH',27,32,null,$b$Y-Jônathan, Va Y-Đavit ƀư nơm nchră, yor lah păng jêng du huê bunuyh geh nau gĭt vât jêh ri du huê kôranh chih săm ƀŭt; Y-Jêhiêl kon bu klâu Y-Hachmôni rong phung kon bu klâu hađăch$b$,false),
('bunong-vn','1CH',27,33,null,$b$Y-Ahitôpel jêng kôranh nchră ma hađăch; jêh ri Y-Husai bunuyh Arkit jêng mĭt jiăng hađăch.$b$,false),
('bunong-vn','1CH',27,34,null,$b$Y-Jêhôida kon bu klâu Y-Bênaya jêh ri Y-Abiathar ntrok Y-Ahitôpel. Y-Jôap jêng kôranh toyh ma lĕ phung ta han hađăch.$b$,false),
('bunong-vn','1CH',28,1,null,$b$Hađăch Đavit rgum lĕ rngôch phung kôranh toyh phung Israel văch ta ƀon Yêrusalem: Phung kôranh chiă uănh ndŭl mpôl, phung kôranh ma du rbăn nuyh, kôranh mpôl pah kan ma hađăch, kôranh ma du rhiăng nuyh, phung kôranh mât uănh drăp ndơ jêh ri mpô mpa hađăch rong, phung kon bu klâu hađăch, phung kôranh chiă uănh ngih hađăch, phung ta han janh ktang, jêh ri lĕ rngôch phung blau tâm lơh.$b$,true),
('bunong-vn','1CH',28,2,null,$b$Hađăch Đavit dâk jêh ri ngơi: “Hơi phung oh nâu jêh ri phung ƀon lan gâp, rkêng tôr iăt hom: Nuih n'hâm gâp geh nau mĭn ndâk du mlâm ngih gay dơm hip nau tâm rnglăp Yêhôva, jêh ri jêng ntŭk chrong jâng Brah Ndu he; jêh ri gâp lĕ ndrăp jêh ndơ prăp ndâk ngih.$b$,false),
('bunong-vn','1CH',28,3,null,$b$Ƀiă lah Brah Ndu lah ma gâp, ‘May mâu dơi ndâk ôh du mlâm ngih ăn amoh gâp yor lah may jêng du huê tâm lơh hŏ ƀư ăn chah nting pling mham bu.’$b$,false),
('bunong-vn','1CH',28,4,null,$b$Ƀiă lah Yêhôva Brah Ndu Israel săch jêh gâp tă bơh rnăk vâl mbơ̆ gâp gay ƀư hađăch chiă uănh phung Israel n'ho ro; yor lah păng săch jêh ndŭl mpôl Yuđa hao chiă uănh, jêh ri bơh mpôl Yuđa Păng hŏ săch rnăk vâl mbơ̆ gâp jêh ri tă tâm nklang phung kon bu klâu mbơ̆ gâp, Păng hŏ maak đah gâp gay ŭch njêng gâp hađăch chiă uănh lĕ phung Israel.$b$,false),
('bunong-vn','1CH',28,5,null,$b$Tâm lĕ rngôch phung kon bu klâu gâp (yor lah Yêhôva ăn jêh ma gâp âk kon bu klâu) păng săch jêh Y-Salômôn kon bu klâu gâp ăn gŭ ta sưng hađăch ƀon bri hađăch Yêhôva chiă uănh phung Israel.$b$,false),
('bunong-vn','1CH',28,6,null,$b$Păng lah ma gâp, ‘Kon bu klâu may Y-Salômôn mra ndâk ngih gâp jêh ri nhuang ngih ăn ma gâp, yor lah gâp hŏ săch jêh păng ăn jêng kon bu klâu gâp, jêh ri gâp mra jêng mbơ̆ păng$b$,false),
('bunong-vn','1CH',28,7,null,$b$Gâp mra ƀư ăn nâp ƀon bri hađăch păng n'ho ro tơ lah păng ton djôt prăp nau gâp ntĭnh jêh ri nau vay gâp nâm bu bu ƀư nar aơ$b$,false),
('bunong-vn','1CH',28,8,null,$b$Yor nây aƀaơ ri ta năp lĕ rngôch phung Israel, phung Yêhôva tâm rƀŭn, jêh ri Brah Ndu he gŭ iăt, djôt prăp hom jêh ri tĭng kơt lĕ rngôch nau vay Yêhôva Brah Ndu khân may ntĭnh jêh; gay ma khân may dơi geh neh ueh aơ, jêh ri ăn tay ma kon sau khân may ô klak jêng drăp ndơn ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','1CH',28,9,null,$b$“Bi may, Hơi Y-Salômôn, kon bu klâu gâp, gĭt năl hom Brah Ndu mbơ̆ may, jêh ri pah kan hom ma păng ma lĕ nuih n'hâm jêh ri ma lĕ nau mĭn ŭch; yor lah Yêhôva sek uănh lĕ rngôch nuih n'hâm, jêh ri păng gĭt vât lĕ rngôch nau ŭch tâm nau mĭn. Tơ lah may joi păng, păng mra ăn may saơ păng; ƀiă lah tơ lah may cha lơi păng, păng mra mprơh may n'ho ro.$b$,true),
('bunong-vn','1CH',28,10,null,$b$Njrăng hom aƀaơ ri, yor lah Yêhôva săch jêh may ăn may ndâk du mlâm ngih prăp ma jrô kloh ueh; jêng ktang hom, jêh ri ƀư nau nây.”$b$,false),
('bunong-vn','1CH',28,11,null,$b$Hađăch Đavit ăn ma Y-Salômôn, kon bu klâu păng, sămƀŭt rup ndring ngih brah, jêh ri rplay ngih êng êng prăp ma ngih brah, jrô drăp ndơ ngih brah, jrô klơ, jrô tâm trôm, jêh jrô prăp ntŭk yô̆ an;$b$,true),
('bunong-vn','1CH',28,12,null,$b$jêh ri rup ma lĕ rngôch nau mĭn di ma nhuang ngih Yêhôva, lĕ rngôch jrô văr jŭm, jrô drăp ndơ ngih Brah Ndu, jêh ri jrô drăp ndơ prăp ndơ bu nhhơr;$b$,false),
('bunong-vn','1CH',28,13,null,$b$ma mbŭch mpôl kôranh ƀư brah jêh ri phung Lêvi, tâm lĕ rngôch kan bu ƀư tâm ngih Yêhôva; ma lĕ rngôch khăl ngan prăp ma kan tâm ngih Yêhôva,$b$,false),
('bunong-vn','1CH',28,14,null,$b$njing jâk mah ma lĕ rngôch khăl ngan ƀư ma mah prăp ma kan, njing jâk prăk ma khăl ngan prăp ma kan;$b$,false),
('bunong-vn','1CH',28,15,null,$b$njing jâk jâng jrêng mah ndrel ma ŭnh kađen khân păng, njing jâk mah tâm ăp mlâm jâng jrêng jêh ri ŭnh kađen păng, njing jâk prăk ma du mlâm jâng jrêng jêh ri ndrel ma ŭnh kađen păng, tĭng nâm bu dŏng ăp mlâm jâng jrêng tâm kan,$b$,false),
('bunong-vn','1CH',28,16,null,$b$njing jâk mah ăp mlâm sưng prăp ma piăng let nhhơr ma Brah Ndu, prăk ma sưng prăk,$b$,false),
('bunong-vn','1CH',28,17,null,$b$jêh ri mah chrêk ăn ma n'hoi njraih, ngan grưng, jêh ri kachok; ăn ma ngan rlŭ mah jêh ri njing jâk ăp mlâm;$b$,false),
('bunong-vn','1CH',28,18,null,$b$ma nơng su ndơ ƀâu kah bu ƀư ma mah chrêk, jêh ri njing jâk mah nây; tâm ban đŏng păng geh rup ma ndeh seh mah phung chêrubim lĭ nting năr khân păng nkŭm hip nau tâm rnglăp Yêhôva.$b$,false),
('bunong-vn','1CH',28,19,null,$b$Hađăch Đavit ngơi: “Lĕ rngôch kan bu mra ƀư tĭng nâm săm ƀŭt rup nây; tâm mpơl rah vah lĕ nau nây tĭng nâm ti Yêhôva chih.”$b$,false),
('bunong-vn','1CH',28,20,null,$b$Hađăch Đavit lah ma Y-Salômôn kon bu klâu păng, “Jêng ktang hom jêh ri lơi klach ôh ƀư nau nây. Lơi klach ôh, lơi rdja nuih ôh; yor lah Yêhôva Brah Ndu, jêng Brah Ndu gâp, gŭ ndrel ma may, Păng mâu mra roh hêng ôh nau kơl may, mâu lah mâu lĕ cha lơi may, ăn tât dơi jêh lĕ rngôch kan ngih Yêhôva.$b$,true),
('bunong-vn','1CH',28,21,null,$b$Aơ, mpôl phung kôranh ƀư brah jêh ri phung Lêvi prăp ma lĕ rngôch kan tâm ngih Brah Ndu; jêh ri ăp nơm bu klâu blau kan geh nau ŭch mra gŭ ndrel ma may; tâm ban đŏng phung kôranh chiă uănh jêh ri lĕ rngôch phung ƀon lan mra tông ma may da dê.$b$,false),
('bunong-vn','1CH',29,1,null,$b$Hađăch Đavit lah ma lĕ rngôch phung tâm rƀŭn, “Kon bu klâu gâp Y-Salômôn, knŏng êng păng Brah Ndu hŏ săch jêh, jêng ndăm jêh ri ê hŏ rgăn ôh âk nau tât, jêh ri kan jêng toyh. Yor lah ngih hađăch mâu di prăp ma bunuyh ôh, ƀiă lah mra prăp ma Yêhôva Brah Ndu.$b$,true),
('bunong-vn','1CH',29,2,null,$b$Pô ri gâp joi ăn geh ma ngih Brah Ndu gâp tĭng nâm gâp dơi; mah prăp ma ndơ ƀư đah mah, prăk prăp ma ndơ ƀư đah prăk, kông prăp ma ndơ ƀư đah kông, loih prăp ma ndơ ƀư đah loih, tơm si prăp ma ndơ ƀư đah tơm si, ndrel ma âk ngăn lŭ ônik jêh ri lŭ prăp rli lŭ muy tâm pot đah mah, kông lŭ geh âk ntil dak, ăp ntil lŭ khay jêh ri lŭ marbrơ.$b$,false),
('bunong-vn','1CH',29,3,null,$b$Rmeh ma nây gay ŭch ntop tay ma lĕ rngôch ndơ gâp hŏ geh jêh prăp ma ngih kloh ueh, gâp lĕ geh jêh drăp ndơ gâp nơm mah jêh ri prăk, yor lah gâp rŏng ma ngih Brah Ndu gâp, gâp ăn ndơ nây ma ngih Brah Ndu gâp$b$,false),
('bunong-vn','1CH',29,4,null,$b$pe rbăn talâng mah tă bơh n'gor Ôphir, pơh rbăn talâng prăk chrêk prăp mblum mpir ngih,$b$,false),
('bunong-vn','1CH',29,5,null,$b$jêh ri prăp ma lĕ rngôch kan phung blau kan mra ƀư, mah prăp ma ndơ ƀư đah mah jêh ri prăk prăp ma ndơ ƀư đah prăk. Pô nây mbu nơm ŭch nhhơr păng nơm prăp an ma Yêhôva nar aơ?”$b$,false),
('bunong-vn','1CH',29,6,null,$b$Nôk nây phung kôranh chiă uănh mpôl, kôranh chiă uănh noi deh, phung Israel, phung kôranh ma du rbăn nuyh, kôranh ma du rhiăng nuyh, jêh ri phung kôranh toyh chiă uănh kan hađăch ma nau maak nhhơr ndơ da dê.$b$,true),
('bunong-vn','1CH',29,7,null,$b$Khân păng nhhơr ma nau kan nkra ndâk ngih Brah Ndu: Prăm rbăn talâng jêh ri du rmưn darik mah, du rmưn talâng prăk, du rmưn pham rbăn talâng kông, jêh ri du rsen talâng loih.$b$,false),
('bunong-vn','1CH',29,8,null,$b$Mbu nơm geh lŭ khlay ăn đŏng ma jrô prăp drăp ngih Yêhôva, Y-Jêhiêl bunuyh Gersôn jêng nơm chiă uănh ndơ nây.$b$,true),
('bunong-vn','1CH',29,9,null,$b$Pô ri phung ƀon lan hâk răm ngăn yor lah phung nây ăn jêh ma nuih n'hâm ŭch, yor lah khân păng ma lĕ nuih n'hâm nhhơr ma Yêhôva; Hađăch Đavit bêng ma nau răm maak tâm ban đŏng.$b$,false),
('bunong-vn','1CH',29,10,null,$b$Yor nây Hađăch Đavit mât Ton ma Yêhôva tra năp lĕ rngôch phung tâm rƀŭn; jêh ri lah: “Mât ton ma may, Hơi Yêhôva, Brah Ndu Israel chô che hên ƀa ƀơ n'ho ro!$b$,true),
('bunong-vn','1CH',29,11,null,$b$Hơi Yêhôva, May toyh ngăn, nau brah ngăn; nau chrêk ma lơp, nau dơi jêh ri nau hit ra nam; Hơi Yêhôva, yor lah lĕ rngôch klơ trôk tâm neh ntu jêng ndơ may da dê; jêh ri Ƀon Bri Hađăch jêng ndơ may, jêh ri hên yơk ma may jêng kôranh ta klơ lĕ rngôch.$b$,true),
('bunong-vn','1CH',29,12,null,$b$Nđâp nau ndrŏng kuăng jêh ri nau yơk tă luh bơh may Jêh ri may chiă uănh ta klơ lĕ rngôch. Tâm ti may geh nau brah jêh ri nau ktang; ma ti may ƀư ăn bu dơi toyh jêh ri ăn nau ktang n'hâm suan ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','1CH',29,13,null,$b$Aƀaơ ri, Hơi Brah Ndu hên, Hên tâm rnê ma may, jêh ri mât ton ma amoh chrêk rmah may.$b$,false),
('bunong-vn','1CH',29,14,null,$b$“Ƀiă lah mbu gâp jêng? Jêh ri mbu phung ƀon lan gâp jêng dĭng hên dơi nhhơr ma nuih n'hâm ŭch tâm ban pô aơ? Yor lah lĕ rngôch ndơ tă luh bơh may, jêh ri hên nhhơr ma may ndơ may nơm.$b$,false),
('bunong-vn','1CH',29,15,null,$b$Yor lah ta năp măt may, hên jêng phung bu năch jêh ri phung gŭ njơh ƀât lât, nâm bu lĕ rngôch phung chô che hên kăl e; rô̆ hên gŭ rêh ta neh ntu nâm bu gui, jêh ri mâu geh ôh nau kâp gân.$b$,false),
('bunong-vn','1CH',29,16,null,$b$Hơi Yêhôva, Brah Ndu hên, lĕ rngôch ndơ rmeh ler hên geh jêh aƀaơ gay ŭch ndâk du mlâm ngih ma Amoh Kloh Ueh may tă luh bơh ti may nơm, jêh ri lĕ rngôch jêng ndơ may nơm đŏng.$b$,true),
('bunong-vn','1CH',29,17,null,$b$Hơi Brah Ndu gâp, gâp gĭt jêh may sek uănh nuih n'hâm bunuyh, jêh ri rŏng ma nau sŏng srăng; ma nuih n'hâm sŏng gâp nhhơr jêh mâu geh bu nchâp lĕ rngôch ndơ aơ. Aƀaơ ri gâp saơ jêh phung ƀon lan may gŭ ta aơ ma nau răm rhơn nhhơr ma may.$b$,false),
('bunong-vn','1CH',29,18,null,$b$Hơi Yêhôva, Brah Ndu Y-Abraham, Y-Isăk, jêh ri Y-Israel phung chô che hên, ăn djôt prăp mro nau ton, nau mĭn nây tâm nuih n'hâm phung ƀon lan may, May gai ƀa ƀơ jêh ri gay ăn djôt prăp nuih n'hâm khân păng mpeh ma may.$b$,false),
('bunong-vn','1CH',29,19,null,$b$Ăn ma Y-Salômôn, kon bu klâu gâp, lĕ nuih n'hâm dơi djôt prăp nau may ntĭnh, nau may mbơh, jêh ri nau vay may, dơi ƀư nŭm, jêh ri gay ma păng dơi ndâk ngih brah, lĕ ndơ ƀư gâp hŏ ndrăp nŭm jêh.”$b$,true),
('bunong-vn','1CH',29,20,null,$b$Nôk nây, Hađăch Đavit lah ma lĕ rngôch phung tâm rƀŭn, “Aƀaơ ri, mât ton hom ma Yêhôva Brah Ndu khân may.” Jêh ri lĕ rngôch phung tâm rƀŭn mât ton ma Yêhôva Brah Ndu phung chô che khân păng; Khân păng kŭnh bôk jêh ri chon mbah ma Yêhôva, jêh ri mbah ma hađăch.”$b$,true),
('bunong-vn','1CH',29,21,null,$b$Nar pa kơi nây, khân păng nhhơr ndơ ƀư brah jêh ri ndơ nhhơr gŭch ma Yêhôva du rbăn mlâm ndrôk nkuăng, jêh ri du rbăn mlâm biăp kon, ndrel ma ndơ nhhơr nhêt, jêh ri ndơ ƀư brah mbêng ler yor lĕ rngôch phung Israel;$b$,false),
('bunong-vn','1CH',29,22,null,$b$jêh ri khân păng nhêt sa ta năp Yêhôva nar nây ma nau răm maak ngăn. Nôk nây, du tơ̆ tay đŏng khân păng n'hao ăn Y-Salômôn, kon bu klâu Y-Đavit hao ƀư hađăch; khân păng tŏ dak ƀâu kah ma păng ta năp măt Yêhôva gay chiă uănh jêh ri tŏ dak ƀâu kah ăn Y-Sadôk jêng kôranh ƀư brah.$b$,false),
('bunong-vn','1CH',29,23,null,$b$Pô nây, Y-Salômôn gŭ ta sưng hađăch Yêhôva, ƀư hađăch ntrok Y-Đavit mbơ̆ păng; jêh ri păng dơi chăt hao, lĕ rngôch phung Israel tông ma păng.$b$,true),
('bunong-vn','1CH',29,24,null,$b$Lĕ rngôch phung kôranh, jêh ri phung ta han dăng ktang, ndrel ma phung kon bu klâu Hađăch Đavit đŏng mra ton khân păng tông bâr Hađăch Salômôn da dê.$b$,false),
('bunong-vn','1CH',29,25,null,$b$Yêhôva ăn ma Y-Salômôn nau lư n'găr toyh ta năp măt lĕ rngôch phung Israel, jêh ri ăn ma păng nau rnam khư ma hađăch, mâu mâp geh ôh tâm ban pô nây ma phung hađăch lor pa năp păng tâm n'gor Israel.$b$,false),
('bunong-vn','1CH',29,26,null,$b$Pô ri Y-Đavit, kon bu klâu Y-Yêsê chiă uănh jêh lĕ rngôch phung Israel.$b$,true),
('bunong-vn','1CH',29,27,null,$b$Nôk păng chiă uănh phung Israel geh puăn jât năm; păng chiă uănh pơh năm ta ƀon Hêbron, jêh ri pe jât năm tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','1CH',29,28,null,$b$Jêh ri păng khĭt ranh jŏk rêh; geh nau ndrŏng, geh nau bu yơk; jêh ri Y-Salômôn, kon bu klâu păng, chiă uănh ntrok păng.$b$,false),
('bunong-vn','1CH',29,29,null,$b$Kan Hađăch Đavit bơh ntơm sa ơm tât lôch bu chih jêh tâm ndrom sămƀŭt Nau Y-Samuel nơm gĭt tâm saơ Nkoch Bri, jêh ri tâm ndrom sămƀŭt Nau Nkoch Bri Y-Nathan, kôranh nơm mbơh lor, jêh ri tâm ndrom sămƀŭt Y-Gat, nơm gĭt tâm saơ Nkoch Bri,$b$,false),
('bunong-vn','1CH',29,30,null,$b$geh nau Chih prăp lĕ kan păng chiă uănh, nau ktang păng, jêh ri nau tât ma păng jêh nây ma phung Israel, jêh ri ma lĕ rngôch ƀon bri hađăch phung bri dak êng.$b$,false);
